    // Each package's identity and module ID, and the fingerprint of its module.
    package_names: string[] = [];
    package_ids: uint64[] = [];
    for (listed in packages) {
        package_names.append(documents[files_of[listed.member_start]].identity);
        package_ids.append(binding.ID("module", package_names[length(package_names) - 1]));
    }
    fingerprints := resize([uint64(0)], length(packages));
    data: byte[] = [];
    starts := resize([int(0)], length(packages));
    lengths := resize([int(0)], length(packages));
    for (package in order) {
        switch Assemble(forest, documents, package, files_of[packages[package].member_start], package_names,
                        package_ids, fingerprints,
                        Reachable(edges, length(packages), package), links, callables, params, types, members, constants,
                        natives, ports, identities, ops, target, abi, Game.Package) {
            case .Rejected(diagnostic):
                return Result.Rejected(diagnostic);
            case .Compiled(module, bytes):
                // Only an importer reads a fingerprint, and none imports the root.
                if (package != root) {
                    fingerprints[package] = writer.Fingerprint(bytes);
                }
                starts[package] = length(data);
                lengths[package] = length(bytes);
                data.extend(bytes);
        }
    }
    return Result.Compiled(package_ids[root],
                           writer.Closure(package_ids[root], package_ids, package_names, data, starts, lengths));
}
// The prepared module of package `package`, or of a behavior, whose
// functions are its handlers; its bytes are the Compiled result's. Each body
// is a canonical definition the runtime verifies and finalizes when it loads
// it.
// `constants`, each another package's taking the occurrence of the first use
// in package `package`, where stage zero declares its symbol.
UsedConstants :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], links: graph.Binding[],
                  callables: Callable[], constants: ConstDecl[], package: int, first_own: int,
                  reachable: bool[]) -> ConstDecl[] {
    // Only a package this one imports declares a constant it can use.
    foreign := false;
    for (constant in constants) {
        foreign = foreign || (constant.package != package && reachable[constant.package]);
    }
    if (!foreign) {
        return constants;
    }
    seen := resize([false], length(constants));
    firsts := resize([uint64(0)], length(constants));
    solid: int[] = [];
    solid_document: int = -1;
    index := first_own;
    while (index < length(callables) && callables[index].package == package) {
        document := callables[index].document;
        text := documents[document].text;
        if (document != solid_document) {
            solid = SolidOffsets(text);
            solid_document = document;
        }
        aliases := Aliases(links, document);
        // The body's nodes in source order.
        pending: int[] = [Field(forest, callables[index].node, "body")];
        while (length(pending) > 0) {
            node := pending[length(pending) - 1];
            pending = slice(pending, 0, length(pending) - 1);
            found: int = -1;
            if (Is(forest, node, "member_expression")) {
                found = ConstantOf(forest, text, constants, aliases, package, node);
            }
            if (found >= 0 && constants[found].package != package && !seen[found]) {
                seen[found] = true;
                firsts[found] = Occurrence(documents[document].key, SymbolRecord, solid[forest[node].start],
                                           solid[forest[node].end]);
            }
            children: int[] = [];
            child := forest[node].first_child;
            while (child >= 0) {
                children.append(child);
                child = forest[child].next_sibling;
            }
            at_child := length(children) - 1;
            while (at_child >= 0) {
                pending.append(children[at_child]);
                at_child -= 1;
            }
        }
        index += 1;
    }
    used: ConstDecl[] = [];
    at: int = 0;
    while (at < length(constants)) {
        occurrence := constants[at].occurrence;
        if (seen[at]) {
            occurrence = firsts[at];
        }
        first: ConstDecl = {name: constants[at].name, package: constants[at].package, storage: constants[at].storage,
                            bits: constants[at].bits, node: constants[at].node, file: constants[at].file,
                            folded: constants[at].folded, occurrence: occurrence};
        used.append(first);
        at += 1;
    }
    return used;
}
Assemble :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], package: int, first_document: int,
             package_names: string[], package_ids: uint64[], fingerprints: uint64[], reachable: bool[],
             links: graph.Binding[], callables: Callable[], params: Param[], types: TypeDecl[],
             members: TypeMember[], constants: ConstDecl[], natives: Native[], ports: Port[],
             identities: uint64[], ops: Ops, target: Target, abi: uint64, game: Game) -> Result {
    identity := package_names[package];
    module := package_ids[package];
    // A behavior's states, the event each of its functions handles, the
    // game's events and the type of the entity that owns it.
    kept_states: StateDecl[] = [];
    handled: int[] = [];
    game_events: GameEvent[] = [];
    game_fields: GameEventField[] = [];
    owner_type: uint64 = 0;
    behaving: Name[] = [];
    aggregates: NumericOperator[] = [];
    record_makes: NativeMake[] = [];
    make_fields: int[] = [];
    switch game {
        case .Package:
            owner_type = 0;
        case .Behavior(declared_states, handlers, declared_events, payloads, entity, operators, globals, makes,
                       made_fields):
            kept_states = declared_states;
            handled = handlers;
            game_events = declared_events;
            game_fields = payloads;
            owner_type = entity;
            behaving = BehaviorNames(declared_states, globals);
            aggregates = operators;
            record_makes = makes;
            make_fields = made_fields;
    }
    wide: uint64[] = [0];
    values: writer.Value[] = [];
    ints: int[] = [];
    spans: writer.Span[] = [];
    functions: writer.Function[] = [];
    instructions: writer.Instruction[] = [];
    locals: writer.Local[] = [];
    parameters: writer.Parameter[] = [];
    frames: writer.Frame[] = [];
    sources: writer.Source[] = [];
    data: writer.Data[] = [];
    hosts: writer.Host[] = [];
    roots: writer.Root[] = [];
    calls: writer.Call[] = [];
    references: writer.Reference[] = [];
    components: writer.Component[] = [];
    entries: writer.Entry[] = [];
    requirements: writer.Requirement[] = [];
    fields: writer.Field[] = [];
    // Each record's layout and each variant's tag, as indices into `wide`, for
    // the types of this package and those it reaches; no others can occur.
    layouts: int[] = [];
    tags: int[] = [];
    for (declared in types) {
        layouts.append(int(0));
        tags.append(int(0));
        if (!reachable[declared.package]) {
            continue;
        }
        if (declared.kind == VariantDecl) {
            // Stage zero's tag: the union's ID in decimal, then the variant.
            union_id := binding.ID("package-symbol",
                                   format_text("{}:{}:{}", package_names[declared.package], TypeKind, types[declared.parent].name));
            wide.append(binding.ID("union-variant", format_text("{}:{}", union_id, declared.name)));
            tags[length(tags) - 1] = length(wide) - 1;
        } else if (declared.kind == RecordDecl) {
            wide.append(binding.ID("package-symbol",
                                   format_text("{}:{}:{}", package_names[declared.package], TypeKind, declared.name)));
            wide.append(LayoutHash(declared, members, target));
            layouts[length(layouts) - 1] = length(wide) - 1;
            requirement: writer.Requirement = {id: length(wide) - 2, layout: length(wide) - 1, storage: StructStorage,
                                               name: declared.type_name, size: declared.size, authored: true, first: length(fields),
                                               count: declared.count};
            requirements.append(requirement);
            at := declared.first;
            while (at < declared.first + declared.count) {
                // Record fields are integers, bools or strings, so none names a type or unit.
                field: writer.Field = {name: members[at].name, kind: members[at].storage, type_name: "",
                                       has_type_name: false, unit: "", has_unit: false};
                fields.append(field);
                at += 1;
            }
        } else if (declared.kind == NativeDecl) {
            wide.append(declared.id);
            wide.append(declared.layout);
            layouts[length(layouts) - 1] = length(wide) - 1;
            requirement: writer.Requirement = {id: length(wide) - 2, layout: length(wide) - 1, storage: declared.storage,
                                               name: declared.type_name, size: declared.size, authored: false, first: 0,
                                               count: 0};
            requirements.append(requirement);
        }
    }
    abi_one := length(wide);
    wide.append(uint64(1));
    // A package's functions are contiguous; the module numbers them from 0.
    first_own: int = 0;
    while (first_own < length(callables) && callables[first_own].package != package) {
        first_own += 1;
    }
    used := UsedConstants(forest, documents, links, callables, constants, package, first_own, reachable);
    // The packages this module calls into, each an import row.
    imported: int[] = [];
    imports: writer.Import[] = [];
    points: writer.Point[] = [];
    watches: writer.Watch[] = [];
    // Only a package that calls a ref parameter keeps locals in data cells.
    referencing := AnyReference(params);
    // Debugger points count each document's bytes that are not whitespace.
    solid: int[] = [];
    solid_document: int = -1;
    // A symbol the source declares nowhere spans the package's first
    // document, as stage zero gives it that document's unset range.
    first_solid := SolidOffsets(documents[first_document].text);
    undeclared := OccurrenceIn(DocumentHash(documents[first_document].key), SymbolRecord, 0,
                               first_solid[length(first_solid) - 1]);
    index := first_own;
    while (index < length(callables) && callables[index].package == package) {
        callable := callables[index];
        if (callable.document != solid_document) {
            solid = SolidOffsets(documents[callable.document].text);
            solid_document = callable.document;
        }
        handler: int = -1;
        if (index - first_own < length(handled)) {
            handler = handled[index - first_own];
        }
        // A function's points mean the event it handles, or the function.
        meaning := binding.ID("package-symbol", format_text("{}:{}:{}:callable", identity, FunctionKind, callable.name));
        if (handler >= 0) {
            meaning = game_events[handler].id;
        } else if (owner_type != 0) {
            meaning = binding.ID("symbol", format_text("{}:1:{}:callable", identity, callable.name));
        }
        aliases := extend(Aliases(links, callable.document), behaving);
        // The names a ref argument reaches live in data cells.
        referenced: string[] = [];
        if (referencing) {
            referenced = ReferencedNames(forest, documents[callable.document].text, callables, params, aliases, package,
                                         Field(forest, callable.node, "body"));
        }
        mutated := MutatedNames(forest, documents[callable.document].text, Field(forest, callable.node, "body"),
                                referenced);
        // A function with one result builds the arrays it returns in its
        // caller's storage.
        built: int[] = [];
        if (callable.results == 0) {
            built = BuiltLocals(forest, documents[callable.document].text, types, aliases, callable.package,
                                Field(forest, callable.node, "body"), referenced);
        }
        tables := EmitBody(forest, documents[callable.document].text, callable.document, callables, params,
                           types, members, used, natives, ports, identities, aggregates, record_makes, make_fields,
                           aliases, documents[callable.document].key, solid, undeclared, meaning, index, referenced,
                           mutated, built, ops, target);
        switch tables {
            case .Failed(diagnostic):
                return Result.Rejected(diagnostic);
            case .Emitted(body_slots, body_locals, body_cells, body_code, body_calls, body_hosts, body_roots,
                          body_points, body_watches):
                base := length(spans);
                // Argument defaults and kinds.
                spans.append(Range(length(values), callable.count));
                at: int = 0;
                while (at < callable.count) {
                    values.append(ParamHeader(params[callable.first + at], types, layouts, target));
                    at += 1;
                }
                spans.append(Range(length(ints), callable.count));
                at = 0;
                while (at < callable.count) {
                    kind: int = 0;
                    if (params[callable.first + at].reference) {
                        kind = ReferenceKind;
                    }
                    ints.append(kind);
                    at += 1;
                }
                // Result defaults and kinds: the one result, or each named one.
                result_count := callable.results;
                if (callable.result != 0) {
                    result_count = 1;
                }
                spans.append(Range(length(values), result_count));
                if (callable.result != 0) {
                    values.append(Header(callable.result, callable.result_container, callable.result_record,
                                         types, layouts));
                }
                at = 0;
                while (at < callable.results) {
                    named := params[callable.first + callable.count + at];
                    values.append(ScalarValue(named.storage, 0));
                    at += 1;
                }
                spans.append(Range(length(ints), result_count));
                at = 0;
                while (at < result_count) {
                    ints.append(int(0));
                    at += 1;
                }
                // A behavior's states are each function's variables.
                spans.append(Range(length(values), length(kept_states)));
                for (kept in kept_states) {
                    values.append(ScalarValue(kept.storage, length(wide)));
                    wide.append(kept.bits);
                }
                spans.append(Range(length(ints), length(body_slots)));
                for (slot in body_slots) {
                    ints.append(slot.storage);
                }
                spans.append(Range(length(ints), length(body_slots)));
                for (slot in body_slots) {
                    ints.append(slot.kind);
                }
                // Record and array pointers each slot may hold while the function waits.
                spans.append(Range(length(roots), length(body_roots)));
                for (root in body_roots) {
                    values.append(Header(root.storage, root.container, root.record, types, layouts));
                    row: writer.Root = {bank: 0, index: root.slot, shape: length(values) - 1};
                    roots.append(row);
                }
                // Instructions, each with its own value row and source at pc + 1.
                spans.append(Range(length(instructions), length(body_code)));
                pc: int = 0;
                for (code in body_code) {
                    value := Header(code.value_storage, code.value_container, code.value_record, types, layouts);
                    if (code.has_text) {
                        value.text = code.text;
                        value.has_text = true;
                    }
                    if (code.payload != 0) {
                        value.wide = length(wide);
                        wide.append(code.payload);
                    }
                    values.append(value);
                    row: writer.Instruction = {op: code.op, type: code.type, output: code.output,
                                               left: code.left, right: code.right, target: code.target, frame: 0, source: pc + 1,
                                               stack: -1, pin: 0, offset: code.offset, indirect: false, component_index: 0, node: 0,
                                               value: length(values) - 1, layout: 0, message: code.message, has_message: code.has_message};
                    instructions.append(row);
                    pc += 1;
                }
                spans.append(Range(length(locals), length(body_locals)));
                for (body_local in body_locals) {
                    values.append(ScalarValue(body_local.storage, 0));
                    local: writer.Local = {kind: body_local.kind, initial: length(values) - 1, frame: 0, node: 0, pin: 0,
                                           offset: 0, parameter: false, array_default: false, data_index: 0};
                    locals.append(local);
                }
                spans.append(Range(length(parameters), callable.count));
                at = 0;
                while (at < callable.count) {
                    values.append(ParamHeader(params[callable.first + at], types, layouts, target));
                    parameter: writer.Parameter = {initial: length(values) - 1, frame: 0, pin: 0};
                    parameters.append(parameter);
                    at += 1;
                }
                // One frame with an empty origin, then the instruction origins.
                sources.append(NoSource());
                frame: writer.Frame = {source: length(sources) - 1, depth: 0, resume: 0, source_index: 0, stack: -1};
                spans.append(Range(length(frames), 1));
                frames.append(frame);
                spans.append(Range(length(sources), length(body_code) + 1));
                sources.append(NoSource());
                asset := documents[callable.document].key;
                for (code in body_code) {
                    source := NoSource();
                    source.asset = asset;
                    source.has_asset = true;
                    source.start = code.start;
                    source.end = code.end;
                    source.line = code.line;
                    source.column = code.column;
                    sources.append(source);
                }
                spans.append(Range(0, 0));
                spans.append(Range(0, 0));
                // Data cells: record cells own a buffer of the record's size;
                // others may hold a constant or a variant's tag.
                spans.append(Range(length(data), length(body_cells)));
                for (cell in body_cells) {
                    value := Header(cell.storage, cell.container, cell.record, types, layouts);
                    size: int = 0;
                    if (cell.storage == StructStorage && cell.container == 0) {
                        size = types[cell.record].size;
                    }
                    if (cell.variant >= 0) {
                        value.wide = tags[cell.variant];
                    } else if (cell.constant != 0) {
                        value.wide = length(wide);
                        wide.append(cell.constant);
                    }
                    values.append(value);
                    datum: writer.Data = {kind: cell.kind, initial: length(values) - 1, size: size};
                    data.append(datum);
                }
                spans.append(Range(length(hosts), length(body_hosts)));
                for (host in body_hosts) {
                    capability := length(wide);
                    host_abi := abi_one;
                    if (host.linked >= 0) {
                        wide.append(identities[2 * host.linked]);
                        wide.append(identities[2 * host.linked + 1]);
                        host_abi = capability + 1;
                    } else {
                        wide.append(IntrinsicBase | uint64(host.intrinsic));
                    }
                    row: writer.Host = {capability: capability, abi: host_abi, first: host.first,
                                        result_first: host.result_first, result_count: host.result_count, outcome_first: 0,
                                        outcome_count: 0};
                    hosts.append(row);
                }
                spans.append(Range(length(calls), length(body_calls)));
                for (invocation in body_calls) {
                    callee := callables[invocation.callee];
                    if (callee.package == package) {
                        references.append(Own(invocation.callee - first_own));
                    } else {
                        row := Position(imported, callee.package);
                        if (row < 0) {
                            imported.append(callee.package);
                            wide.append(package_ids[callee.package]);
                            wide.append(fingerprints[callee.package]);
                            dependency: writer.Import = {id: length(wide) - 2, fingerprint: length(wide) - 1};
                            imports.append(dependency);
                            row = length(imports) - 1;
                        }
                        wide.append(binding.ID("package-symbol",
                                               format_text("{}:{}:{}:callable", package_names[callee.package], FunctionKind, callee.name)));
                        foreign: writer.Reference = {imported: row, own: 0, function: length(wide) - 1, role: 0};
                        references.append(foreign);
                    }
                    call: writer.Call = {function: length(references) - 1, first: invocation.first,
                                         count: invocation.count, result_first: invocation.result_first,
                                         result_count: invocation.result_count, task: false};
                    calls.append(call);
                }
                // No definitions; then the components the body reads or
                // writes through references, each once, and each write.
                spans.append(Range(0, 0));
                written := ComponentsOf(body_cells, body_hosts, true);
                reached := Distinct(ComponentsOf(body_cells, body_hosts, false));
                spans.append(Range(length(components), length(reached)));
                for (component_id in reached) {
                    reached_row: writer.Component = {id: length(wide), binding: false};
                    components.append(reached_row);
                    wide.append(component_id);
                }
                spans.append(Range(length(ints), length(written)));
                for (component_id in written) {
                    ints.append(length(wide));
                    wide.append(component_id);
                }
                spans.append(Range(length(points), length(body_points)));
                for (point in body_points) {
                    wide.append(point.occurrence);
                    wide.append(point.meaning);
                    row: writer.Point = {occurrence: length(wide) - 2, meaning: length(wide) - 1, start: point.start,
                                         end: point.end, line: point.line, column: point.column, kind: point.kind,
                                         completion: point.completion};
                    points.append(row);
                }
                // Each watch's origin is a point of its own, past the
                // function's points, and its initial value the type's header.
                spans.append(Range(length(watches), length(body_watches)));
                for (watched in body_watches) {
                    wide.append(watched.occurrence);
                    wide.append(uint64(0));
                    origin: writer.Point = {occurrence: length(wide) - 2, meaning: length(wide) - 1,
                                            start: watched.start, end: watched.end, line: watched.line,
                                            column: watched.column, kind: ExpressionRecord, completion: false};
                    points.append(origin);
                    // A behavior's handles are its entities.
                    watched_record := watched.record;
                    if (watched.storage == HandleStorage && watched_record < 0 && owner_type != 0) {
                        watched_record = TypeWithId(types, owner_type);
                    }
                    values.append(Header(watched.storage, watched.container, watched_record, types, layouts));
                    row: writer.Watch = {origin: length(points) - 1, initial: length(values) - 1,
                                         ordinal: watched.ordinal, output: watched.output, reference: watched.reference};
                    watches.append(row);
                }
                while (length(spans) < base + writer.Tables) {
                    spans.append(Range(0, 0));
                }
                head: writer.Function = {argument_count: callable.count, result_count: result_count,
                                         variable_count: length(kept_states), root_steps: 0, child_budget: 0,
                                         depth_bound: 0, pure_depth_limit: 0, breakpoints: false, batchable: false,
                                         managed: false, custom_lowering: false, checkpoints: false, pin_watches: false,
                                         watch_size: 0, component_bindings: false, component_access: length(reached) != 0,
                                         spans: base};
                functions.append(head);
                references.append(Own(index - first_own));
                references.append(Own(-1));
                if (handler >= 0) {
                    // Stage zero's handler ID: the source, the handler's offset and its kind.
                    handled_event := game_events[handler];
                    wide.append(binding.ID("function", format_text("{}:{}:{}", identity,
                                                                   forest[callable.node].start, HandlerFunction)));
                    wide.append(handled_event.id);
                    wide.append(handled_event.abi);
                    wide.append(uint64(Effects(ops, body_code, length(reached) != 0, length(written) != 0)));
                    row: writer.Entry = {id: length(wide) - 4, kind: HandlerFunction, entry_name: "", has_entry: false,
                                         event_id: length(wide) - 3, event_abi: length(wide) - 2,
                                         event_name: handled_event.name, has_event_name: true, continuation_wait: false,
                                         effects: length(wide) - 1, body: length(references) - 2,
                                         subscription: length(references) - 1};
                    entries.append(row);
                } else if (owner_type != 0) {
                    // A behavior's member procedure is a symbol of its source's scope.
                    wide.append(binding.ID("symbol", format_text("{}:1:{}:callable", identity,
                                                                 callable.name)));
                    procedure: writer.Entry = {id: length(wide) - 1, kind: 0, entry_name: "", has_entry: false,
                                               event_id: 0, event_abi: 0, event_name: "", has_event_name: false,
                                               continuation_wait: false, effects: 0, body: length(references) - 2,
                                               subscription: length(references) - 1};
                    entries.append(procedure);
                } else {
                    wide.append(binding.ID("package-symbol",
                                           format_text("{}:{}:{}:callable", identity, FunctionKind, callable.name)));
                    exported: writer.Entry = {id: length(wide) - 1, kind: 0, entry_name: callable.name, has_entry: true,
                                              event_id: 0, event_abi: 0, event_name: "", has_event_name: false,
                                              continuation_wait: false, effects: 0, body: length(references) - 2,
                                              subscription: length(references) - 1};
                    entries.append(exported);
                }
        }
        index += 1;
    }
    // The events the handlers take, each once, in the order they first do.
    event_declarations: writer.Event[] = [];
    event_fields: writer.EventField[] = [];
    listed: int[] = [];
    for (handler in handled) {
        if (handler < 0 || Position(listed, handler) >= 0) {
            continue;
        }
        listed.append(handler);
        handled_event := game_events[handler];
        wide.append(handled_event.id);
        wide.append(handled_event.abi);
        declared: writer.Event = {id: length(wide) - 2, abi: length(wide) - 1, name: handled_event.name,
                                  first: length(event_fields), count: handled_event.count};
        event_declarations.append(declared);
        at := handled_event.first;
        while (at < handled_event.first + handled_event.count) {
            payload := game_fields[at];
            values.append(ScalarValue(payload.storage, 0));
            wide.append(payload.nominal);
            field: writer.EventField = {name: payload.name, nominal: length(wide) - 1, has_default: payload.has_default,
                                        default_owner: payload.default_owner, initial: length(values) - 1};
            event_fields.append(field);
            at += 1;
        }
    }
    states: writer.State[] = [];
    for (kept in kept_states) {
        values.append(ScalarValue(kept.storage, length(wide)));
        wide.append(kept.bits);
        wide.append(kept.id);
        row: writer.State = {id: length(wide) - 1, initial: length(values) - 1, shared: false, contains_tasks: false};
        states.append(row);
    }
    layouts_table: writer.ResultLayout[] = [];
    return Result.Compiled(module, writer.Write(writer.Module.Tables(module, owner_type, abi, target.pointer_size, wide, values, ints, requirements,
                                                                     fields, event_declarations, event_fields, imports, functions, spans, roots, instructions,
                                                                     locals, parameters, frames, sources, layouts_table, data, hosts, calls,
                                                                     references, components, points, watches, states, entries)));
}

// `paths` and `sources` are the files of every package, `paths[0]` one of the
// root package's; `project` and each named collection are roots that paths
// and imports resolve against. `abi` is the target's prepared header ABI,
// `names` its instruction names in ordinal order, and `natives` the native
// functions it links.
pub Compile :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                sources: string[], debug: bool, target: Target, abi: uint64, names: string[], natives: Native[],
                ports: Port[], identities: uint64[]) -> Result {
    ops := ResolveOps(names, debug);
    complete := length(identities) == 2 * length(natives);
    for (native_row in natives) {
        if (native_row.first < 0 || native_row.parameters < 0 || native_row.results < 0 ||
            native_row.first + native_row.parameters + native_row.results > length(ports)) {
            complete = false;
        }
    }
    if (abi == 0 || !Complete(ops) || !complete || length(paths) == 0 || length(paths) != length(sources) ||
        length(collection_names) != length(collection_paths)) {
        return InputFailure(-1, "unsupported compiler input or target");
    }
    collections: routes.Collection[] = [];
    index: int = 0;
    while (index < length(collection_names)) {
        collection: routes.Collection = {name: collection_names[index], path: collection_paths[index], has_name: true,
                                         has_path: true};
        collections.append(collection);
        index += 1;
    }
    inputs: snapshot.Input[] = [];
    sizes: uint64[] = [];
    index = 0;
    while (index < length(paths)) {
        input: snapshot.Input = {path: paths[index], text: sources[index], has_path: true, has_text: true};
        inputs.append(input);
        sizes.append(uint64(strings.ByteLength(sources[index])));
        index += 1;
    }
    options: snapshot.Options = {project: project, has_project: true, has_options: true,
                                 has_files: true, has_collections: length(collections) != 0, file_count: length(inputs),
                                 collection_count: length(collections)};
    switch snapshot.Build(options, collections, inputs, sizes) {
        case .Rejected(diagnostic, related, graph_error, cycle, documents, nodes, imports):
            return Result.Rejected(diagnostic);
        case .Accepted(roots, documents, nodes, imports, built):
            switch built {
                case .Rejected(error, cycle):
                    return InputFailure(-1, "package graph is invalid");
                case .Accepted(packages, files_of, file_packages, order, edges, links):
                    switch Declare(nodes, documents, packages, files_of, order, imports, links, target) {
                        case .Failed(diagnostic):
                            return Result.Rejected(diagnostic);
                        case .Collected(callables, params, types, members, constants):
                            return Link(nodes, documents, packages, files_of, file_packages[0], order, edges, links,
                                        callables, params, types, members, constants, natives, ports, identities, ops, target,
                                        abi);
                    }
            }
    }
}
// Compile's closure, for a host that takes one byte[] result; empty when
// Compile rejects the input, whose diagnostic Compile returns.
pub CompileClosure :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                       sources: string[], debug: bool, target: Target, abi: uint64, names: string[],
                       natives: Native[], ports: Port[], identities: uint64[]) -> byte[] {
    switch Compile(project, collection_names, collection_paths, paths, sources, debug, target, abi, names, natives,
                   ports, identities) {
        case .Rejected(diagnostic):
            return [];
        case .Compiled(module, bytes):
            return bytes;
    }
}
package package_compiler

import snapshot "project:source_snapshot"
import syntax "project:syntax_diagnostics"
import binding "project:lexical_binding"
import strings "core:strings"

// One function body, emitted in one pass. A work stack visits statements and
// expressions in evaluation order; each expression pushes its typed value.
// Scalars and strings live in the locals bank. Records and arrays are
// pointers; a local one lives in a data cell and is copied on every store.
// Host calls and authored calls pass values through cells, whose headers
// carry each value's type.
//
// EmitBody keeps every table and emits control flow. Every other node is a
// step (Steps.chibi) that returns only what it adds, so no one definition
// grows past what the runtime's verifier admits.

// A slot's or a local's storage and kind.
Slot :: struct {
    storage: int;
    kind: int;
}
// A local holding a value of `storage`.
ValueLocal :: (storage: int) -> Slot {
    return {storage: storage, kind: ValueKind};
}
// An instruction with the value a constant or header read carries, the
// message a failing check reports and the source range it lowers. `payload`
// is a scalar's 64 bits, sign-extended for signed types.
Code :: struct {
    op: int;
    type: int;
    output: int;
    left: int;
    right: int;
    target: int;
    offset: int;
    value_storage: int;
    value_container: int;
    value_record: int;
    payload: uint64;
    text: string;
    has_text: bool;
    message: string;
    has_message: bool;
    start: int;
    end: int;
    line: int;
    column: int;
}
// An integer literal's exact value, or none.
Literal :: union {
    Number(negative: bool, magnitude: uint64) | Invalid
}
// A data cell's header type and kind. Some cells hold a constant payload: the
// bits `constant`, or the tag of variant types[variant] when that is not -1.
Cell :: struct {
    storage: int;
    container: int;
    record: int;
    constant: uint64;
    variant: int;
    kind: int;
}
Invocation :: struct {
    callee: int;
    first: int;
    count: int;
    result_first: int;
    result_count: int;
}
// A host call: runtime intrinsic `intrinsic`, or the native natives[linked]
// when `linked` is not -1. A component reference's make is `written` when
// the body writes through the reference.
Host :: struct {
    intrinsic: int;
    linked: int;
    first: int;
    result_first: int;
    result_count: int;
    written: bool;
}
// A slot holding a record or array pointer the collector must trace.
Root :: struct {
    slot: int;
    storage: int;
    container: int;
    record: int;
}
Body :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Emitted(slots: Slot[], locals: Slot[], cells: Cell[], code: Code[], calls: Invocation[],
              hosts: Host[], roots: Root[], points: SourcePoint[], watches: SourceWatch[])
}
// A debugger point: a record of stage zero's kind at a source range, which
// breakpoints find by its occurrence; `meaning` names what it is, such as the
// event a handler takes, and a function's completion points mark its returns.
SourcePoint :: struct {
    occurrence: uint64;
    meaning: uint64;
    start: int;
    end: int;
    line: int;
    column: int;
    kind: int;
    completion: bool;
}
// A debugger watch: the value of the expression whose occurrence and range it
// holds, of the type that storage, container and record give, or, unless
// `output`, its input numbered `ordinal`, such as a call's argument.
SourceWatch :: struct {
    occurrence: uint64;
    start: int;
    end: int;
    line: int;
    column: int;
    storage: int;
    container: int;
    record: int;
    ordinal: int;
    output: bool;
    reference: bool;
}
// Record kinds, as the SDK numbers them.
SymbolRecord: int : 0;
FunctionRecord: int : 1;
ExpressionRecord: int : 2;
StatementRecord: int : 3;
// Point indexes of SOURCE_POINTs that EmitBody makes points once the body is
// emitted, each at the instruction's own position: the function's completion
// point, an expression's point, and the point of the symbol whose declaring
// node the instruction's `right` holds.
CompletionPoint: int : -2;
SymbolPoint: int : -3;
ExpressionPoint: int : -4;
// The point index of a point of the record kind the instruction's `right`
// holds, whose occurrence its payload holds, for a record that need not be in
// the function's document.
OccurrencePoint: int : -5;
// A scheduled visit. Storage, container and record are the type a literal at
// `node` takes from its context; storage 0 means none.
Work :: struct {
    node: int;
    phase: int;
    a: int;
    b: int;
    c: int;
    storage: int;
    container: int;
    record: int;
}
Value :: struct {
    slot: int;
    storage: int;
    container: int;
    record: int;
}
// A name in scope: a locals-bank value, a record or array held in a data
// cell, a record or array parameter read in place, or a behavior's state or
// owner. Pattern bindings are not writable.
Name :: struct {
    name: string;
    place: int;
    index: int;
    storage: int;
    container: int;
    record: int;
    writable: bool;
    // The node that declares the name, -1 when the source declares none, as
    // for `self`.
    node: int;
}
// A loop being emitted. A while loop's continues jump to `head`; a for
// loop patches them to its increment, and owns its index local, the names to
// drop and its exit jump, `leave`. A for loop counts down when `reverse`; a
// range loop keeps its other end in the `bound` local and, when `counted`,
// stops once the index reaches it, before a step that could wrap; `empty`
// skips a reversed `..<` range that holds nothing.
Loop :: struct {
    head: int;
    first_break: int;
    first_continue: int;
    each: bool;
    index: int;
    mark: int;
    leave: int;
    reverse: bool;
    counted: bool;
    bound: int;
    empty: int;
}
// A switch being emitted: the local holding its union, where its exit jumps
// start in `exits` and its matched variants in `covered`, whether it has a
// default arm, the pending jump past the current arm, and the names the arm's
// bindings start at. A switch on an integer of `storage` compares the value
// with each arm's in turn and runs its default arm, `fallback`, after them
// all, as stage zero does; -2 once that arm is emitted.
Switch :: struct {
    subject: int;
    held: int;
    first_exit: int;
    first_cover: int;
    defaulted: bool;
    skip: int;
    mark: int;
    value: bool;
    storage: int;
    fallback: int;
}
// The size of each table when a step starts.
Bases :: struct {
    pc: int;
    slot: int;
    local: int;
    cell: int;
    host: int;
    call: int;
}
// What a step adds: instructions and table rows, names it binds, work it
// schedules, how many values it pops, the value it produces, a value to copy
// into a fresh cell, and positions it reports to EmitBody.
Step :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Emitted(code: Code[], slots: Slot[], locals: Slot[], cells: Cell[], hosts: Host[], roots: Root[],
              calls: Invocation[], bound: Name[], next: Work[], popped: int, produced: Value, retained: Value,
              marks: int[])
}

ValueKind: int : 0;
AddressKind: int : 1;
// A slot or cell holding a reference the reference intrinsics take.
ReferenceKind: int : 2;
LocalPlace: int : 0;
CellPlace: int : 1;
ParameterPlace: int : 2;
// An import alias; its index is the package it names.
AliasPlace: int : 3;
// A local holding a native call's several results: its index is the first
// result's cell and its record the native.
ResultsPlace: int : 4;
// A behavior's retained state; its index is the state's.
StatePlace: int : 5;
// `self`, the entity that owns the behavior.
SelfPlace: int : 6;
// A name the game binds; its index is the global's.
GlobalPlace: int : 7;
ArrayContainer: int : 1;
// A map, as PIN_CONTAINER_MAP; its record is its MapDecl.
MapContainer: int : 3;
// A jump whose target a later instruction supplies.
Pending: int : -1;
SnapshotIntrinsic: int : 1;
ConstructIntrinsic: int : 2;
ArrayPushIntrinsic: int : 27;
ArrayStoreIntrinsic: int : 28;
ArrayExtendIntrinsic: int : 29;
ReferenceMakeIntrinsic: int : 3;
ReferenceFieldIntrinsic: int : 4;
ReferenceReadIntrinsic: int : 5;
ReferenceWriteIntrinsic: int : 6;
UnionMakeIntrinsic: int : 20;
// union_make in the caller's storage, keeping the payload values it names.
UnionKeepIntrinsic: int : 45;
// Added to an intrinsic, runs it in the caller's storage, where a function
// builds the locals it returns.
InResult: int : 256;
UnionTestIntrinsic: int : 21;
UnionGetIntrinsic: int : 22;
// Statement phases after the value is ready.
ValuePhase: int : 1;
RetainedPhase: int : 2;
PushPhase: int : 3;
StorePhase: int : 4;
FieldPhase: int : 5;
ComponentPhase: int : 6;
// The phase of a binary operator or compound assignment whose two values on
// top are records, which a numeric aggregate native combines.
AggregatePhase: int : 7;
ComponentAssignPhase: int : 8;
// The phase of a compound assignment that combines the two values on top with
// its operator.
CombinePhase: int : 9;
// The phase of `return (a, b)` once each named result's value is ready.
ReturnsPhase: int : 10;

// The FNV-1a mix of the eight bytes of `value`, low first, as the SDK mixes
// a word into an identity.
MixWord :: (hash: uint64, value: uint64) -> uint64 {
    mixed := hash;
    rest := value;
    index: int = 0;
    while (index < 8) {
        mixed = (mixed ^ (rest & 255)) * 1099511628211;
        rest = rest >> 8;
        index += 1;
    }
    return mixed;
}
// A record's occurrence, as the SDK's script_occurrence gives it: its
// document `key`, its kind and its range counted in bytes that are not
// whitespace.
Occurrence :: (key: string, kind: int, start: int, end: int) -> uint64 {
    return OccurrenceIn(DocumentHash(key), kind, start, end);
}
// The part of every occurrence that the document `key` fixes.
DocumentHash :: (key: string) -> uint64 {
    hash := binding.ID("source-occurrence", "");
    count := strings.ByteLength(key);
    hash = MixWord(hash, uint64(count));
    index: int = 0;
    while (index < count) {
        hash = (hash ^ uint64(strings.ByteAt(key, index))) * 1099511628211;
        index += 1;
    }
    return hash;
}
// An occurrence in the document whose DocumentHash is `document`.
OccurrenceIn :: (document: uint64, kind: int, start: int, end: int) -> uint64 {
    hash := MixWord(MixWord(MixWord(document, uint64(kind)), uint64(start)), uint64(end));
    if (hash == 0) {
        return 1;
    }
    return hash;
}
// How many bytes of `text` before each offset, through its end, are not
// whitespace. It reads the bytes at once: each ByteAt measures the text.
SolidOffsets :: (text: string) -> int[] {
    solid: int[] = [0];
    count: int = 0;
    for (byte in strings.Bytes(text)) {
        if (byte != 32 && byte != 9 && byte != 10 && byte != 13) {
            count += 1;
        }
        solid.append(count);
    }
    return solid;
}
// The point of the record of `kind` at `node`, in the document whose
// DocumentHash is `document` and whose bytes `solid` counts.
PointIn :: (document: uint64, solid: int[], kind: int, node: snapshot.SnapshotNode) -> SourcePoint {
    return {occurrence: OccurrenceIn(document, kind, solid[node.start], solid[node.end]), meaning: 0,
            start: node.start, end: node.end, line: node.row + 1, column: node.column + 1, kind: kind,
            completion: false};
}
// The point at `node` of the record of `kind` at `record`, in the document
// `key` whose bytes `solid` counts. A completion point is its function's, at
// a return.
PointAt :: (key: string, solid: int[], kind: int, meaning: uint64, completion: bool, record: snapshot.SnapshotNode,
            node: snapshot.SnapshotNode) -> SourcePoint {
    return {occurrence: Occurrence(key, kind, solid[record.start], solid[record.end]), meaning: meaning,
            start: node.start, end: node.end, line: node.row + 1, column: node.column + 1, kind: kind,
            completion: completion};
}
// A return's SOURCE_POINT, which EmitBody makes the function's completion
// point at the return.
CompletionCode :: (ops: Ops, node: snapshot.SnapshotNode) -> Code {
    return Instruction(ops.source_point, 0, 0, CompletionPoint, 0, 0, node);
}
// The point of the expression at `node`.
ExpressionCode :: (ops: Ops, node: snapshot.SnapshotNode) -> Code {
    return Instruction(ops.source_point, 0, 0, ExpressionPoint, 0, 0, node);
}
// A point at `node` of the symbol that the node `declared` declares, -1 when
// the source declares none.
SymbolCode :: (ops: Ops, declared: int, node: snapshot.SnapshotNode) -> Code {
    return Instruction(ops.source_point, 0, 0, SymbolPoint, declared, 0, node);
}
// A point at `node` of a record of `kind` whose occurrence is `occurrence`.
OccurrenceCode :: (ops: Ops, kind: int, occurrence: uint64, node: snapshot.SnapshotNode) -> Code {
    return {op: ops.source_point, type: 0, output: 0, left: OccurrencePoint, right: kind, target: 0, offset: 0,
            value_storage: 0, value_container: 0, value_record: -1, payload: occurrence, text: "", has_text: false,
            message: "", has_message: false, start: node.start, end: node.end, line: node.row + 1,
            column: node.column + 1};
}
// Whether `binding` is a function's parameter, which stage zero assigns
// through its reference rather than storing.
Parameter :: (forest: snapshot.SnapshotNode[], binding: Name) -> bool {
    if (binding.node < 0) {
        return false;
    }
    declaring := forest[binding.node].parent;
    return Is(forest, declaring, "parameter") && forest[forest[declaring].parent].field == "parameters";
}
// Whether stage zero reads `node` as a literal: a number, string or bool,
// or a negated number.
LiteralNode :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    kind := forest[node].kind;
    return kind == "number" || kind == "string" || kind == "boolean" ||
           (kind == "unary_expression" && Is(forest, Field(forest, node, "operand"), "number"));
}
// Whether `node` is a number literal, negated or not.
NumberLiteral :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    return Is(forest, node, "number") ||
           (Is(forest, node, "unary_expression") && Is(forest, Field(forest, node, "operand"), "number"));
}
// Whether `node` is an element of an array literal of literals, which stage
// zero makes as one constant.
ConstantElement :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    array := forest[node].parent;
    if (!Is(forest, array, "array_expression")) {
        return false;
    }
    for (element in Members(forest, array)) {
        if (!LiteralNode(forest, element)) {
            return false;
        }
    }
    return true;
}
// An identifier's points as stage zero evaluates it: the expression's, then
// the name's when it names one.
NamePoints :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], ops: Ops, node: int) -> Code[] {
    code: Code[] = [ExpressionCode(ops, forest[node])];
    found := Lookup(names, Text(forest, text, node));
    if (found >= 0 && names[found].place != AliasPlace) {
        code.append(SymbolCode(ops, names[found].node, forest[node]));
    }
    return code;
}
// The points stage zero places on an assignment's target before its value:
// each member the target reaches through, outermost first, then the name it
// starts from.
TargetPoints :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], ops: Ops, node: int) -> Code[] {
    code: Code[] = [];
    at := node;
    while (Is(forest, at, "member_expression")) {
        code.append(ExpressionCode(ops, forest[at]));
        at = Field(forest, at, "object");
    }
    if (Is(forest, at, "identifier")) {
        code.extend(NamePoints(forest, text, names, ops, at));
    }
    return code;
}
// Whether stage zero evaluates a node of `kind` as an expression, with a
// point. Parentheses only group.
Expression :: (kind: string) -> bool {
    return kind == "number" || kind == "boolean" || kind == "string" || kind == "identifier" ||
           kind == "member_expression" || kind == "index_expression" || kind == "struct_expression" ||
           kind == "array_expression" || kind == "map_expression" || kind == "call_expression" ||
           kind == "unary_expression" || kind == "binary_expression" || kind == "is_expression";
}
// The occurrence of the symbol the node `declared` declares, or `undeclared`
// for one the source declares nowhere.
SymbolOccurrence :: (forest: snapshot.SnapshotNode[], document: uint64, solid: int[], undeclared: uint64,
                     declared: int) -> uint64 {
    if (declared < 0) {
        return undeclared;
    }
    return OccurrenceIn(document, SymbolRecord, solid[forest[declared].start], solid[forest[declared].end]);
}
// The SOURCE_WATCH of slot `slot`, holding a value of the type storage,
// container and record give, that EmitBody makes the watch of the expression
// at `node`: its output, or its input `ordinal`.
WatchCode :: (ops: Ops, slot: int, storage: int, container: int, record: int, ordinal: int, output: bool,
              node: snapshot.SnapshotNode, target: Target) -> Code {
    flag: int = 0;
    if (output) {
        flag = 1;
    }
    code := Instruction(ops.source_watch, SlotStorage(storage, container, target), flag, slot, ordinal, Pending,
                        node);
    code.value_storage = storage;
    code.value_container = container;
    code.value_record = record;
    return code;
}
// The SOURCE_WATCH of slot `slot`, holding a number or bool of `storage`,
// that EmitBody makes the watch of the expression at `node`.
ScalarWatch :: (ops: Ops, slot: int, storage: int, ordinal: int, output: bool, node: snapshot.SnapshotNode) -> Code {
    flag: int = 0;
    if (output) {
        flag = 1;
    }
    code := Instruction(ops.source_watch, storage, flag, slot, ordinal, Pending, node);
    code.value_storage = storage;
    return code;
}
// The output watch of slot `slot`, holding a default of `storage` that a call
// omits, at `node`. The default of a function in the same package is its own
// expression, with that occurrence. Stage zero reads another package's default
// from that package's catalog as a constant at the call's arguments. Its
// occurrence is 0 and is resolved in the caller's document.
DefaultWatch :: (ops: Ops, slot: int, storage: int, occurrence: uint64, node: snapshot.SnapshotNode) -> Code {
    return {op: ops.source_watch, type: storage, output: 1, left: slot, right: 0, target: Pending, offset: 0,
            value_storage: storage, value_container: 0, value_record: -1, payload: occurrence, text: "",
            has_text: false, message: "", has_message: false, start: node.start, end: node.end,
            line: node.row + 1, column: node.column + 1};
}
// The watch of the number literal at `node` once slot `slot` holds it as
// `storage`; an element of an array of literals has none.
LiteralWatch :: (forest: snapshot.SnapshotNode[], ops: Ops, slot: int, storage: int, node: int) -> Code[] {
    if (ConstantElement(forest, node)) {
        return [];
    }
    return [ScalarWatch(ops, slot, storage, 0, true, forest[node])];
}
// The owner read into slot `slot` and watched as the `self` at `node`.
OwnerWatch :: (ops: Ops, slot: int, node: snapshot.SnapshotNode) -> Code[] {
    if (!ops.debug) {
        return [];
    }
    watch := Instruction(ops.source_watch, HandleStorage, 1, slot, 0, Pending, node);
    watch.value_storage = HandleStorage;
    return [Instruction(ops.owner, HandleStorage, slot, 0, 0, 0, node), watch];
}
// The name an assignment's target starts from, through its members.
TargetRoot :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    at := node;
    while (Is(forest, at, "member_expression")) {
        at = Field(forest, at, "object");
    }
    return at;
}
// Bases `count` slots past `at`, for a step whose slots follow others.
SlotsPast :: (at: Bases, count: int) -> Bases {
    return {pc: at.pc, slot: at.slot + count, local: at.local, cell: at.cell, host: at.host, call: at.call};
}
// The source position an instruction records, as a node to place at.
Located :: (code: Code) -> snapshot.SnapshotNode {
    return {kind: "", start: code.start, end: code.end, row: code.line - 1, column: code.column - 1, parent: -1,
            first_child: -1, next_sibling: -1, error: false, missing: false, has_error: false, field: "",
            is_named: false, is_extra: false};
}
// `code` without its points and watches. A jump or branch to one goes to the
// next instruction kept.
WithoutDebug :: (ops: Ops, code: Code[]) -> Code[] {
    kept: int[] = [];
    count: int = 0;
    for (item in code) {
        kept.append(count);
        if (item.op != ops.source_point && item.op != ops.source_watch) {
            count += 1;
        }
    }
    kept.append(count);
    stripped: Code[] = [];
    for (item in code) {
        if (item.op == ops.jump || item.op == ops.branch_if) {
            moved := item;
            moved.target = kept[item.target];
            stripped.append(moved);
        } else if (item.op != ops.source_point && item.op != ops.source_watch) {
            stripped.append(item);
        }
    }
    return stripped;
}
// The SOURCE_POINT of points[point].
PointCode :: (ops: Ops, point: int, node: snapshot.SnapshotNode) -> Code {
    return Instruction(ops.source_point, 0, 0, point, 0, 0, node);
}
// Whether stage zero lowers a node of `kind` as a statement, with a point.
Statement :: (kind: string) -> bool {
    return kind == "callable_body" || kind == "block" || kind == "if_statement" || kind == "while_statement" ||
           kind == "for_statement" || kind == "switch_statement" || kind == "break_statement" ||
           kind == "continue_statement" || kind == "local_declaration" || kind == "assignment" ||
           kind == "expression_statement" || kind == "return_statement" || kind == "delete_statement";
}
Instruction :: (op: int, type: int, output: int, left: int, right: int, target: int,
                item: snapshot.SnapshotNode) -> Code {
    return {op: op, type: type, output: output, left: left, right: right, target: target,
            offset: 0, value_storage: 0, value_container: 0, value_record: -1, payload: 0, text: "",
            has_text: false, message: "", has_message: false, start: item.start, end: item.end, line: item.row + 1,
            column: item.column + 1};
}
Visit :: (node: int) -> Work {
    return {node: node, phase: 0, a: 0, b: 0, c: 0, storage: 0, container: 0, record: -1};
}
Expect :: (node: int, storage: int, container: int, record: int) -> Work {
    return {node: node, phase: 0, a: 0, b: 0, c: 0, storage: storage, container: container, record: record};
}
Resume :: (node: int, phase: int, a: int, b: int) -> Work {
    return {node: node, phase: phase, a: a, b: b, c: 0, storage: 0, container: 0, record: -1};
}
// Bases for a step whose code stands alone, such as a state's initial value.
NoBases :: () -> Bases {
    return {pc: 0, slot: 0, local: 0, cell: 0, host: 0, call: 0};
}
NoValue :: () -> Value {
    return {slot: -1, storage: 0, container: 0, record: -1};
}
Typed :: (slot: int, storage: int, container: int, record: int) -> Value {
    return {slot: slot, storage: storage, container: container, record: record};
}
Fail :: (forest: snapshot.SnapshotNode[], node: int, document: int, message: string) -> Step {
    return Step.Failed(Diagnose(forest, node, document, message));
}
// Whether a record, array or union is new in the function's value storage,
// where a copy would go, and nothing else reaches it: a literal, a variant
// built with its payload, or an authored function's result, which the call
// copies there. A native may return an argument, so its result is not fresh.
Fresh :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], types: TypeDecl[], names: Name[],
          package: int, node: int) -> bool {
    value := Unparenthesized(forest, node);
    if (Is(forest, value, "struct_expression") || Is(forest, value, "array_expression") ||
        Is(forest, value, "map_expression")) {
        return true;
    }
    if (!Is(forest, value, "call_expression")) {
        return false;
    }
    callee := Field(forest, value, "function");
    return CalledFunction(forest, text, callables, names, package, value) >= 0 ||
           (Is(forest, callee, "member_expression") && UnionOf(forest, text, types, names, package, callee) >= 0);
}
// Whether a value is the one a return statement returns, which the function
// may build in its caller's storage.
Returned :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    at := node;
    while (Is(forest, forest[at].parent, "parenthesized_expression")) {
        at = forest[at].parent;
    }
    parent := forest[at].parent;
    return Is(forest, parent, "return_statement") && Field(forest, parent, "value") == at;
}
// The name a place reads or writes, through its fields and elements.
RootOf :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    at := Unparenthesized(forest, node);
    while (Is(forest, at, "member_expression") || Is(forest, at, "index_expression")) {
        at = Unparenthesized(forest, Field(forest, at, "object"));
    }
    return at;
}
// The names a body changes: each assignment's root, each map a key is
// deleted from, and each name a ref argument reaches. Shadowing is ignored,
// so another local of the same spelling counts too.
MutatedNames :: (forest: snapshot.SnapshotNode[], text: string, node: int, referenced: string[]) -> string[] {
    found := referenced;
    pending: int[] = [node];
    top: int = 1;
    while (top > 0) {
        top -= 1;
        at := pending[top];
        target: int = -1;
        if (Is(forest, at, "assignment") || Is(forest, at, "delete_statement")) {
            target = Field(forest, at, "target");
        } else if (Is(forest, at, "call_expression") && Is(forest, Field(forest, at, "function"), "member_expression") &&
                   ChangingMethod(Text(forest, text, Field(forest, Field(forest, at, "function"), "member")))) {
            target = Field(forest, at, "function");
        }
        if (target >= 0 && Is(forest, RootOf(forest, target), "identifier")) {
            found.append(Text(forest, text, RootOf(forest, target)));
        }
        child := forest[at].first_child;
        while (child >= 0) {
            if (top < length(pending)) {
                pending[top] = child;
            } else {
                pending.append(child);
            }
            top += 1;
            child = forest[child].next_sibling;
        }
    }
    return found;
}
// Whether a method of that name changes what it is called on: a map's
// `delete`, or an array method such as `append`.
ChangingMethod :: (name: string) -> bool {
    changers: string[] = ["delete", "append", "extend", "insert", "remove_index", "remove_item", "add_unique",
                          "set_array_elem", "clear", "reverse", "swap", "resize"];
    for (changer in changers) {
        if (NameMatches(name, changer)) {
            return true;
        }
    }
    return false;
}
// Whether a record or array stays as it is while its function runs, so a
// name may read it in place rather than copy it: a fresh value, or part of a
// local or parameter the body never changes.
Unchanging :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], types: TypeDecl[],
               names: Name[], package: int, mutated: string[], node: int) -> bool {
    if (Fresh(forest, text, callables, types, names, package, node)) {
        return true;
    }
    root := RootOf(forest, node);
    if (!Is(forest, root, "identifier") || Holds(mutated, Text(forest, text, root))) {
        return false;
    }
    found := Lookup(names, Text(forest, text, root));
    return found >= 0 && (names[found].place == CellPlace || names[found].place == ParameterPlace ||
                          names[found].place == ResultsPlace);
}
// Whether a value is a local its function builds in its caller's storage.
BuiltName :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], built: int[], value: int) -> bool {
    at := Unparenthesized(forest, value);
    if (!Is(forest, at, "identifier")) {
        return false;
    }
    found := Lookup(names, Text(forest, text, at));
    return found >= 0 && names[found].place == CellPlace && built.contains(names[found].node);
}
// Whether an array literal initializes a local its function builds in its
// caller's storage.
BuiltLiteral :: (forest: snapshot.SnapshotNode[], built: int[], literal: int) -> bool {
    at := literal;
    while (Is(forest, forest[at].parent, "parenthesized_expression")) {
        at = forest[at].parent;
    }
    declaration := forest[at].parent;
    return Is(forest, declaration, "local_declaration") && Field(forest, declaration, "value") == at &&
           built.contains(Field(forest, declaration, "name"));
}
// The position of a spelling in a list of names, or -1.
NamePosition :: (spellings: string[], name: string) -> int {
    index: int = 0;
    while (index < length(spellings)) {
        if (spellings[index] == name) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// Whether an identifier declares a name rather than reads one.
Declares :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    parent := forest[node].parent;
    if (Is(forest, parent, "pattern_bindings")) {
        return true;
    }
    field := forest[node].field;
    return ((Is(forest, parent, "local_declaration") || Is(forest, parent, "constant_declaration") ||
             Is(forest, parent, "parameter")) && field == "name") ||
           (Is(forest, parent, "for_statement") && (field == "name" || field == "key")) || field == "binding";
}
// The names a returned value is made of: itself, or a returned variant's
// payload values.
ReturnedNames :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], aliases: Name[], package: int,
                  value: int) -> string[] {
    at := Unparenthesized(forest, value);
    if (Is(forest, at, "identifier")) {
        return [Text(forest, text, at)];
    }
    callee := Field(forest, at, "function");
    found: string[] = [];
    if (!Is(forest, at, "call_expression") || !Is(forest, callee, "member_expression") ||
        UnionOf(forest, text, types, aliases, package, callee) < 0) {
        return found;
    }
    argument := FirstMember(forest, Field(forest, at, "arguments"));
    while (argument >= 0) {
        if (Is(forest, Unparenthesized(forest, argument), "identifier")) {
            found.append(Text(forest, text, Unparenthesized(forest, argument)));
        }
        argument = NextMember(forest, argument);
    }
    return found;
}
// The array locals a function builds in its caller's storage, by the nodes
// that name them. Each is declared once, at the top of the body, from an
// array literal; changed only by `append`, `extend` and element stores; never
// assigned, deleted from or reached by a ref argument; and returned, itself or
// as a payload of a returned variant, so the return need not copy it.
BuiltLocals :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], aliases: Name[], package: int,
                body: int, referenced: string[]) -> int[] {
    spellings: string[] = [];
    nodes: int[] = [];
    statement := FirstMember(forest, body);
    while (statement >= 0) {
        name := Field(forest, statement, "name");
        if (Is(forest, statement, "local_declaration") &&
            Is(forest, Unparenthesized(forest, Field(forest, statement, "value")), "array_expression") &&
            !Holds(referenced, Text(forest, text, name))) {
            spellings.append(Text(forest, text, name));
            nodes.append(name);
        }
        statement = NextMember(forest, statement);
    }
    returned := resize([false], length(spellings));
    rejected := resize([false], length(spellings));
    pending: int[] = [body];
    top: int = 1;
    while (top > 0 && length(spellings) > 0) {
        top -= 1;
        at := pending[top];
        changed: int = -1;
        if (Is(forest, at, "identifier") && Declares(forest, at)) {
            index := NamePosition(spellings, Text(forest, text, at));
            if (index >= 0 && nodes[index] != at) {
                rejected[index] = true;
            }
        } else if (Is(forest, at, "assignment") || Is(forest, at, "delete_statement")) {
            target := Unparenthesized(forest, Field(forest, at, "target"));
            element := Is(forest, at, "assignment") && Is(forest, target, "index_expression") &&
                       Is(forest, Unparenthesized(forest, Field(forest, target, "object")), "identifier");
            if (!element) {
                changed = RootOf(forest, target);
            }
        } else if (Is(forest, at, "call_expression") && Is(forest, Field(forest, at, "function"), "member_expression")) {
            method := Text(forest, text, Field(forest, Field(forest, at, "function"), "member"));
            if (ChangingMethod(method) && !NameMatches(method, "append") && !NameMatches(method, "extend")) {
                changed = RootOf(forest, Field(forest, at, "function"));
            }
        } else if (Is(forest, at, "return_statement")) {
            for (made in ReturnedNames(forest, text, types, aliases, package, Field(forest, at, "value"))) {
                index := NamePosition(spellings, made);
                if (index >= 0) {
                    returned[index] = true;
                }
            }
        }
        if (Is(forest, changed, "identifier")) {
            index := NamePosition(spellings, Text(forest, text, changed));
            if (index >= 0) {
                rejected[index] = true;
            }
        }
        child := forest[at].first_child;
        while (child >= 0) {
            if (top < length(pending)) {
                pending[top] = child;
            } else {
                pending.append(child);
            }
            top += 1;
            child = forest[child].next_sibling;
        }
    }
    built: int[] = [];
    index: int = 0;
    while (index < length(nodes)) {
        if (returned[index] && !rejected[index]) {
            built.append(nodes[index]);
        }
        index += 1;
    }
    return built;
}
// Records and arrays are pointers to their storage.
Pointer :: (storage: int, container: int) -> bool {
    return container != 0 || storage == StructStorage;
}
SlotStorage :: (storage: int, container: int, target: Target) -> int {
    if (Pointer(storage, container)) {
        return target.pointer_storage;
    }
    return storage;
}
SlotKind :: (storage: int, container: int) -> int {
    if (Pointer(storage, container)) {
        return AddressKind;
    }
    return ValueKind;
}
SameType :: (storage: int, container: int, record: int, value: Value) -> bool {
    return storage == value.storage && container == value.container && record == value.record;
}
Single :: (value: Value, storage: int) -> bool {
    return value.storage == storage && value.container == 0;
}
// The digit a hexadecimal character stands for, -1 for any other.
HexDigit :: (character: int) -> int {
    if (character >= 48 && character <= 57) {
        return character - 48;
    }
    if (character >= 97 && character <= 102) {
        return character - 87;
    }
    if (character >= 65 && character <= 70) {
        return character - 55;
    }
    return -1;
}
// The value of a number literal, or of `-` on one; not valid for anything
// else or beyond 64 bits. Only the operations the runtime allows on uint64
// touch the magnitude: addition, multiplication and comparison for equality.
ParseNumber :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> Literal {
    invalid := Literal.Invalid;
    digits := node;
    negative := false;
    if (Is(forest, node, "unary_expression")) {
        if (Text(forest, text, Field(forest, node, "operator")) != "-") {
            return invalid;
        }
        digits = Field(forest, node, "operand");
        negative = true;
    }
    if (!Is(forest, digits, "number")) {
        return invalid;
    }
    literal := Text(forest, text, digits);
    size := strings.ByteLength(literal);
    base: int = 10;
    index: int = 0;
    if (size > 2 && strings.ByteAt(literal, 0) == 48 &&
        (strings.ByteAt(literal, 1) == 120 || strings.ByteAt(literal, 1) == 88)) {
        base = 16;
        index = 2;
    }
    // At most 16 hexadecimal or 20 decimal significant digits; twenty decimal
    // digits must not exceed the largest uint64.
    first: int = -1;
    magnitude: uint64 = 0;
    while (index < size) {
        digit := HexDigit(strings.ByteAt(literal, index));
        if (digit < 0 || digit >= base) {
            return invalid;
        }
        if (first < 0 && digit != 0) {
            first = index;
        }
        magnitude = magnitude * uint64(base) + uint64(digit);
        index += 1;
    }
    significant: int = 0;
    if (first >= 0) {
        significant = size - first;
    }
    if ((base == 16 && significant > 16) || significant > 20 ||
        (significant == 20 && strings.Compare(strings.Slice(literal, first, 20), "18446744073709551615") > 0)) {
        return invalid;
    }
    return Literal.Number(negative, magnitude);
}
Int8Storage: int : 2;
ByteStorage: int : 3;
Int16Storage: int : 4;
Uint16Storage: int : 5;
UintStorage: int : 7;
Int64Storage: int : 8;
// A value no instruction holds yet: an integer literal its use gives a type.
NumberStorage: int : -3;
// The several results of a native call: the value's slot is the cell of the
// first result and its record the native; `.name` reads one result.
ResultsStorage: int : -4;
// The named results of a function's call, as ResultsStorage, but the record
// is the callable.
FunctionResultsStorage: int : -5;
// The integer types this compiler emits.
Integer :: (storage: int) -> bool {
    return storage >= Int8Storage && storage <= WordStorage;
}
Signed :: (storage: int) -> bool {
    return storage == Int8Storage || storage == Int16Storage || storage == IntStorage || storage == Int64Storage;
}
// An integer type's width in bits.
Width :: (storage: int) -> int {
    if (storage == Int8Storage || storage == ByteStorage) {
        return 8;
    }
    if (storage == Int16Storage || storage == Uint16Storage) {
        return 16;
    }
    if (storage == IntStorage || storage == UintStorage) {
        return 32;
    }
    return 64;
}
TypeName :: (storage: int) -> string {
    if (!Integer(storage)) {
        return "";
    }
    names: string[] = ["int8", "byte", "int16", "uint16", "int", "uint", "int64", "uint64"];
    return names[storage - Int8Storage];
}
// Whether a literal's value fits an integer type.
Fits :: (negative: bool, magnitude: uint64, storage: int) -> bool {
    // Stage zero rejects any signed literal of an unsigned type, -0 included.
    if (negative && !Signed(storage)) {
        return false;
    }
    if (magnitude == 0) {
        return true;
    }
    if (!Signed(storage)) {
        return storage == WordStorage || (magnitude >> uint64(Width(storage))) == 0;
    }
    bits := uint64(Width(storage) - 1);
    return (magnitude >> bits) == 0 || (negative && magnitude == (uint64(1) << bits));
}
// A literal's bits in an integer type it fits, sign-extended when negative.
Bits :: (negative: bool, magnitude: uint64) -> uint64 {
    if (negative) {
        return ~magnitude + 1;
    }
    return magnitude;
}
// The type both integer operands convert to without loss, as stage zero's
// behavior_scalar_common_integer chooses it: the wider operand, or int or
// int64 for a signed and unsigned pair; -1 when there is none, as for int64
// with uint64.
CommonInteger :: (left: int, right: int) -> int {
    if (IntegerWidens(left, right)) {
        return right;
    }
    if (IntegerWidens(right, left)) {
        return left;
    }
    if (IntegerWidens(left, IntStorage) && IntegerWidens(right, IntStorage)) {
        return IntStorage;
    }
    if (IntegerWidens(left, Int64Storage) && IntegerWidens(right, Int64Storage)) {
        return Int64Storage;
    }
    return -1;
}
// Whether every value of the integer type `from` fits `to`.
IntegerWidens :: (from: int, to: int) -> bool {
    if (Signed(from) && !Signed(to)) {
        return false;
    }
    if (!Signed(from) && Signed(to)) {
        return Width(to) > Width(from);
    }
    return Width(to) >= Width(from);
}
// Whether an integer converts to another without loss, as stores do
// implicitly.
Widens :: (from: int, to: int) -> bool {
    return from != to && Integer(from) && Integer(to) && CommonInteger(from, to) == to;
}
// Whether the runtime computes `op` in a number type: arithmetic other than
// remainders, and comparisons, for floats; every operator for the integers,
// negation for the signed ones only.
Computes :: (ops: Ops, op: int, storage: int) -> bool {
    if (Floating(storage)) {
        return op == ops.add || op == ops.sub || op == ops.mul || op == ops.div || op == ops.neg || Comparison(ops, op);
    }
    return op != ops.neg || Signed(storage);
}
// A constant of an integer or bool type. One literal holds `bits`: stage
// zero takes any uint64 for a pointer, and storing one into a local record's
// field would make this function, and every caller, copy its arguments.
ConstantCode :: (ops: Ops, storage: int, bits: uint64, output: int, node: snapshot.SnapshotNode) -> Code {
    return {op: ops.constant, type: storage, output: output, left: 0, right: 0, target: 0, offset: 0,
            value_storage: storage, value_container: 0, value_record: -1, payload: bits, text: "",
            has_text: false, message: "", has_message: false, start: node.start, end: node.end, line: node.row + 1,
            column: node.column + 1};
}
// A conversion to an integer type: `mode` 0 fails when the value does not
// fit, 1 keeps its low bits and 2 saturates.
CastCode :: (ops: Ops, storage: int, output: int, input: int, mode: int, node: snapshot.SnapshotNode) -> Code {
    cast := Instruction(ops.cast, storage, output, input, 0, mode, node);
    cast.message = format_text("Value does not fit in {}", TypeName(storage));
    cast.has_message = true;
    return cast;
}
// The floating types this compiler emits.
Floating :: (storage: int) -> bool {
    return storage == FloatStorage || storage == DoubleStorage;
}
// The instruction a binary operator lowers to; -1 for logic and unknown ones.
BinaryOp :: (ops: Ops, operator: string) -> int {
    if (operator == "+") {
        return ops.add;
    }
    if (operator == "-") {
        return ops.sub;
    }
    if (operator == "*") {
        return ops.mul;
    }
    if (operator == "/") {
        return ops.div;
    }
    if (operator == "%") {
        return ops.mod;
    }
    if (operator == "&") {
        return ops.bit_and;
    }
    if (operator == "|") {
        return ops.bit_or;
    }
    if (operator == "^") {
        return ops.bit_xor;
    }
    if (operator == "<<") {
        return ops.shl;
    }
    if (operator == ">>") {
        return ops.shr;
    }
    if (operator == "<") {
        return ops.lt;
    }
    if (operator == "<=") {
        return ops.le;
    }
    if (operator == ">") {
        return ops.gt;
    }
    if (operator == ">=") {
        return ops.ge;
    }
    if (operator == "==") {
        return ops.eq;
    }
    if (operator == "!=") {
        return ops.ne;
    }
    return -1;
}
Comparison :: (ops: Ops, op: int) -> bool {
    return op == ops.lt || op == ops.le || op == ops.gt || op == ops.ge || op == ops.eq || op == ops.ne;
}
// The operator of a compound assignment, "" for plain assignment.
CompoundOperator :: (text: string) -> string {
    if (text == "=") {
        return "";
    }
    return strings.Slice(text, 0, strings.ByteLength(text) - 1);
}
// The function of `package` named `name`, -1 when none.
FindCallable :: (callables: Callable[], package: int, name: string) -> int {
    index: int = 0;
    while (index < length(callables)) {
        if (callables[index].package == package && callables[index].name == name) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// The field of types[record] named `name`; a native type's matches as the
// catalog matches it: an exact name first, else the one that matches
// loosely. -1 for none or several.
FindField :: (types: TypeDecl[], members: TypeMember[], record: int, name: string) -> int {
    found: int = -1;
    at := types[record].first;
    while (at < types[record].first + types[record].count) {
        if (members[at].name == name) {
            return at;
        }
        if (types[record].kind >= NativeDecl && NameMatches(members[at].name, name)) {
            if (found != -1) {
                found = -2;
            } else {
                found = at;
            }
        }
        at += 1;
    }
    if (found < 0) {
        return -1;
    }
    return found;
}
// The innermost binding of `wanted`, -1 when none.
Lookup :: (names: Name[], wanted: string) -> int {
    at := length(names) - 1;
    while (at >= 0) {
        if (names[at].name == wanted) {
            return at;
        }
        at -= 1;
    }
    return -1;
}
Separator :: (byte: int) -> bool {
    return byte == 95 || byte == 32 || byte == 45;
}
Lower :: (byte: int) -> int {
    if (byte >= 65 && byte <= 90) {
        return byte + 32;
    }
    return byte;
}
// Whether two names match as the native catalog matches them: ignoring case,
// spaces, underscores and hyphens.
NameMatches :: (left: string, right: string) -> bool {
    i: int = 0;
    j: int = 0;
    left_length := strings.ByteLength(left);
    right_length := strings.ByteLength(right);
    while (i <= left_length && j <= right_length) {
        while (i < left_length && Separator(strings.ByteAt(left, i))) {
            i += 1;
        }
        while (j < right_length && Separator(strings.ByteAt(right, j))) {
            j += 1;
        }
        if (i == left_length || j == right_length) {
            return i == left_length && j == right_length;
        }
        if (Lower(strings.ByteAt(left, i)) != Lower(strings.ByteAt(right, j))) {
            return false;
        }
        i += 1;
        j += 1;
    }
    return false;
}
// The native an exact name or one unique matching name selects: -1 when none,
// -2 when several match.
FindNative :: (natives: Native[], name: string) -> int {
    found: int = -1;
    index: int = 0;
    while (index < length(natives)) {
        if (natives[index].name == name) {
            return index;
        }
        if (NameMatches(natives[index].name, name)) {
            if (found >= 0) {
                found = -2;
            } else if (found == -1) {
                found = index;
            }
        }
        index += 1;
    }
    return found;
}
// The package a name of package `package` qualified by `node` names: that
// package for none, the imported one when `node` is an import alias no local
// hides, and -1 otherwise.
QualifierOf :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], package: int, node: int) -> int {
    if (node < 0) {
        return package;
    }
    if (!Is(forest, node, "identifier")) {
        return -1;
    }
    found := Lookup(names, Text(forest, text, node));
    if (found < 0 || names[found].place != AliasPlace) {
        return -1;
    }
    return names[found].index;
}
// Package privacy governs source names, not the runtime functions retained in
// a module. A native or synthesized declaration has no source node.
PrivateDeclaration :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    return node >= 0 && Field(forest, node, "visibility") < 0;
}
PrivateMessage :: (name: string) -> string {
    return format_text("'{}' is private: declare it pub to use it from another package", name);
}
// The qualified type name a type spells privately, including a map's key or
// value and an array's element type. Returns its name node for the diagnostic.
PrivateType :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], names: Name[], package: int,
                node: int) -> int {
    if (node < 0) {
        return -1;
    }
    if (Is(forest, node, "type")) {
        named := Field(forest, node, "name");
        first := FirstMember(forest, named);
        part: int = -1;
        if (first >= 0) {
            part = NextMember(forest, first);
        }
        if (part >= 0) {
            home := QualifierOf(forest, text, names, package, first);
            declared := FindType(types, home, Text(forest, text, part));
            if (home >= 0 && home != package && declared >= 0 && PrivateDeclaration(forest, types[declared].node)) {
                return named;
            }
        }
    }
    child := FirstMember(forest, node);
    while (child >= 0) {
        hidden := PrivateType(forest, text, types, names, package, child);
        if (hidden >= 0) {
            return hidden;
        }
        child = NextMember(forest, child);
    }
    return -1;
}
// A qualified source access, with an import alias no local hides. For a
// variant `alias.Union.Variant`, privacy applies to `alias.Union`.
PrivateAccess :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], types: TypeDecl[],
                  constants: ConstDecl[], names: Name[], package: int, node: int) -> int {
    if (!Is(forest, node, "member_expression")) {
        return -1;
    }
    object := Field(forest, node, "object");
    if (Is(forest, object, "member_expression")) {
        return PrivateAccess(forest, text, callables, types, constants, names, package, object);
    }
    home := QualifierOf(forest, text, names, package, object);
    if (home < 0 || home == package) {
        return -1;
    }
    name := Text(forest, text, Field(forest, node, "member"));
    callable := FindCallable(callables, home, name);
    declared := FindType(types, home, name);
    constant := FindConstant(constants, home, name);
    if ((callable >= 0 && PrivateDeclaration(forest, callables[callable].node)) ||
        (declared >= 0 && PrivateDeclaration(forest, types[declared].node)) ||
        (constant >= 0 && PrivateDeclaration(forest, forest[constants[constant].node].parent))) {
        return node;
    }
    return -1;
}
// The package constant `node` names: `Name` when no local hides it, or
// `alias.Name`; -1 otherwise.
ConstantOf :: (forest: snapshot.SnapshotNode[], text: string, constants: ConstDecl[], names: Name[], package: int,
               node: int) -> int {
    if (Is(forest, node, "identifier")) {
        if (Lookup(names, Text(forest, text, node)) >= 0) {
            return -1;
        }
        return FindConstant(constants, package, Text(forest, text, node));
    }
    if (!Is(forest, node, "member_expression")) {
        return -1;
    }
    home := QualifierOf(forest, text, names, package, Field(forest, node, "object"));
    if (home < 0) {
        return -1;
    }
    return FindConstant(constants, home, Text(forest, text, Field(forest, node, "member")));
}
// The union `U` names when `node` is a member expression `U.Variant` or
// `alias.U.Variant` and no local hides U or the alias; -1 otherwise.
UnionOf :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], names: Name[], package: int,
            node: int) -> int {
    object := Field(forest, node, "object");
    qualifier: int = -1;
    if (Is(forest, object, "member_expression")) {
        qualifier = Field(forest, object, "object");
        object = Field(forest, object, "member");
    } else if (!Is(forest, object, "identifier") || Lookup(names, Text(forest, text, object)) >= 0) {
        return -1;
    }
    home := QualifierOf(forest, text, names, package, qualifier);
    if (home < 0) {
        return -1;
    }
    declared := FindType(types, home, Text(forest, text, object));
    if (declared < 0 || types[declared].kind != UnionDecl) {
        return -1;
    }
    return declared;
}
// Whether `variant` is among `covered` from `first` on.
Covers :: (covered: int[], first: int, variant: int) -> bool {
    at := first;
    while (at < length(covered)) {
        if (covered[at] == variant) {
            return true;
        }
        at += 1;
    }
    return false;
}
// Whether `name` is declared in the innermost scope, whose names start at
// names[scope].
Declared :: (names: Name[], scope: int, name: string) -> bool {
    at := scope;
    while (at < length(names)) {
        if (names[at].name == name) {
            return true;
        }
        at += 1;
    }
    return false;
}
// Whether the `is` expression `node` is an if or while condition, alone or
// joined by `&&` and parentheses, where its bindings may hold the payload.
BindingCondition :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> bool {
    at := node;
    parent := forest[at].parent;
    while (parent >= 0) {
        if (Is(forest, parent, "if_statement") || Is(forest, parent, "while_statement")) {
            return Field(forest, parent, "condition") == at;
        }
        if (Is(forest, parent, "binary_expression")) {
            operator := Text(forest, text, Field(forest, parent, "operator"));
            if (operator != "&&" && operator != "and") {
                return false;
            }
        } else if (!Is(forest, parent, "parenthesized_expression")) {
            return false;
        }
        at = parent;
        parent = forest[at].parent;
    }
    return false;
}
// The next switch arm after `node` among its siblings, -1 when none.
// Whether a range's bounds are both constant and the first is the greater.
Descends :: (forest: snapshot.SnapshotNode[], text: string, document: int, constants: ConstDecl[], names: Name[],
             package: int, node: int) -> bool {
    bounds: int64[] = [];
    for (end in [Field(forest, node, "first"), Field(forest, node, "last")]) {
        switch FoldConstant(forest, text, document, constants, names, package, end, IntStorage) {
            case .Folded(bits):
                bounds.append(int64(wrap: bits));
            case .Failed(diagnostic):
                return false;
            case .Waiting:
                return false;
        }
    }
    return bounds[0] > bounds[1];
}
// The name an array loop gives each item: `x` in `for x in xs` and in the
// keyed `for x, i in xs`, whose second name is the index.
ItemField :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    if (Field(forest, node, "key") >= 0) {
        return Field(forest, node, "key");
    }
    return Field(forest, node, "name");
}
NextArm :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    at := NextMember(forest, node);
    while (at >= 0 && !Is(forest, at, "switch_arm")) {
        at = NextMember(forest, at);
    }
    return at;
}
// The index of a native's result named `name`, matched as natives are: an
// exact name first, else the one name that matches loosely; -1 for none and
// -2 when several match.
FindResult :: (ports: Port[], native: Native, name: string) -> int {
    found: int = -1;
    index: int = 0;
    while (index < native.results) {
        result := ports[native.first + native.parameters + index].name;
        if (result == name) {
            return index;
        }
        if (NameMatches(result, name)) {
            if (found >= 0) {
                found = -2;
            } else if (found == -1) {
                found = index;
            }
        }
        index += 1;
    }
    return found;
}
// The port of a native's argument `index`; a variadic native's last
// parameter takes every argument from it on.
NativePort :: (native: Native, index: int) -> int {
    if (index >= native.parameters && native.variadic && native.parameters > 0) {
        return native.first + native.parameters - 1;
    }
    return native.first + index;
}
// How `xs = name(xs, value)` updates the local array names[found] in place:
// 0 for a push, 1 for an extension and -1 for any other statement. As in stage
// zero, the native is recognized by its capability identity.
InPlaceUpdate :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], natives: Native[],
                  ports: Port[], identities: uint64[], names: Name[], package: int, found: int, destination: int,
                  value: int) -> int {
    updated := names[found];
    if (updated.place != CellPlace || updated.container != ArrayContainer || !updated.writable ||
        !Is(forest, value, "call_expression")) {
        return -1;
    }
    callee := Field(forest, value, "function");
    first := ArrayArgument(forest, value);
    if (!Is(forest, first, "identifier") || Text(forest, text, first) != Text(forest, text, destination) ||
        ItemArgument(forest, value) < 0 || NextMember(forest, ItemArgument(forest, value)) >= 0) {
        return -1;
    }
    native: int = -1;
    if (Is(forest, callee, "member_expression")) {
        native = ArrayMethod(natives, ports, Text(forest, text, Field(forest, callee, "member")));
    } else if (Is(forest, callee, "identifier") && FindCallable(callables, package, Text(forest, text, callee)) < 0) {
        native = FindNative(natives, Text(forest, text, callee));
    }
    if (native < 0) {
        return -1;
    }
    capability := identities[2 * native];
    if (capability == binding.ID("capability", "Append")) {
        return 0;
    }
    if (capability == binding.ID("capability", "Extend")) {
        return 1;
    }
    return -1;
}

// The array function a method call on an array runs, with the array first.
// -1 for none.
ArrayMethod :: (natives: Native[], ports: Port[], name: string) -> int {
    index: int = 0;
    for (native in natives) {
        if (native.parameters > 0 && ports[native.first].container == ArrayContainer && NameMatches(native.name, name)) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// Whether an array function returns its array changed, so its method changes
// the array in place, as `append` does and `slice` does not.
ArrayChanger :: (natives: Native[], native: int) -> bool {
    changers: string[] = ["append", "add_unique", "extend", "set_array_elem", "insert", "remove_index", "remove_item",
                          "clear", "reverse", "swap", "resize"];
    for (changer in changers) {
        if (NameMatches(natives[native].name, changer)) {
            return true;
        }
    }
    return false;
}
// The array an expression statement's method call changes, as `xs.append(x)`
// changes xs: the receiver, a name of an array, or -1.
ChangedArray :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], natives: Native[], ports: Port[],
                 statement: int) -> int {
    call := FirstMember(forest, statement);
    function := Field(forest, call, "function");
    if (!Is(forest, statement, "expression_statement") || !Is(forest, call, "call_expression") ||
        !Is(forest, function, "member_expression") || !Is(forest, Field(forest, function, "object"), "identifier")) {
        return -1;
    }
    object := Field(forest, function, "object");
    found := Lookup(names, Text(forest, text, object));
    if (found < 0 || names[found].container != ArrayContainer) {
        return -1;
    }
    method := ArrayMethod(natives, ports, Text(forest, text, Field(forest, function, "member")));
    if (method < 0 || !ArrayChanger(natives, method)) {
        return -1;
    }
    return object;
}
// An assignment's target and value, or the array a method statement changes
// and its call.
StatementTarget :: (forest: snapshot.SnapshotNode[], statement: int) -> int {
    if (Is(forest, statement, "expression_statement")) {
        return Field(forest, Field(forest, FirstMember(forest, statement), "function"), "object");
    }
    return Field(forest, statement, "target");
}
StatementValue :: (forest: snapshot.SnapshotNode[], statement: int) -> int {
    if (Is(forest, statement, "expression_statement")) {
        return FirstMember(forest, statement);
    }
    return Field(forest, statement, "value");
}
// The array a call updates, `xs` in both `append(xs, x)` and
// `xs.append(x)`, and the item or array it adds.
ArrayArgument :: (forest: snapshot.SnapshotNode[], call: int) -> int {
    callee := Field(forest, call, "function");
    if (Is(forest, callee, "member_expression")) {
        return Field(forest, callee, "object");
    }
    return FirstMember(forest, Field(forest, call, "arguments"));
}
ItemArgument :: (forest: snapshot.SnapshotNode[], call: int) -> int {
    if (Is(forest, Field(forest, call, "function"), "member_expression")) {
        return FirstMember(forest, Field(forest, call, "arguments"));
    }
    return NextMember(forest, FirstMember(forest, Field(forest, call, "arguments")));
}
// The tables a body starts from: its parameters, its record or array result's
// symbol, its point and its named results, which are locals from `named` on.
Start :: union {
    Begun(work: Work[], names: Name[], slots: Slot[], locals: Slot[], code: Code[], points: SourcePoint[], named: int)
}
Prologue :: (forest: snapshot.SnapshotNode[], text: string, params: Param[], callable: Callable, aliases: Name[],
             key: string, solid: int[], meaning: uint64, referenced: string[], mutated: string[],
             ops: Ops) -> Start {
    declaration := forest[callable.node];
    // Import aliases are the outermost names; every local may hide one.
    names := aliases;
    slots: Slot[] = [];
    locals: Slot[] = [];
    code: Code[] = [];
    // Scalar and string parameters move to locals, so assigning one needs no
    // other form. Record and array parameters are read in place, unless the
    // body writes them: those get copies of their own, before the body runs.
    work: Work[] = [Visit(Field(forest, callable.node, "body"))];
    index: int = 0;
    while (index < callable.count) {
        param := params[callable.first + index];
        if (param.reference) {
            name: Name = {name: param.name, place: ReferencePlace, index: index, storage: param.storage,
                          container: param.container, record: param.record, writable: true, node: param.node};
            names.append(name);
        } else if (Holds(referenced, param.name) && !Pointer(param.storage, param.container)) {
            work.append(Resume(callable.node, 0, index, 1));
        } else if (Pointer(param.storage, param.container) && Holds(mutated, param.name)) {
            work.append(Resume(callable.node, 0, index, 0));
        } else if (Pointer(param.storage, param.container)) {
            name: Name = {name: param.name, place: ParameterPlace, index: index, storage: param.storage,
                          container: param.container, record: param.record, writable: true, node: param.node};
            names.append(name);
        } else {
            slot: Slot = {storage: param.storage, kind: ValueKind};
            slots.append(slot);
            read := Instruction(ops.argument, param.storage, length(slots) - 1, index, 0, 0, declaration);
            read.value_storage = param.storage;
            code.append(read);
            locals.append(ValueLocal(param.storage));
            code.append(Instruction(ops.save, param.storage, 0, length(slots) - 1, 0,
                                    length(locals) - 1, declaration));
            name: Name = {name: param.name, place: LocalPlace, index: length(locals) - 1,
                          storage: param.storage, container: 0, record: param.record, writable: true,
                          node: param.node};
            names.append(name);
        }
        index += 1;
    }
    // A record or array result is a symbol the function stores before it
    // starts.
    if (callable.results == 0 && (callable.result == StructStorage || callable.result_container != 0)) {
        code.append(SymbolCode(ops, -1, declaration));
    }
    // The function's point; the body places the others as stage zero does.
    points: SourcePoint[] = [PointAt(key, solid, FunctionRecord, meaning, false, declaration, declaration)];
    code.append(PointCode(ops, 0, declaration));
    // Named results are locals from `named` on, zero until the body sets them.
    named := length(locals);
    index = 0;
    while (index < callable.results) {
        result := params[callable.first + callable.count + index];
        slots.append(ValueLocal(result.storage));
        code.append(ConstantCode(ops, result.storage, 0, length(slots) - 1, declaration));
        locals.append(ValueLocal(result.storage));
        code.append(Instruction(ops.save, result.storage, 0, length(slots) - 1, 0, length(locals) - 1,
                                declaration));
        bound: Name = {name: result.name, place: LocalPlace, index: length(locals) - 1, storage: result.storage,
                       container: 0, record: result.record, writable: true, node: result.node};
        names.append(bound);
        index += 1;
    }
    return Start.Begun(work, names, slots, locals, code, points, named);
}
EmitBody :: (forest: snapshot.SnapshotNode[], text: string, document: int,
             callables: Callable[], params: Param[], types: TypeDecl[], members: TypeMember[],
             constants: ConstDecl[], natives: Native[], ports: Port[], identities: uint64[],
             operators: NumericOperator[], makes: NativeMake[], make_fields: int[], aliases: Name[], key: string,
             solid: int[], undeclared: uint64, meaning: uint64, function: int, referenced: string[],
             mutated: string[], built: int[], ops: Ops, target: Target) -> Body {
    callable := callables[function];
    declaration := forest[callable.node];
    document_hash := DocumentHash(key);
    slots: Slot[] = [];
    // The storage of each locals-bank value; records and arrays never live there.
    locals: Slot[] = [];
    cells: Cell[] = [];
    code: Code[] = [];
    calls: Invocation[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    names: Name[] = [];
    work: Work[] = [];
    points: SourcePoint[] = [];
    named: int = 0;
    begun := Prologue(forest, text, params, callable, aliases, key, solid, meaning, referenced, mutated, ops);
    switch begun {
        case .Begun(begun_work, begun_names, begun_slots, begun_locals, begun_code, begun_points, begun_named):
            work = begun_work;
            names = begun_names;
            slots = begun_slots;
            locals = begun_locals;
            code = begun_code;
            points = begun_points;
            named = begun_named;
    }
    values: Value[] = [];
    loops: Loop[] = [];
    breaks: int[] = [];
    continues: int[] = [];
    switches: Switch[] = [];
    exits: int[] = [];
    covered: int[] = [];
    // Where each open scope's names start: blocks, if and while statements,
    // and switch arms.
    scopes: int[] = [];
    work_top: int = 0;
    value_top: int = 0;
    watches: SourceWatch[] = [];
    work_top = length(work);
    while (work_top > 0) {
        work_top -= 1;
        item := work[work_top];
        node := forest[item.node];
        kind := node.kind;
        // Items this one schedules, in the order they run.
        next: Work[] = [];
        // A value this item leaves for its consumer, when `produced.storage` is set.
        produced := NoValue();
        // A record or array to copy into a fresh cell; the copy is produced.
        retained := NoValue();
        operator := Text(forest, text, Field(forest, item.node, "operator"));
        logic := kind == "binary_expression" &&
                 (operator == "&&" || operator == "and" || operator == "||" || operator == "or");
        if (ops.debug && item.phase == 0 && Statement(kind)) {
            points.append(PointAt(key, solid, StatementRecord, 0, false, node, node));
            code.append(PointCode(ops, length(points) - 1, node));
            // Stage zero assigns each returned value to a result, a statement
            // of its own.
            value := Field(forest, item.node, "value");
            returned: int[] = [];
            if (kind == "return_statement" && Is(forest, value, "argument_list")) {
                returned = Members(forest, value);
            } else if (kind == "return_statement" && value >= 0) {
                returned = [value];
            }
            for (each in returned) {
                points.append(PointAt(key, solid, StatementRecord, 0, false, forest[each], forest[each]));
                code.append(PointCode(ops, length(points) - 1, forest[each]));
            }
        }
        // Stage zero reads `-1` as one literal.
        negated := kind == "number" && Is(forest, node.parent, "unary_expression") &&
                   Text(forest, text, Field(forest, node.parent, "operator")) == "-";
        if (ops.debug && item.phase == 0 && Expression(kind) && !negated && !ConstantElement(forest, item.node)) {
            points.append(PointIn(document_hash, solid, ExpressionRecord, node));
            code.append(PointCode(ops, length(points) - 1, node));
            // A name's symbol, or a package constant's, which is a symbol of
            // its own document.
            constant: int = -1;
            if (kind == "identifier") {
                found := Lookup(names, Text(forest, text, item.node));
                if (found >= 0 && names[found].place != AliasPlace) {
                    code.append(SymbolCode(ops, names[found].node, node));
                } else if (found < 0) {
                    constant = FindConstant(constants, callable.package, Text(forest, text, item.node));
                }
            } else if (kind == "member_expression") {
                constant = ConstantOf(forest, text, constants, names, callable.package, item.node);
                // `self.C` reads the owner's component without visiting `self`.
                if (constant < 0 && SelfComponent(forest, text, types, names, item.node) >= 0) {
                    code.extend(NamePoints(forest, text, names, ops, Field(forest, item.node, "object")));
                    slots.append(ValueLocal(HandleStorage));
                    code.extend(OwnerWatch(ops, length(slots) - 1, forest[Field(forest, item.node, "object")]));
                }
            }
            if (constant >= 0) {
                code.append(OccurrenceCode(ops, SymbolRecord, constants[constant].occurrence, node));
            }
        }
        // The step a node other than control flow takes.
        stepped := true;
        at: Bases = {pc: length(code), slot: length(slots), local: length(locals), cell: length(cells),
                     host: length(hosts), call: length(calls)};
        step := Fail(forest, item.node, document, "");
        if (kind == "callable_body" || kind == "block") {
            stepped = false;
            if (item.phase == 0) {
                child := FirstMember(forest, item.node);
                while (child >= 0) {
                    next.append(Visit(child));
                    child = NextMember(forest, child);
                }
                next.append(Resume(item.node, 1, length(names), 0));
                scopes.append(length(names));
            } else {
                names = slice(names, 0, item.a);
                scopes = slice(scopes, 0, length(scopes) - 1);
            }
        } else if (kind == "if_statement" || kind == "while_statement") {
            stepped = false;
            // Bindings of the condition's patterns last through the consequence
            // or body; the work item keeps where they start in `c`.
            if (item.phase == 0) {
                head := length(code);
                code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
                next.append(Visit(Field(forest, item.node, "condition")));
                resume := Resume(item.node, 1, head, 0);
                resume.c = length(names);
                next.append(resume);
                scopes.append(length(names));
            } else if (item.phase == 1) {
                value_top -= 1;
                condition := values[value_top];
                if (!Single(condition, BoolStorage)) {
                    return Body.Failed(Diagnose(forest, Field(forest, item.node, "condition"), document,
                                                "condition needs a bool"));
                }
                code.append(Instruction(ops.branch_if, 0, 0, condition.slot, 0, length(code) + 2, node));
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                field := "consequence";
                if (kind == "while_statement") {
                    field = "body";
                    loop: Loop = {head: item.a, first_break: length(breaks), first_continue: length(continues),
                                  each: false, index: -1, mark: length(names), leave: length(code) - 1,
                                  reverse: false, counted: false, bound: -1, empty: -1};
                    loops.append(loop);
                }
                next.append(Visit(Field(forest, item.node, field)));
                resume := Resume(item.node, 2, item.a, length(code) - 1);
                resume.c = item.c;
                next.append(resume);
            } else if (item.phase == 2) {
                names = slice(names, 0, item.c);
                scopes = slice(scopes, 0, length(scopes) - 1);
                alternative := Field(forest, item.node, "alternative");
                if (kind == "while_statement") {
                    code.append(Instruction(ops.jump, 0, 0, 0, 0, item.a, node));
                    loop := loops[length(loops) - 1];
                    loops = slice(loops, 0, length(loops) - 1);
                    at_break := loop.first_break;
                    while (at_break < length(breaks)) {
                        escape := code[breaks[at_break]];
                        escape.target = length(code);
                        code[breaks[at_break]] = escape;
                        at_break += 1;
                    }
                    breaks = slice(breaks, 0, loop.first_break);
                    skip := code[item.b];
                    skip.target = length(code);
                    code[item.b] = skip;
                } else if (alternative >= 0) {
                    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                    skip := code[item.b];
                    skip.target = length(code);
                    code[item.b] = skip;
                    next.append(Visit(alternative));
                    next.append(Resume(item.node, 3, 0, length(code) - 1));
                } else {
                    skip := code[item.b];
                    skip.target = length(code);
                    code[item.b] = skip;
                }
            } else {
                end := code[item.b];
                end.target = length(code);
                code[item.b] = end;
            }
        } else if (kind == "for_statement") {
            if (item.phase == 0) {
                if (Field(forest, item.node, "reference") >= 0) {
                    return Body.Failed(Diagnose(forest, item.node, document, "for loops do not support `ref` yet"));
                }
                stepped = false;
                code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
                if (Field(forest, item.node, "first") >= 0) {
                    // Ranges never count down, so constant bounds that descend
                    // are a mistake, as stage zero reports.
                    if (Descends(forest, text, document, constants, names, callable.package, item.node)) {
                        message := "Range bounds descend; count down with for <";
                        if (Field(forest, item.node, "reverse") >= 0) {
                            message = "Range bounds descend; for < takes the low bound first, as in for < i in 0..10";
                        }
                        return Body.Failed(Diagnose(forest, item.node, document, message));
                    }
                    next.append(Expect(Field(forest, item.node, "first"), IntStorage, 0, -1));
                    next.append(Expect(Field(forest, item.node, "last"), IntStorage, 0, -1));
                    next.append(Resume(item.node, 5, 0, 0));
                } else {
                    next.append(Visit(Field(forest, item.node, "value")));
                    next.append(Resume(item.node, 1, 0, 0));
                }
            } else if (item.phase == 5) {
                // A range loop, as stage zero emits it: the index starts at
                // `first`, or at `last` counting down, and the other end waits
                // in a local. `..<` stops before `last`; reversed, it starts at
                // `last - 1` only once `first < last` shows that cannot wrap.
                stepped = false;
                value_top -= 2;
                ends: int[] = [];
                end_index: int = 0;
                while (end_index < 2) {
                    end := values[value_top + end_index];
                    if (end.container != 0 || !Integer(end.storage) ||
                        (end.storage != IntStorage && !Widens(end.storage, IntStorage))) {
                        return Body.Failed(Diagnose(forest, item.node, document, "range bounds need int values"));
                    }
                    if (end.storage != IntStorage) {
                        slots.append(ValueLocal(IntStorage));
                        code.append(CastCode(ops, IntStorage, length(slots) - 1, end.slot, 0, node));
                        end = Typed(length(slots) - 1, IntStorage, 0, -1);
                    }
                    ends.append(end.slot);
                    end_index += 1;
                }
                reverse := Field(forest, item.node, "reverse") >= 0;
                exclusive := Text(forest, text, Field(forest, item.node, "bound")) == "..<";
                start := ends[0];
                stop := ends[1];
                if (reverse) {
                    start = ends[1];
                    stop = ends[0];
                }
                empty: int = -1;
                if (reverse && exclusive) {
                    slots.append(ValueLocal(BoolStorage));
                    code.append(Instruction(ops.lt, IntStorage, length(slots) - 1, ends[0], ends[1], -1, node));
                    code.append(Instruction(ops.branch_if, 0, 0, length(slots) - 1, 0, length(code) + 2, node));
                    empty = length(code);
                    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                    slots.append(ValueLocal(IntStorage));
                    code.append(ConstantCode(ops, IntStorage, 1, length(slots) - 1, node));
                    slots.append(ValueLocal(IntStorage));
                    code.append(Instruction(ops.sub, IntStorage, length(slots) - 1, ends[1], length(slots) - 2,
                                            -1, node));
                    start = length(slots) - 1;
                }
                locals.append(ValueLocal(IntStorage));
                index_local := length(locals) - 1;
                code.append(Instruction(ops.save, IntStorage, 0, start, 0, index_local, node));
                // The range's name is stored before the loop and at each step.
                code.append(SymbolCode(ops, Field(forest, item.node, "name"), node));
                locals.append(ValueLocal(IntStorage));
                bound_local := length(locals) - 1;
                code.append(Instruction(ops.save, IntStorage, 0, stop, 0, bound_local, node));
                head := length(code);
                code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
                slots.append(ValueLocal(IntStorage));
                code.append(Instruction(ops.local, IntStorage, length(slots) - 1, index_local, 0, 0, node));
                slots.append(ValueLocal(IntStorage));
                code.append(Instruction(ops.local, IntStorage, length(slots) - 1, bound_local, 0, 0, node));
                compare := ops.lt;
                if (reverse) {
                    compare = ops.ge;
                } else if (!exclusive) {
                    compare = ops.le;
                }
                slots.append(ValueLocal(BoolStorage));
                code.append(Instruction(compare, IntStorage, length(slots) - 1, length(slots) - 3,
                                        length(slots) - 2, -1, node));
                code.append(Instruction(ops.branch_if, 0, 0, length(slots) - 1, 0, length(code) + 2, node));
                loop: Loop = {head: head, first_break: length(breaks), first_continue: length(continues), each: true,
                              index: index_local, mark: length(names), leave: length(code), reverse: reverse,
                              counted: !exclusive || reverse, bound: bound_local, empty: empty};
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                loops.append(loop);
                binding: Name = {name: Text(forest, text, Field(forest, item.node, "name")), place: LocalPlace,
                                 index: index_local, storage: IntStorage, container: 0, record: -1, writable: false,
                                 node: Field(forest, item.node, "name")};
                names.append(binding);
                next.append(Visit(Field(forest, item.node, "body")));
                next.append(Resume(item.node, 4, 0, 0));
            } else if (item.phase == 1) {
                // The loop walks its own copy, whatever the body changes, or
                // the array itself when nothing can change it.
                stepped = false;
                value_top -= 1;
                array := values[value_top];
                if (array.container != ArrayContainer && !IsMap(array)) {
                    return Body.Failed(Diagnose(forest, Field(forest, item.node, "value"), document, "for needs an array"));
                }
                if (Unchanging(forest, text, callables, types, names, callable.package, mutated,
                               Field(forest, item.node, "value"))) {
                    cells.append(MovedCell(array));
                    slots.append(AddressSlot(target));
                    code.extend(MoveCode(array, ops, target, length(slots) - 1, length(cells) - 1, node));
                    produced = array;
                } else {
                    retained = array;
                }
                next.append(Resume(item.node, 2, 0, 0));
            } else if (item.phase == 2) {
                // The array or its copy is in the last cell; the step loads each element.
                value_top -= 1;
                if (Text(forest, text, ItemField(forest, item.node)) == "") {
                    return Body.Failed(Diagnose(forest, ItemField(forest, item.node), document,
                                                "Invalid string or embedded NUL"));
                }
                array := values[value_top];
                if (IsMap(array)) {
                    step = MapForStep(forest, text, document, types, array, item, ops, target, at);
                } else {
                    step = ForStep(array, Packable(array.storage, array.record, types, members),
                                   Field(forest, item.node, "reverse") >= 0, ops, target, at, node);
                }
            } else if (item.phase == 3) {
                // A record element was copied, or read in place, into the
                // last cell.
                stepped = false;
                value_top -= 1;
                kept := values[value_top];
                binding: Name = {name: Text(forest, text, ItemField(forest, item.node)), place: CellPlace,
                                 index: length(cells) - 1, storage: StructStorage, container: 0, record: kept.record,
                                 writable: false, node: ItemField(forest, item.node)};
                names.append(binding);
                code.append(SymbolCode(ops, binding.node, node));
                next.append(Visit(Field(forest, item.node, "body")));
                next.append(Resume(item.node, 4, 0, 0));
            } else {
                stepped = false;
                loop := loops[length(loops) - 1];
                loops = slice(loops, 0, length(loops) - 1);
                at_continue := loop.first_continue;
                while (at_continue < length(continues)) {
                    resume := code[continues[at_continue]];
                    resume.target = length(code);
                    code[continues[at_continue]] = resume;
                    at_continue += 1;
                }
                continues = slice(continues, 0, loop.first_continue);
                slots.append(ValueLocal(IntStorage));
                current := length(slots) - 1;
                code.append(Instruction(ops.local, IntStorage, current, loop.index, 0, 0, node));
                // An inclusive or reversed range ends once the index reaches
                // its bound, so neither INT_MAX nor INT_MIN wraps.
                at_bound: int = -1;
                if (loop.counted) {
                    slots.append(ValueLocal(IntStorage));
                    code.append(Instruction(ops.local, IntStorage, length(slots) - 1, loop.bound, 0, 0, node));
                    slots.append(ValueLocal(BoolStorage));
                    code.append(Instruction(ops.eq, IntStorage, length(slots) - 1, current, length(slots) - 2,
                                            -1, node));
                    at_bound = length(code);
                    code.append(Instruction(ops.branch_if, 0, 0, length(slots) - 1, 0, Pending, node));
                }
                slots.append(ValueLocal(IntStorage));
                code.append(ConstantCode(ops, IntStorage, 1, length(slots) - 1, node));
                step_op := ops.add;
                if (loop.reverse) {
                    step_op = ops.sub;
                }
                slots.append(ValueLocal(IntStorage));
                code.append(Instruction(step_op, IntStorage, length(slots) - 1, current, length(slots) - 2,
                                        -1, node));
                code.append(Instruction(ops.save, IntStorage, 0, length(slots) - 1, 0, loop.index, node));
                if (Field(forest, item.node, "bound") >= 0) {
                    code.append(SymbolCode(ops, Field(forest, item.node, "name"), node));
                }
                code.append(Instruction(ops.jump, 0, 0, 0, 0, loop.head, node));
                exits_here: int[] = [loop.leave, at_bound, loop.empty];
                for (pending in exits_here) {
                    if (pending >= 0) {
                        done := code[pending];
                        done.target = length(code);
                        code[pending] = done;
                    }
                }
                at_break := loop.first_break;
                while (at_break < length(breaks)) {
                    escape := code[breaks[at_break]];
                    escape.target = length(code);
                    code[breaks[at_break]] = escape;
                    at_break += 1;
                }
                breaks = slice(breaks, 0, loop.first_break);
                names = slice(names, 0, loop.mark);
            }
        } else if (kind == "switch_statement") {
            if (item.phase == 0) {
                stepped = false;
                code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
                next.append(Visit(Field(forest, item.node, "value")));
                next.append(Resume(item.node, 1, 0, 0));
            } else if (item.phase == 1) {
                // The union waits in a local while each arm tests it in turn.
                stepped = false;
                value_top -= 1;
                subject := values[value_top];
                value_switch := subject.container == 0 && Integer(subject.storage);
                if (!Single(subject, UnionStorage) && !value_switch) {
                    return Body.Failed(Diagnose(forest, Field(forest, item.node, "value"), document,
                                                "switch needs a union or integer value"));
                }
                locals.append(ValueLocal(subject.storage));
                code.append(Instruction(ops.save, subject.storage, 0, subject.slot, 0, length(locals) - 1, node));
                current: Switch = {subject: length(locals) - 1, held: subject.record, first_exit: length(exits),
                                   first_cover: length(covered), defaulted: false, skip: -1, mark: length(names),
                                   value: value_switch, storage: subject.storage, fallback: -1};
                switches.append(current);
                next.append(Resume(item.node, 2, NextArm(forest, Field(forest, item.node, "value")), 0));
            } else if (item.phase == 2 && item.a < 0 && switches[length(switches) - 1].fallback >= 0) {
                // Every value arm missed: the default arm runs last.
                stepped = false;
                current := switches[length(switches) - 1];
                arm := current.fallback;
                current.fallback = -2;
                current.mark = length(names);
                switches[length(switches) - 1] = current;
                scopes.append(length(names));
                next.append(Visit(Field(forest, arm, "body")));
                next.append(Resume(item.node, 3, arm, 1));
            } else if (item.phase == 2 && item.a < 0) {
                stepped = false;
                current := switches[length(switches) - 1];
                if (!current.value && !current.defaulted &&
                    length(covered) - current.first_cover < types[current.held].count) {
                    return Body.Failed(Diagnose(forest, item.node, document,
                                                "Non-exhaustive switch: a union alternative is missing"));
                }
                switches = slice(switches, 0, length(switches) - 1);
                covered = slice(covered, 0, current.first_cover);
                at_exit := current.first_exit;
                while (at_exit < length(exits)) {
                    exit_jump := code[exits[at_exit]];
                    exit_jump.target = length(code);
                    code[exits[at_exit]] = exit_jump;
                    at_exit += 1;
                }
                exits = slice(exits, 0, current.first_exit);
            } else if (item.phase == 2 && switches[length(switches) - 1].value) {
                stepped = false;
                current := switches[length(switches) - 1];
                pattern := Field(forest, item.a, "value");
                if (pattern < 0) {
                    if (current.fallback != -1) {
                        return Body.Failed(Diagnose(forest, item.a, document, "Duplicate default arm"));
                    }
                    current.fallback = item.a;
                    switches[length(switches) - 1] = current;
                    next.append(Resume(item.node, 2, NextArm(forest, item.a), 0));
                } else if (Is(forest, pattern, "variant_pattern")) {
                    return Body.Failed(Diagnose(forest, pattern, document, "an integer switch's arms need values"));
                } else {
                    next.append(Expect(pattern, current.storage, 0, -1));
                    next.append(Resume(item.node, 4, item.a, 0));
                }
            } else if (item.phase == 4) {
                // An integer arm's test: past the arm unless the value equals it.
                stepped = false;
                value_top -= 1;
                candidate := values[value_top];
                current := switches[length(switches) - 1];
                if (candidate.container == 0 && Integer(candidate.storage) && candidate.storage != current.storage &&
                    Widens(candidate.storage, current.storage)) {
                    slots.append(ValueLocal(current.storage));
                    code.append(CastCode(ops, current.storage, length(slots) - 1, candidate.slot, 0, node));
                    candidate = Typed(length(slots) - 1, current.storage, 0, -1);
                }
                if (!Single(candidate, current.storage)) {
                    return Body.Failed(Diagnose(forest, Field(forest, item.a, "value"), document,
                                                "case value differs from the switch value"));
                }
                slots.append(ValueLocal(current.storage));
                code.append(Instruction(ops.local, current.storage, length(slots) - 1, current.subject, 0, 0,
                                        node));
                slots.append(ValueLocal(BoolStorage));
                code.append(Instruction(ops.eq, current.storage, length(slots) - 1, length(slots) - 2,
                                        candidate.slot, -1, node));
                code.append(Instruction(ops.branch_if, 0, 0, length(slots) - 1, 0, length(code) + 2, node));
                current.skip = length(code);
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                current.mark = length(names);
                switches[length(switches) - 1] = current;
                scopes.append(length(names));
                next.append(Visit(Field(forest, item.a, "body")));
                next.append(Resume(item.node, 3, item.a, 0));
            } else if (item.phase == 2) {
                current := switches[length(switches) - 1];
                current.mark = length(names);
                switches[length(switches) - 1] = current;
                scopes.append(length(names));
                pattern := Field(forest, item.a, "value");
                if (pattern < 0) {
                    if (current.defaulted) {
                        return Body.Failed(Diagnose(forest, item.a, document, "Duplicate default arm"));
                    }
                    current.defaulted = true;
                    switches[length(switches) - 1] = current;
                    stepped = false;
                } else {
                    if (!Is(forest, pattern, "variant_pattern")) {
                        return Body.Failed(Diagnose(forest, pattern, document, "switch arms need a variant pattern"));
                    }
                    member := Text(forest, text, Field(forest, pattern, "name"));
                    variant := FindVariant(types, current.held, member);
                    if (variant < 0) {
                        return Body.Failed(Diagnose(forest, pattern, document, format_text("Unknown variant '{}'", member)));
                    }
                    if (current.defaulted || Covers(covered, current.first_cover, variant)) {
                        return Body.Failed(Diagnose(forest, pattern, document, "Unreachable duplicate union pattern"));
                    }
                    covered.append(variant);
                    code.append(ExpressionCode(ops, forest[pattern]));
                    at.pc = length(code);
                    bindings := Field(forest, pattern, "bindings");
                    count: int = 0;
                    binding := FirstMember(forest, bindings);
                    while (binding >= 0) {
                        count += 1;
                        binding = NextMember(forest, binding);
                    }
                    if (count != 0 && count != types[variant].count) {
                        return Body.Failed(Diagnose(forest, pattern, document, "A union payload pattern must bind every field"));
                    }
                    step = MatchStep(forest, text, document, types, members, names, scopes[length(scopes) - 1],
                                     current.subject, -1, variant, bindings, true, false,
                                     Field(forest, item.node, "value"), pattern, ops, target, at, node);
                }
                next.append(Visit(Field(forest, item.a, "body")));
                next.append(Resume(item.node, 3, item.a, 0));
            } else {
                // The arm is done: leave the switch, and send a failed test here.
                stepped = false;
                exits.append(length(code));
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                current := switches[length(switches) - 1];
                if (current.skip >= 0) {
                    skip := code[current.skip];
                    skip.target = length(code);
                    code[current.skip] = skip;
                }
                current.skip = -1;
                switches[length(switches) - 1] = current;
                names = slice(names, 0, current.mark);
                scopes = slice(scopes, 0, length(scopes) - 1);
                if (item.b == 1) {
                    // The default arm of an integer switch was the last.
                    next.append(Resume(item.node, 2, -1, 0));
                } else {
                    next.append(Resume(item.node, 2, NextArm(forest, item.a), 0));
                }
            }
        } else if (kind == "break_statement" || kind == "continue_statement") {
            stepped = false;
            if (length(loops) == 0) {
                return Body.Failed(Diagnose(forest, item.node, document, "break or continue outside a loop"));
            }
            loop := loops[length(loops) - 1];
            code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
            if (kind == "break_statement") {
                breaks.append(length(code));
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
            } else if (loop.each) {
                continues.append(length(code));
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
            } else {
                code.append(Instruction(ops.jump, 0, 0, 0, 0, loop.head, node));
            }
        } else if (logic) {
            // The temporary local holds the answer whichever side decides it.
            stepped = false;
            if (item.phase == 0) {
                next.append(Visit(Field(forest, item.node, "left")));
                next.append(Resume(item.node, 1, 0, 0));
            } else if (item.phase == 1) {
                value_top -= 1;
                left := values[value_top];
                if (!Single(left, BoolStorage)) {
                    return Body.Failed(Diagnose(forest, item.node, document, "logic needs bool operands"));
                }
                locals.append(ValueLocal(BoolStorage));
                answer := length(locals) - 1;
                code.append(Instruction(ops.save, BoolStorage, 0, left.slot, 0, answer, node));
                escape := length(code);
                if (operator == "&&" || operator == "and") {
                    code.append(Instruction(ops.branch_if, 0, 0, left.slot, 0, length(code) + 2, node));
                    escape = length(code);
                    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                } else {
                    code.append(Instruction(ops.branch_if, 0, 0, left.slot, 0, Pending, node));
                }
                next.append(Visit(Field(forest, item.node, "right")));
                next.append(Resume(item.node, 2, answer, escape));
            } else {
                value_top -= 1;
                right := values[value_top];
                if (!Single(right, BoolStorage)) {
                    return Body.Failed(Diagnose(forest, item.node, document, "logic needs bool operands"));
                }
                code.append(Instruction(ops.save, BoolStorage, 0, right.slot, 0, item.a, node));
                escape := code[item.b];
                escape.target = length(code);
                code[item.b] = escape;
                slot: Slot = {storage: BoolStorage, kind: ValueKind};
                slots.append(slot);
                code.append(Instruction(ops.local, BoolStorage, length(slots) - 1, item.a, 0, 0, node));
                produced = Typed(length(slots) - 1, BoolStorage, 0, -1);
            }
        } else if (item.phase == CombinePhase) {
            step = OperatorStep(forest, text, document, values, value_top, item, ops, at);
        } else if (item.phase == ReferencePhase) {
            step = ReferenceArgumentStep(forest, text, document, types, members, names, item, ops, target, at);
        } else if (item.phase == AggregatePhase) {
            step = AggregateStep(forest, text, document, types, members, operators, values, value_top, item, ops,
                                 target, at);
        } else if (kind == "local_declaration" || kind == "assignment" || kind == "expression_statement" ||
                   kind == "return_statement" || kind == "delete_statement") {
            step = StatementStep(forest, text, document, callables, params, types, members, natives, ports, identities, names,
                                 scopes[length(scopes) - 1], callable.package, values, value_top, function, named,
                                 referenced, mutated, built, item, ops, target, at);
        } else if (kind == "number" || kind == "boolean" || kind == "string" || kind == "identifier" ||
                   kind == "parenthesized_expression" || kind == "member_expression" || kind == "index_expression") {
            step = ValueStep(forest, text, document, callables, params, types, members, constants, natives, ports,
                             names, callable.package, values, value_top, item, ops, target, at);
        } else if (kind == "struct_expression" || kind == "array_expression") {
            step = LiteralStep(forest, text, document, types, members, values, value_top, built, item, ops, target, at);
        } else if (kind == "map_expression") {
            step = MapLiteralStep(forest, document, types, values, value_top, item, ops, target, at);
        } else if ((kind == "binary_expression" && (operator == "in" || NotIn(forest, item.node, operator))) ||
                   (kind == "call_expression" &&
                    (item.c == MapHasMark || (item.phase == 0 && MapMethod(forest, text, names, item.node, "has"))))) {
            step = MapHasStep(forest, text, document, types, values, value_top, item, ops, target, at);
        } else if (kind == "call_expression") {
            step = CallStep(forest, text, document, callables, params, types, members, constants, natives, ports, makes,
                            make_fields, names, callable.package, values, value_top, built, item, ops, target, at);
        } else if (kind == "unary_expression" || kind == "binary_expression") {
            step = OperatorStep(forest, text, document, values, value_top, item, ops, at);
        } else if (kind == "function_declaration") {
            step = ParameterStep(params, callable, item, ops, target, at, node);
        } else if (kind == "is_expression" && item.phase == 0) {
            stepped = false;
            next.append(Visit(Field(forest, item.node, "value")));
            next.append(Resume(item.node, 1, 0, 0));
        } else if (kind == "is_expression") {
            step = IsStep(forest, text, document, types, members, names, scopes[length(scopes) - 1], values, value_top,
                          item, ops, target, at);
        } else {
            return Body.Failed(Diagnose(forest, item.node, document, format_text("unsupported syntax '{}'", kind)));
        }
        // Apply the step, then the copy it or the control flow asks for.
        pass: int = 0;
        while (pass < 2) {
            if (pass == 1) {
                stepped = retained.storage != 0;
                if (stepped) {
                    at = {pc: length(code), slot: length(slots), local: length(locals), cell: length(cells),
                          host: length(hosts), call: length(calls)};
                    step = RetainStep(retained, ops, target, at, node);
                }
            }
            if (stepped) {
                switch step {
                    case .Failed(diagnostic):
                        return Body.Failed(diagnostic);
                    case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                                  added_calls, added_names, scheduled, popped, value, kept, marks):
                        code.extend(added_code);
                        slots.extend(added_slots);
                        locals.extend(added_locals);
                        cells.extend(added_cells);
                        hosts.extend(added_hosts);
                        roots.extend(added_roots);
                        calls.extend(added_calls);
                        names.extend(added_names);
                        next.extend(scheduled);
                        value_top -= popped;
                        if (value.storage != 0) {
                            produced = value;
                        }
                        if (pass == 0) {
                            retained = kept;
                        }
                        if (length(marks) == 1) {
                            // A switch arm's test: the jump past the arm.
                            current := switches[length(switches) - 1];
                            current.skip = marks[0];
                            switches[length(switches) - 1] = current;
                        }
                        if (length(marks) == 2) {
                            // A map loop's head, whose step binds its names; leaving
                            // the loop drops them.
                            loop: Loop = {head: marks[0], first_break: length(breaks), first_continue: length(continues),
                                          each: true, index: at.local, mark: length(names) - length(added_names),
                                          leave: marks[1],
                                          reverse: false, counted: false, bound: -1, empty: -1};
                            loops.append(loop);
                        }
                        if (length(marks) == 3) {
                            // A for head: its loop, then its element's binding.
                            reverse := Field(forest, item.node, "reverse") >= 0;
                            loop: Loop = {head: marks[0], first_break: length(breaks), first_continue: length(continues),
                                          each: true, index: marks[2], mark: length(names), leave: marks[1],
                                          reverse: reverse, counted: false, bound: -1, empty: -1};
                            loops.append(loop);
                            // `for x, i in xs` names the item, then the index the loop owns.
                            if (Field(forest, item.node, "key") >= 0 &&
                                Text(forest, text, Field(forest, item.node, "key")) ==
                                Text(forest, text, Field(forest, item.node, "name"))) {
                                return Body.Failed(Diagnose(forest, Field(forest, item.node, "name"), document,
                                                            format_text("Duplicate declaration '{}'",
                                                                        Text(forest, text, Field(forest, item.node, "name")))));
                            }
                            if (Field(forest, item.node, "key") >= 0) {
                                key: Name = {name: Text(forest, text, Field(forest, item.node, "name")), place: LocalPlace,
                                             index: marks[2], storage: IntStorage, container: 0, record: -1,
                                             writable: false, node: Field(forest, item.node, "name")};
                                names.append(key);
                                code.append(SymbolCode(ops, key.node, node));
                            }
                            element := produced;
                            produced = NoValue();
                            if (element.storage == StructStorage &&
                                Unchanging(forest, text, callables, types, names, callable.package, mutated,
                                           Field(forest, item.node, "value"))) {
                                // The array cannot change, so the element is read in place.
                                cells.append(MovedCell(element));
                                slots.append(AddressSlot(target));
                                code.extend(MoveCode(element, ops, target, length(slots) - 1,
                                                     length(cells) - 1, node));
                                produced = element;
                                next.append(Resume(item.node, 3, 0, 0));
                            } else if (element.storage == StructStorage) {
                                retained = element;
                                next.append(Resume(item.node, 3, 0, 0));
                            } else {
                                locals.append(ValueLocal(element.storage));
                                code.append(Instruction(ops.save, element.storage, 0, element.slot, 0,
                                                        length(locals) - 1, node));
                                binding: Name = {name: Text(forest, text, ItemField(forest, item.node)),
                                                 place: LocalPlace, index: length(locals) - 1, storage: element.storage,
                                                 container: 0, record: element.record, writable: false,
                                                 node: ItemField(forest, item.node)};
                                names.append(binding);
                                code.append(SymbolCode(ops, binding.node, node));
                                next.append(Visit(Field(forest, item.node, "body")));
                                next.append(Resume(item.node, 4, 0, 0));
                            }
                        }
                }
            }
            pass += 1;
        }
        // The value an expression produced is watched as its output; the
        // step that gives a number literal its type watches it.
        if (ops.debug && produced.storage > 0 && Expression(kind) && !negated &&
            !ConstantElement(forest, item.node) && !NumberLiteral(forest, item.node)) {
            code.append(WatchCode(ops, produced.slot, produced.storage, produced.container, produced.record,
                                  0, true, node, target));
        }
        // A call's several results are each watched, numbered.
        if (ops.debug && kind == "call_expression" &&
            (produced.storage == FunctionResultsStorage || produced.storage == ResultsStorage)) {
            count: int = 0;
            if (produced.storage == FunctionResultsStorage) {
                count = callables[produced.record].results;
            } else {
                count = natives[produced.record].results;
            }
            at_result: int = 0;
            while (at_result < count) {
                storage: int = 0;
                container: int = 0;
                if (produced.storage == FunctionResultsStorage) {
                    called := callables[produced.record];
                    storage = params[called.first + called.count + at_result].storage;
                } else {
                    linked := natives[produced.record];
                    storage = ports[linked.first + linked.parameters + at_result].storage;
                    container = ports[linked.first + linked.parameters + at_result].container;
                }
                address: Slot = {storage: target.pointer_storage, kind: AddressKind};
                loaded: Slot = {storage: SlotStorage(storage, container, target), kind: SlotKind(storage, container)};
                slots.extend([address, loaded]);
                code.extend(CellRead(loaded.storage, produced.slot + at_result, ops, target, length(slots) - 2,
                                     node));
                code.append(WatchCode(ops, length(slots) - 1, storage, container, -1, at_result, true, node,
                                      target));
                at_result += 1;
            }
        }
        // A compound assignment watches the value it stores at its target.
        if (item.phase == CombinePhase && kind == "assignment" && produced.storage > 0) {
            code.append(WatchCode(ops, produced.slot, produced.storage, produced.container, produced.record,
                                  0, true, forest[Field(forest, item.node, "target")], target));
        }
        if (produced.storage != 0) {
            if (value_top < length(values)) {
                values[value_top] = produced;
            } else {
                values.append(produced);
            }
            value_top += 1;
        }
        // Run scheduled items in order: the last pushed runs first.
        at_next := length(next) - 1;
        while (at_next >= 0) {
            if (work_top < length(work)) {
                work[work_top] = next[at_next];
            } else {
                work.append(next[at_next]);
            }
            work_top += 1;
            at_next -= 1;
        }
    }
    // A function completes at its end, and one with named results returns
    // them.
    points.append(PointAt(key, solid, FunctionRecord, meaning, true, declaration, declaration));
    code.append(PointCode(ops, length(points) - 1, declaration));
    if (callable.results > 0) {
        code.extend(NamedResultsCode(ops, params, callable, named, length(slots), declaration));
        slots.extend(NamedResultsSlots(params, callable));
        code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, declaration));
    }
    code.append(Instruction(ops.end, 0, 0, 0, 0, 0, declaration));
    if (!ops.debug) {
        code = WithoutDebug(ops, code);
        points = [];
    }
    return NumberPoints(forest, solid, undeclared, meaning, document_hash, declaration, ops, slots, locals, cells,
                        code, calls, hosts, roots, points, watches);
}

// A body's tables, with the points and watches the steps placed, each at its
// instruction's position. The runtime numbers each instruction that suspends,
// an invocation or a point, by its order, and a prepared module's bytes hold
// that number.
NumberPoints :: (forest: snapshot.SnapshotNode[], solid: int[], undeclared: uint64, meaning: uint64,
                 document_hash: uint64, declaration: snapshot.SnapshotNode, ops: Ops, slots: Slot[], locals: Slot[],
                 cells: Cell[], code: Code[], calls: Invocation[], hosts: Host[], roots: Root[],
                 points: SourcePoint[], watches: SourceWatch[]) -> Body {
    numbered_code := code;
    numbered_points := points;
    numbered_watches := watches;
    suspension: int = 0;
    at_point: int = 0;
    while (at_point < length(numbered_code)) {
        op := numbered_code[at_point].op;
        if (op == ops.source_point && numbered_code[at_point].left < 0) {
            placed := numbered_code[at_point];
            occurrence := OccurrenceIn(document_hash, ExpressionRecord, solid[placed.start], solid[placed.end]);
            point_meaning: uint64 = 0;
            point_kind := ExpressionRecord;
            if (placed.left == CompletionPoint) {
                occurrence = OccurrenceIn(document_hash, FunctionRecord, solid[declaration.start],
                                          solid[declaration.end]);
                point_meaning = meaning;
                point_kind = FunctionRecord;
            } else if (placed.left == SymbolPoint) {
                occurrence = SymbolOccurrence(forest, document_hash, solid, undeclared, placed.right);
                point_kind = SymbolRecord;
            } else if (placed.left == OccurrencePoint) {
                occurrence = placed.payload;
                point_kind = placed.right;
            }
            point: SourcePoint = {occurrence: occurrence, meaning: point_meaning, start: placed.start, end: placed.end,
                                  line: placed.line, column: placed.column, kind: point_kind,
                                  completion: placed.left == CompletionPoint};
            numbered_points.append(point);
            numbered_code[at_point] = {op: ops.source_point, type: 0, output: 0, left: length(numbered_points) - 1, right: 0,
                                       target: suspension, offset: 0, value_storage: 0, value_container: 0, value_record: -1,
                                       payload: 0, text: "", has_text: false, message: "", has_message: false,
                                       start: placed.start, end: placed.end, line: placed.line, column: placed.column};
            suspension += 1;
        } else if (op == ops.invoke || op == ops.source_point) {
            numbered := numbered_code[at_point];
            numbered.target = suspension;
            numbered_code[at_point] = numbered;
            suspension += 1;
        } else if (op == ops.source_watch) {
            placed := numbered_code[at_point];
            // A default of another document carries its occurrence.
            occurrence := placed.payload;
            if (occurrence == 0) {
                occurrence = OccurrenceIn(document_hash, ExpressionRecord, solid[placed.start], solid[placed.end]);
            }
            watch: SourceWatch = {occurrence: occurrence,
                                  start: placed.start, end: placed.end, line: placed.line, column: placed.column,
                                  storage: placed.value_storage, container: placed.value_container,
                                  record: placed.value_record, ordinal: placed.right, output: placed.output == 1,
                                  reference: placed.offset == 1};
            numbered_watches.append(watch);
            numbered_code[at_point] = Instruction(ops.source_watch, placed.type, 0, placed.left, 0, length(numbered_watches) - 1,
                                                  Located(placed));
        }
        at_point += 1;
    }
    return Body.Emitted(slots, locals, cells, numbered_code, calls, hosts, roots, numbered_points, numbered_watches);
}
package package_compiler

import snapshot "project:source_snapshot"
import strings "core:strings"

// The steps EmitBody takes for nodes other than control flow. Each reads the
// body's tables, which calls share rather than copy, and returns only what it
// adds, numbered from the sizes in `at`.

// Whether an array of this element type may hold its elements inline, with a
// nonzero stride, as the runtime decides: scalars and records of scalars may,
// while strings, unions and records with a string field are always boxed.
Packable :: (storage: int, record: int, types: TypeDecl[], members: TypeMember[]) -> bool {
    if (storage == TextStorage || storage == UnionStorage) {
        return false;
    }
    if (storage != StructStorage) {
        return true;
    }
    at := types[record].first;
    while (at < types[record].first + types[record].count) {
        if (members[at].storage == TextStorage) {
            return false;
        }
        at += 1;
    }
    return true;
}
// The slots ElementRead numbers from its `first`: zero, the lower check, the
// count and the upper check, then the slots of ElementLoad.
ElementSlots :: (storage: int, packable: bool, target: Target) -> Slot[] {
    number: Slot = {storage: IntStorage, kind: ValueKind};
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    checks: Slot[] = [number, flag, number, flag];
    return extend(checks, LoadSlots(storage, packable, target));
}
// Reads the element of the array in slot `array` at the index in slot
// `position` into the last of ElementSlots, after checking 0 <= index < count
// as stage zero does. `pc` is where its code starts; a packable record element
// needs the local `local`.
ElementRead :: (array: int, position: int, storage: int, packable: bool, first: int, pc: int, local: int,
                ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    constant := Instruction(ops.constant, IntStorage, first, 0, 0, 0, node);
    constant.value_storage = IntStorage;
    code.append(constant);
    code.append(Instruction(ops.ge, IntStorage, first + 1, position, first, -1, node));
    code.append(Instruction(ops.guard, 0, 0, first + 1, 0, target.argument_failure, node));
    code.append(Instruction(ops.guard, 0, 0, array, 0, target.argument_failure, node));
    count := Instruction(ops.load, IntStorage, first + 2, array, 0, 0, node);
    count.offset = target.count_offset;
    code.append(count);
    code.append(Instruction(ops.lt, IntStorage, first + 3, position, first + 2, -1, node));
    code.append(Instruction(ops.guard, 0, 0, first + 3, 0, target.argument_failure, node));
    return extend(code, ElementLoad(array, position, storage, packable, first + 4, pc + length(code), local, ops,
                                    target, node));
}
// The slots ElementLoad numbers from its `first`. For an element type that is
// never packed: the array's items, the item and the element. Otherwise: the
// array's items, data and stride, a zero word, whether the array is packed,
// the boxed and the actual element width, the index as a word, its byte
// offset, the base, the item, then for a record its boxed pointer and the
// element, and for any other element the payload offset, the offset to use,
// its address and the element.
LoadSlots :: (storage: int, packable: bool, target: Target) -> Slot[] {
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    word: Slot = {storage: target.pointer_storage, kind: ValueKind};
    element: Slot = {storage: SlotStorage(storage, 0, target), kind: SlotKind(storage, 0)};
    if (!packable) {
        return [address, address, element];
    }
    slots: Slot[] = [address, address, word, word, flag, word, word, word, word, address, address];
    if (storage == StructStorage) {
        return extend(slots, [address, element]);
    }
    return extend(slots, [word, word, address, element]);
}
// Loads the element at the index in slot `position`, already checked, into
// the last of LoadSlots, as stage zero does: a packed array (nonzero stride)
// holds elements inline in `data`, and any other holds value headers in
// `items`. An element type that is never packed reads `items` alone. A packed
// record is the element itself, so the boxed pointer is loaded only past a
// branch, through local `local`; `pc` is where the code starts.
ElementLoad :: (array: int, position: int, storage: int, packable: bool, first: int, pc: int, local: int,
                ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    items := Instruction(ops.load, target.pointer_storage, first, array, 0, 0, node);
    items.offset = target.items_offset;
    code.append(items);
    if (!packable) {
        // The header's payload is the value, or a record's pointer.
        item := Instruction(ops.index, target.pointer_storage, first + 1, first, position, 0, node);
        item.offset = target.value_size;
        code.append(item);
        element := Instruction(ops.load, SlotStorage(storage, 0, target), first + 2, first + 1, 0, 0, node);
        element.offset = target.payload_offset;
        return append(code, element);
    }
    data := Instruction(ops.load, target.pointer_storage, first + 1, array, 0, 0, node);
    data.offset = target.data_offset;
    code.append(data);
    stride := Instruction(ops.load, target.pointer_storage, first + 2, array, 0, 0, node);
    stride.offset = target.stride_offset;
    code.append(stride);
    code.append(ConstantCode(ops, target.pointer_storage, 0, first + 3, node));
    code.append(Instruction(ops.ne, target.pointer_storage, first + 4, first + 2, first + 3, -1, node));
    code.append(ConstantCode(ops, target.pointer_storage, uint64(target.value_size), first + 5, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 6, first + 4, first + 2, first + 5, node));
    code.append(CastCode(ops, target.pointer_storage, first + 7, position, 0, node));
    code.append(Instruction(ops.mul, target.pointer_storage, first + 8, first + 7, first + 6, -1, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 9, first + 4, first + 1, first, node));
    code.append(Instruction(ops.add, target.pointer_storage, first + 10, first + 9, first + 8, -1, node));
    if (storage == StructStorage) {
        code.append(Instruction(ops.save, target.pointer_storage, 0, first + 10, 0, local, node));
        code.append(Instruction(ops.branch_if, 0, 0, first + 4, 0, pc + length(code) + 3, node));
        pointer := Instruction(ops.load, target.pointer_storage, first + 11, first + 10, 0, 0, node);
        pointer.offset = target.payload_offset;
        code.append(pointer);
        code.append(Instruction(ops.save, target.pointer_storage, 0, first + 11, 0, local, node));
        return append(code, Instruction(ops.local, target.pointer_storage, first + 12, local, 0, 0, node));
    }
    code.append(ConstantCode(ops, target.pointer_storage, uint64(target.payload_offset), first + 11, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 12, first + 4, first + 3, first + 11, node));
    code.append(Instruction(ops.add, target.pointer_storage, first + 13, first + 10, first + 12, -1, node));
    return append(code, Instruction(ops.load, SlotStorage(storage, 0, target), first + 14, first + 13, 0, 0, node));
}
// The locals ElementRead and ElementLoad need: one for a packable record
// element.
ElementLocals :: (storage: int, packable: bool, target: Target) -> Slot[] {
    if (storage == StructStorage && packable) {
        return [{storage: target.pointer_storage, kind: AddressKind}];
    }
    return [];
}

// Copies the record or array in slot `kept.slot` into a fresh snapshot cell
// and produces the copy's address.
RetainStep :: (kept: Value, ops: Ops, target: Target, at: Bases, item: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    argument: Cell = {storage: kept.storage, container: kept.container, record: kept.record, constant: 0, variant: -1, kind: ValueKind};
    cells.append(argument);
    cells.append(argument);
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    slots.append(address);
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, at.cell, 0, 0, item));
    write := Instruction(ops.write, target.pointer_storage, 0, kept.slot, at.slot, 0, item);
    write.offset = target.payload_offset;
    code.append(write);
    host: Host = {intrinsic: SnapshotIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 1, result_count: 1,
                  written: false};
    hosts.append(host);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, item));
    slots.append(address);
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + 1, at.cell + 1, 0, 0, item));
    slots.append(address);
    load := Instruction(ops.load, target.pointer_storage, at.slot + 2, at.slot + 1, 0, 0, item);
    load.offset = target.payload_offset;
    code.append(load);
    root: Root = {slot: at.slot + 2, storage: kept.storage, container: kept.container, record: kept.record};
    roots.append(root);
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                        Typed(at.slot + 2, kept.storage, kept.container, kept.record), NoValue(), marks);
}

// The cell a fresh value moves into instead of a copy, and the code that
// gives the cell's header its payload as it stands.
MovedCell :: (value: Value) -> Cell {
    return {storage: value.storage, container: value.container, record: value.record, constant: 0, variant: -1,
            kind: ValueKind};
}
AddressSlot :: (target: Target) -> Slot {
    return {storage: target.pointer_storage, kind: AddressKind};
}
MoveCode :: (value: Value, ops: Ops, target: Target, slot: int, cell: int, item: snapshot.SnapshotNode) -> Code[] {
    write := Instruction(ops.write, target.pointer_storage, 0, value.slot, slot, 0, item);
    write.offset = target.payload_offset;
    return [Instruction(ops.host_slot, target.pointer_storage, slot, cell, 0, 0, item), write];
}

// Statements: local declarations, assignments, expression statements and
// returns, from scheduling to the value's store.
// A function's named results are locals from `named` on.
StatementStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, callables: Callable[],
                  params: Param[], types: TypeDecl[], members: TypeMember[], natives: Native[], ports: Port[],
                  identities: uint64[], names: Name[], scope: int, package: int, values: Value[], top: int,
                  function: int, named: int, referenced: string[], mutated: string[], built: int[], item: Work,
                  ops: Ops, target: Target, at: Bases) -> Step {
    callable := callables[function];
    node := forest[item.node];
    kind := node.kind;
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    popped: int = 0;
    produced := NoValue();
    retained := NoValue();
    // `xs.append(x)` and the other methods that change an array assign the
    // name its changed array, as `xs = append(xs, x)` does.
    changing := ChangedArray(forest, text, names, natives, ports, item.node) >= 0;
    if (item.phase == 0) {
        code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
        value := Field(forest, item.node, "value");
        if (kind == "expression_statement") {
            value = FirstMember(forest, item.node);
        }
        if (kind == "delete_statement" ||
            (kind == "expression_statement" && MapMethod(forest, text, names, value, "delete"))) {
            return MapDeleteStep(forest, text, document, types, names, item, ops, node);
        }
        expected := Visit(value);
        if (kind == "local_declaration") {
            declared := Field(forest, item.node, "type");
            if (declared >= 0) {
                hidden := PrivateType(forest, text, types, names, package, declared);
                if (hidden >= 0) {
                    return Fail(forest, hidden, document, PrivateMessage(Text(forest, text, hidden)));
                }
                resolved := ReadType(forest, text, types, names, package, declared);
                if (resolved.storage == 0) {
                    return Fail(forest, declared, document, "local type is not supported yet");
                }
                expected = Expect(value, resolved.storage, resolved.container, resolved.record);
            }
        } else if (kind == "return_statement") {
            expected = Expect(value, callable.result, callable.result_container, callable.result_record);
        } else if (kind == "assignment" || changing) {
            destination := StatementTarget(forest, item.node);
            operator := CompoundOperator(Text(forest, text, Field(forest, item.node, "operator")));
            whole := SelfComponent(forest, text, types, names, destination);
            owned: int = -1;
            if (Is(forest, destination, "member_expression")) {
                owned = SelfComponent(forest, text, types, names, Field(forest, destination, "object"));
            }
            if (Is(forest, destination, "identifier")) {
                found := Lookup(names, Text(forest, text, destination));
                if (found >= 0) {
                    binding := names[found];
                    expected = Expect(value, binding.storage, binding.container, binding.record);
                    // `xs = append(xs, x)` and `xs = extend(xs, ys)` on a
                    // local array update it in place.
                    update: int = -1;
                    // A method call updates in place only as its own statement;
                    // `xs = xs.append(x)` is an error CallStep reports.
                    if (operator == "" &&
                        (changing || !Is(forest, Field(forest, value, "function"), "member_expression"))) {
                        update = InPlaceUpdate(forest, text, callables, natives, ports, identities, names, package,
                                               found, destination, value);
                    }
                    if (update >= 0) {
                        // Stage zero evaluates the target, the call and the
                        // array it updates, as their points show; it writes a
                        // parameter through the reference the target reads.
                        if (Parameter(forest, binding)) {
                            code.extend(NamePoints(forest, text, names, ops, destination));
                        } else {
                            code.append(ExpressionCode(ops, forest[destination]));
                        }
                        code.append(ExpressionCode(ops, forest[value]));
                        code.extend(NamePoints(forest, text, names, ops, ArrayArgument(forest, value)));
                        argument := ItemArgument(forest, value);
                        container: int = 0;
                        if (update == 1) {
                            container = ArrayContainer;
                        }
                        next.append(Expect(argument, binding.storage, container, binding.record));
                        next.append(Resume(item.node, PushPhase, found, update));
                        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                            NoValue(), retained, marks);
                    }
                    if (operator != "" || Parameter(forest, binding)) {
                        code.extend(NamePoints(forest, text, names, ops, destination));
                    }
                }
            } else if (whole >= 0) {
                code.extend(TargetPoints(forest, text, names, ops, destination));
                // The target's owner is watched as `self`, in a slot before
                // the component step's.
                code.extend(OwnerWatch(ops, at.slot, forest[TargetRoot(forest, destination)]));
                shifted := SlotsPast(at, 1);
                // `self.C op= v` combines the owner's component with the value
                // and writes the result through the reference it read.
                write := Resume(item.node, ComponentAssignPhase, shifted.slot + ComponentReferenceSlot, whole);
                if (operator == "") {
                    return PrefixSlots([ValueLocal(HandleStorage)],
                                       ComponentMakeStep(code, types, whole, [Visit(value), write], ops, target, shifted,
                                                         node));
                }
                combine := Resume(item.node, CombinePhase, 0, 0);
                return PrefixSlots([ValueLocal(HandleStorage)],
                                   ComponentReadStep(code, types, whole, true, -1, [Visit(value), combine, write], ops,
                                                     target, shifted, node));
            } else if (owned >= 0) {
                // `self.C.f = v` on a component of the owner.
                code.extend(TargetPoints(forest, text, names, ops, destination));
                member := Text(forest, text, Field(forest, destination, "member"));
                field := FindField(types, members, owned, member);
                if (field < 0) {
                    return Fail(forest, destination, document, format_text("Unknown field '{}'", member));
                }
                if (members[field].c_string) {
                    message := CStringMessage(forest, text, value, members[field].name);
                    if (message != "") {
                        return Fail(forest, value, document, message);
                    }
                }
                if (!members[field].writable) {
                    return Fail(forest, destination, document, "Assignment requires a writable value");
                }
                code.extend(OwnerWatch(ops, at.slot, forest[TargetRoot(forest, destination)]));
                return PrefixSlots([ValueLocal(HandleStorage)],
                                   ComponentReferenceStep(code, types, members, owned, field, value, operator != "",
                                                          item, ops, target, SlotsPast(at, 1), node));
            } else if (Is(forest, destination, "member_expression")) {
                // `x.f = v` on a local record, written as stage zero writes it.
                object := Field(forest, destination, "object");
                found: int = -1;
                if (Is(forest, object, "identifier")) {
                    found = Lookup(names, Text(forest, text, object));
                }
                if (found >= 0 && !names[found].writable) {
                    return Fail(forest, destination, document, "Assignment requires a writable value");
                }
                if (found < 0 || (names[found].place != CellPlace && names[found].place != ReferencePlace) ||
                    names[found].storage != StructStorage || names[found].container != 0) {
                    return Fail(forest, destination, document, "field assignment needs a local record");
                }
                member := Text(forest, text, Field(forest, destination, "member"));
                field := FindField(types, members, names[found].record, member);
                if (field < 0) {
                    return Fail(forest, destination, document, format_text("Unknown field '{}'", member));
                }
                if (members[field].c_string) {
                    message := CStringMessage(forest, text, value, members[field].name);
                    if (message != "") {
                        return Fail(forest, value, document, message);
                    }
                }
                code.extend(TargetPoints(forest, text, names, ops, destination));
                next.append(Expect(value, members[field].storage, 0, -1));
                write := Resume(item.node, FieldPhase, found, field);
                if (operator != "") {
                    write.c = 1;
                }
                next.append(write);
                return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                    NoValue(), retained, marks);
            } else if (Is(forest, destination, "index_expression")) {
                // `xs[i] = x` on a local array stores in place.
                object := Field(forest, destination, "object");
                found: int = -1;
                if (Is(forest, object, "identifier")) {
                    found = Lookup(names, Text(forest, text, object));
                }
                if (found >= 0 && names[found].container == MapContainer) {
                    return MapStoreStep(forest, text, document, types, names, found, item, ops, node);
                }
                if (found < 0 || names[found].place != CellPlace || names[found].container != ArrayContainer ||
                    !names[found].writable) {
                    return Fail(forest, destination, document, "element assignment needs a local array");
                }
                binding := names[found];
                compound: int = 0;
                code.append(ExpressionCode(ops, forest[destination]));
                if (operator != "") {
                    compound = 1;
                }
                if (operator != "" || Parameter(forest, binding)) {
                    code.extend(NamePoints(forest, text, names, ops, object));
                }
                next.append(Expect(Field(forest, destination, "index"), IntStorage, 0, -1));
                next.append(Expect(value, binding.storage, 0, binding.record));
                next.append(Resume(item.node, StorePhase, found, compound));
                return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                    NoValue(), retained, marks);
            }
        }
        if (kind == "return_statement" && callable.results > 0) {
            return NamedReturnStep(forest, document, code, params, callable, named, value, item, ops, at, node);
        }
        if (kind == "return_statement" && value < 0) {
            if (callable.result != 0) {
                return Fail(forest, item.node, document, "return needs a value");
            }
            code.append(CompletionCode(ops, node));
            code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, node));
        } else {
            next.append(expected);
            next.append(Resume(item.node, ValuePhase, 0, 0));
        }
    } else if (item.phase == ValuePhase) {
        popped = 1;
        result := values[top - 1];
        if (result.storage < 0 && result.storage != NumberStorage && !Single(result, ResultsStorage) &&
            !Single(result, FunctionResultsStorage) && kind != "expression_statement") {
            return Fail(forest, item.node, document, "call has no value");
        }
        if (kind == "local_declaration") {
            declared := Field(forest, item.node, "type");
            local := result;
            if (declared < 0 && result.storage == NumberStorage) {
                return Fail(forest, Field(forest, item.node, "value"), document,
                            "an untyped number is a double; give the local an integer type");
            }
            if (declared >= 0) {
                resolved := ReadType(forest, text, types, names, package, declared);
                local = Typed(-1, resolved.storage, resolved.container, resolved.record);
            }
            if (result.container == 0 && local.container == 0 && Widens(result.storage, local.storage)) {
                widened: Slot = {storage: local.storage, kind: ValueKind};
                slots.append(widened);
                code.append(CastCode(ops, local.storage, at.slot + length(slots) - 1, result.slot, 0, node));
                result = Typed(at.slot + length(slots) - 1, local.storage, 0, -1);
            }
            if (!SameType(local.storage, local.container, local.record, result)) {
                return Fail(forest, item.node, document, "local value differs from its type");
            }
            name := Text(forest, text, Field(forest, item.node, "name"));
            if (name == "") {
                return Fail(forest, Field(forest, item.node, "name"), document, "Invalid string or embedded NUL");
            }
            if (Declared(names, scope, name)) {
                return Fail(forest, Field(forest, item.node, "name"), document, format_text("Duplicate declaration '{}'", name));
            }
            if ((Single(result, ResultsStorage) || Single(result, FunctionResultsStorage)) && declared < 0) {
                // The local reads the call's result cells.
                binding: Name = {name: name, place: ResultsPlace, index: result.slot, storage: result.storage,
                                 container: 0, record: result.record, writable: false,
                                 node: Field(forest, item.node, "name")};
                bound.append(binding);
            } else if (Pointer(local.storage, local.container)) {
                // The local is the cell that holds its own copy, or the value
                // itself when it is fresh, or when neither it nor what it
                // reads ever changes.
                code.append(SymbolCode(ops, Field(forest, item.node, "name"), node));
                if (Fresh(forest, text, callables, types, names, package, Field(forest, item.node, "value")) ||
                    (!Holds(mutated, name) &&
                     Unchanging(forest, text, callables, types, names, package, mutated, Field(forest, item.node, "value")))) {
                    cells.append(MovedCell(result));
                    slots.append(AddressSlot(target));
                    code.extend(MoveCode(result, ops, target, at.slot + length(slots) - 1,
                                         at.cell + length(cells) - 1, node));
                    produced = result;
                } else {
                    retained = result;
                }
                next.append(Resume(item.node, RetainedPhase, 0, 0));
            } else if (Holds(referenced, name)) {
                // A ref argument reaches it, so it lives in a data cell.
                return BoxStep(forest, text, local, result, item, ops, target, at, node);
            } else {
                locals.append(ValueLocal(local.storage));
                code.append(Instruction(ops.save, local.storage, 0, result.slot, 0, at.local, node));
                code.append(SymbolCode(ops, Field(forest, item.node, "name"), node));
                binding: Name = {name: name, place: LocalPlace, index: at.local, storage: local.storage, container: 0,
                                 record: local.record, writable: true, node: Field(forest, item.node, "name")};
                bound.append(binding);
            }
        } else if (kind == "assignment" || changing) {
            destination := StatementTarget(forest, item.node);
            found: int = -1;
            if (Is(forest, destination, "identifier")) {
                found = Lookup(names, Text(forest, text, destination));
            }
            if (found < 0 || names[found].place == ParameterPlace || names[found].place == AliasPlace ||
                names[found].place == SelfPlace) {
                return Fail(forest, destination, document, "assignment needs a local name");
            }
            if (names[found].place == ResultsPlace) {
                return Fail(forest, destination, document, "assigning a native's several results is not supported yet");
            }
            if (!names[found].writable) {
                return Fail(forest, destination, document, "Assignment requires a writable value");
            }
            binding := names[found];
            if (binding.place == ReferencePlace || binding.place == BoxPlace) {
                return PlaceAssignStep(forest, text, document, binding, result, item, ops, target, at, node);
            }
            stored := result;
            operator := CompoundOperator(Text(forest, text, Field(forest, item.node, "operator")));
            if (binding.container == 0 && result.container == 0 && Widens(result.storage, binding.storage)) {
                widened: Slot = {storage: binding.storage, kind: ValueKind};
                slots.append(widened);
                code.append(CastCode(ops, binding.storage, at.slot + length(slots) - 1, result.slot, 0, node));
                result = Typed(at.slot + length(slots) - 1, binding.storage, 0, -1);
                stored = result;
            }
            if (operator != "") {
                op := BinaryOp(ops, operator);
                if (op < 0 || Comparison(ops, op) || !Numeric(binding.storage) || binding.container != 0 ||
                    !Single(result, binding.storage)) {
                    return Fail(forest, item.node, document, "compound assignment needs number operands of its type");
                }
                if (!Computes(ops, op, binding.storage)) {
                    return Fail(forest, item.node, document, "unsupported arithmetic type");
                }
                current: Slot = {storage: binding.storage, kind: ValueKind};
                slots.append(current);
                read := ops.local;
                if (binding.place == StatePlace) {
                    read = ops.variable;
                }
                code.append(Instruction(read, binding.storage, at.slot + length(slots) - 1, binding.index, 0,
                                        0, node));
                // Stage zero watches the target it reads and the value it
                // stores.
                code.append(ScalarWatch(ops, at.slot + length(slots) - 1, binding.storage, 0, true,
                                        forest[destination]));
                slots.append(current);
                code.append(Instruction(op, binding.storage, at.slot + length(slots) - 1,
                                        at.slot + length(slots) - 2, result.slot, -1, node));
                code.append(ScalarWatch(ops, at.slot + length(slots) - 1, binding.storage, 0, true,
                                        forest[destination]));
                stored = Typed(at.slot + length(slots) - 1, binding.storage, 0, -1);
            }
            if (!SameType(binding.storage, binding.container, binding.record, stored)) {
                return Fail(forest, item.node, document, "assigned value differs from its local");
            }
            if (binding.place == CellPlace) {
                // A fresh value replaces the cell's payload without a copy.
                if (Fresh(forest, text, callables, types, names, package, StatementValue(forest, item.node))) {
                    produced = stored;
                } else {
                    retained = stored;
                }
                next.append(Resume(item.node, RetainedPhase, binding.index, 0));
            } else if (binding.place == StatePlace) {
                code.append(Instruction(ops.store, binding.storage, 0, stored.slot, 0, binding.index, node));
            } else {
                code.append(Instruction(ops.save, binding.storage, 0, stored.slot, 0, binding.index, node));
            }
            if (!Parameter(forest, binding)) {
                code.append(SymbolCode(ops, binding.node, node));
            }
        } else if (kind == "return_statement") {
            if (result.container == 0 && callable.result_container == 0 && Widens(result.storage, callable.result)) {
                widened: Slot = {storage: callable.result, kind: ValueKind};
                slots.append(widened);
                code.append(CastCode(ops, callable.result, at.slot + length(slots) - 1, result.slot, 0, node));
                result = Typed(at.slot + length(slots) - 1, callable.result, 0, -1);
            }
            if (!SameType(callable.result, callable.result_container, callable.result_record, result)) {
                return Fail(forest, item.node, document, "returned value differs from the result type");
            }
            if (Pointer(result.storage, result.container) &&
                (Fresh(forest, text, callables, types, names, package, Field(forest, item.node, "value")) ||
                 BuiltName(forest, text, names, built, Field(forest, item.node, "value")))) {
                // A fresh value is already the copy a return would make, and
                // a built local already lies in the caller's storage.
                cells.append(MovedCell(result));
                slots.append(AddressSlot(target));
                code.extend(MoveCode(result, ops, target, at.slot + length(slots) - 1,
                                     at.cell + length(cells) - 1, node));
                produced = result;
                next.append(Resume(item.node, RetainedPhase, -1, 0));
            } else if (Pointer(result.storage, result.container)) {
                retained = result;
                next.append(Resume(item.node, RetainedPhase, -1, 0));
            } else {
                code.append(SymbolCode(ops, -1, forest[Field(forest, item.node, "value")]));
                code.append(CompletionCode(ops, node));
                code.append(Instruction(ops.result, result.storage, 0, result.slot, 0, 0, node));
                code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, node));
            }
        }
    } else if (item.phase == FieldPhase) {
        popped = 1;
        return FieldStep(forest, text, document, names[item.a], members[item.b], values[top - 1], item, ops, target, at,
                         node);
    } else if (item.phase == ComponentPhase) {
        return ComponentWriteStep(forest, text, document, members[item.b], values[top - 1], item, ops, target, at,
                                  node);
    } else if (item.phase == ComponentAssignPhase) {
        return ComponentAssignStep(forest, document, types, values[top - 1], item, ops, target, at, node);
    } else if (item.phase == ReturnsPhase) {
        return ResultsStep(forest, document, params, callable, values, top, item, ops, at, node);
    } else if (item.phase == MapStorePhase || item.phase == MapDeletePhase) {
        return MapUpdateStep(forest, text, document, types, names, values, top, item, ops, target, at, node);
    } else if (item.phase == RetainedPhase) {
        // A retained copy or a moved fresh value, in the last cell: bind it,
        // store it in a local's cell, or publish its header.
        popped = 1;
        kept := values[top - 1];
        address: Slot = {storage: target.pointer_storage, kind: AddressKind};
        if (kind == "local_declaration") {
            binding: Name = {name: Text(forest, text, Field(forest, item.node, "name")), place: CellPlace,
                             index: at.cell - 1, storage: kept.storage, container: kept.container, record: kept.record,
                             writable: true, node: Field(forest, item.node, "name")};
            bound.append(binding);
        } else if (kind == "assignment" || changing) {
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, item.a, 0, 0, node));
            write := Instruction(ops.write, target.pointer_storage, 0, kept.slot, at.slot, 0, node);
            write.offset = target.payload_offset;
            code.append(write);
        } else {
            // Copy the cell's whole header, type name and layout included,
            // into result zero.
            code.append(SymbolCode(ops, -1, forest[Field(forest, item.node, "value")]));
            code.append(CompletionCode(ops, node));
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, at.cell - 1, 0, 0, node));
            slots.append(address);
            context := Instruction(ops.context, target.pointer_storage, at.slot + 1, 0, 0, 0, node);
            context.offset = target.results_offset;
            code.append(context);
            zero: Slot = {storage: IntStorage, kind: ValueKind};
            slots.append(zero);
            constant := Instruction(ops.constant, IntStorage, at.slot + 2, 0, 0, 0, node);
            constant.value_storage = IntStorage;
            code.append(constant);
            slots.append(address);
            element := Instruction(ops.index, target.pointer_storage, at.slot + 3, at.slot + 1, at.slot + 2, 0, node);
            element.offset = target.value_size;
            code.append(element);
            header: int[] = [target.type_offset, target.container_offset, target.name_offset,
                             target.record_offset, target.payload_offset];
            part: int = 0;
            while (part < 5) {
                loaded := address;
                if (part < 2) {
                    loaded = zero;
                }
                slots.append(loaded);
                load := Instruction(ops.load, loaded.storage, at.slot + length(slots) - 1, at.slot, 0, 0, node);
                load.offset = header[part];
                code.append(load);
                store := Instruction(ops.write, loaded.storage, 0, at.slot + length(slots) - 1, at.slot + 3, 0, node);
                store.offset = header[part];
                code.append(store);
                part += 1;
            }
            code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, node));
        }
    } else {
        // An in-place update of the local array names[item.a]: a push or an
        // extension, or an element store (compound when item.b is 1).
        binding := names[item.a];
        item_value := NoValue();
        index_value := NoValue();
        intrinsic := ArrayStoreIntrinsic;
        item_container: int = 0;
        if (item.phase == PushPhase) {
            popped = 1;
            item_value = values[top - 1];
            intrinsic = ArrayPushIntrinsic;
            if (item.b == 1) {
                intrinsic = ArrayExtendIntrinsic;
                item_container = ArrayContainer;
            }
        } else if (item.b == 1) {
            // Read the element at the index already evaluated, then combine.
            popped = 2;
            index_value = values[top - 2];
            operand := values[top - 1];
            op := BinaryOp(ops, CompoundOperator(Text(forest, text, Field(forest, item.node, "operator"))));
            if (op < 0 || Comparison(ops, op) || binding.storage != IntStorage || !Single(operand, IntStorage)) {
                return Fail(forest, item.node, document, "compound assignment needs int operands");
            }
            if (!Single(index_value, IntStorage)) {
                return Fail(forest, item.node, document, "index needs an int");
            }
            address: Slot = {storage: target.pointer_storage, kind: AddressKind};
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, binding.index, 0, 0, node));
            slots.append(address);
            load := Instruction(ops.load, target.pointer_storage, at.slot + 1, at.slot, 0, 0, node);
            load.offset = target.payload_offset;
            code.append(load);
            root: Root = {slot: at.slot + 1, storage: IntStorage, container: ArrayContainer, record: -1};
            roots.append(root);
            slots.extend(ElementSlots(IntStorage, true, target));
            code.extend(ElementRead(at.slot + 1, index_value.slot, IntStorage, true, at.slot + 2,
                                    at.pc + length(code), -1, ops, target, node));
            element := at.slot + length(slots) - 1;
            code.append(ScalarWatch(ops, element, IntStorage, 0, true,
                                    forest[Field(forest, item.node, "target")]));
            combined: Slot = {storage: IntStorage, kind: ValueKind};
            slots.append(combined);
            code.append(Instruction(op, IntStorage, element + 1, element, operand.slot, -1, node));
            item_value = Typed(element + 1, IntStorage, 0, -1);
        } else {
            popped = 2;
            index_value = values[top - 2];
            item_value = values[top - 1];
        }
        if (intrinsic == ArrayStoreIntrinsic && !Single(index_value, IntStorage)) {
            return Fail(forest, item.node, document, "index needs an int");
        }
        if (!SameType(binding.storage, item_container, binding.record, item_value)) {
            return Fail(forest, item.node, document, "array item differs from the array's type");
        }
        // The intrinsic takes the local's header address, then the index of a
        // store, then the item; it returns a bool.
        address_cell: Cell = {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: AddressKind};
        cells.append(address_cell);
        sources: int[] = [-1];
        storages: int[] = [target.pointer_storage];
        if (intrinsic == ArrayStoreIntrinsic) {
            index_cell: Cell = {storage: IntStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
            cells.append(index_cell);
            sources.append(index_value.slot);
            storages.append(IntStorage);
        }
        item_cell: Cell = {storage: binding.storage, container: item_container, record: binding.record, constant: 0, variant: -1,
                           kind: ValueKind};
        cells.append(item_cell);
        sources.append(item_value.slot);
        storages.append(SlotStorage(item_value.storage, item_value.container, target));
        done: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
        cells.append(done);
        address: Slot = {storage: target.pointer_storage, kind: AddressKind};
        slots.append(address);
        header_slot := at.slot + length(slots) - 1;
        code.append(Instruction(ops.host_slot, target.pointer_storage, header_slot, binding.index, 0, 0, node));
        sources[0] = header_slot;
        // A push watches the array it reads, as the array argument and the
        // call's first input, and the item as its second.
        call := StatementValue(forest, item.node);
        if (item.phase == PushPhase && ops.debug) {
            slots.append(address);
            read := Instruction(ops.load, target.pointer_storage, at.slot + length(slots) - 1, header_slot, 0, 0, node);
            read.offset = target.payload_offset;
            code.append(read);
            array_slot := at.slot + length(slots) - 1;
            code.append(WatchCode(ops, array_slot, binding.storage, ArrayContainer, binding.record, 0, true,
                                  forest[ArrayArgument(forest, call)], target));
            code.append(WatchCode(ops, array_slot, binding.storage, ArrayContainer, binding.record, 0, false,
                                  forest[call], target));
            code.append(WatchCode(ops, item_value.slot, item_value.storage, item_value.container,
                                  item_value.record, 1, false, forest[call], target));
        }
        argument: int = 0;
        while (argument < length(sources)) {
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1,
                                    at.cell + argument, 0, 0, node));
            write := Instruction(ops.write, storages[argument], 0, sources[argument], at.slot + length(slots) - 1, 0, node);
            write.offset = target.payload_offset;
            code.append(write);
            argument += 1;
        }
        // A local the function returns grows in its caller's storage.
        if (built.contains(binding.node)) {
            intrinsic += InResult;
        }
        host: Host = {intrinsic: intrinsic, linked: -1, first: at.cell, result_first: at.cell + length(cells) - 1,
                      result_count: 1, written: false};
        hosts.append(host);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        // The array a push leaves is the call's watched output.
        if (item.phase == PushPhase && ops.debug) {
            slots.append(address);
            reread := Instruction(ops.load, target.pointer_storage, at.slot + length(slots) - 1, header_slot, 0, 0, node);
            reread.offset = target.payload_offset;
            code.append(reread);
            code.append(WatchCode(ops, at.slot + length(slots) - 1, binding.storage, ArrayContainer,
                                  binding.record, 0, true, forest[call], target));
        }
        // A push or a plain element store stores a local array; a push then
        // evaluates it again.
        if ((item.phase == PushPhase || item.b == 0) && !Parameter(forest, binding)) {
            code.append(SymbolCode(ops, binding.node, node));
        }
        if (item.phase == PushPhase && !Parameter(forest, binding)) {
            code.extend(NamePoints(forest, text, names, ops,
                                   ArrayArgument(forest, StatementValue(forest, item.node))));
        }
    }
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, retained, marks);
}

// Literals, names, parentheses, field reads and element reads.
ValueStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, callables: Callable[],
              params: Param[], types: TypeDecl[], members: TypeMember[], constants: ConstDecl[], natives: Native[],
              ports: Port[], names: Name[], package: int, values: Value[], top: int, item: Work, ops: Ops,
              target: Target, at: Bases) -> Step {
    node := forest[item.node];
    kind := node.kind;
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    popped: int = 0;
    produced := NoValue();
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    if (item.phase == 0 && kind == "member_expression") {
        hidden := PrivateAccess(forest, text, callables, types, constants, names, package, item.node);
        if (hidden >= 0) {
            return Fail(forest, hidden, document, PrivateMessage(Text(forest, text, hidden)));
        }
    }
    if (kind == "number" && Floating(item.storage)) {
        // A literal where a floating value is expected is one.
        return FloatConstantStep(forest, text, document, Typed(-1, NumberStorage, 0, item.node), item.storage, ops, at,
                                 node);
    }
    if (kind == "number" && !Integer(item.storage)) {
        // An untyped literal: its use gives it a type.
        produced = Typed(-1, NumberStorage, 0, item.node);
    } else if (kind == "number" || kind == "boolean" || kind == "string") {
        storage := item.storage;
        payload: uint64 = 0;
        literal := "";
        if (kind == "number") {
            switch ParseNumber(forest, text, item.node) {
                case .Invalid:
                    return Fail(forest, item.node, document, "only integer literals of 64 bits are supported");
                case .Number(negative, magnitude):
                    if (!Fits(negative, magnitude, storage)) {
                        return Fail(forest, item.node, document,
                                    format_text("Numeric literal is outside the range of {}", TypeName(storage)));
                    }
                    payload = Bits(negative, magnitude);
            }
        } else if (kind == "boolean") {
            storage = BoolStorage;
            if (Text(forest, text, item.node) == "true") {
                payload = 1;
            }
        } else {
            // String literals are JSON strings.
            storage = TextStorage;
            decoded := compiler_json_value_string(Text(forest, text, item.node));
            if (!decoded.valid) {
                return Fail(forest, item.node, document, "Invalid string literal");
            }
            literal = decoded.value;
        }
        slot: Slot = {storage: storage, kind: ValueKind};
        slots.append(slot);
        constant := ConstantCode(ops, storage, payload, at.slot, node);
        constant.text = literal;
        constant.has_text = kind == "string";
        code.append(constant);
        if (kind == "number") {
            code.extend(LiteralWatch(forest, ops, at.slot, storage, item.node));
        }
        produced = Typed(at.slot, storage, 0, -1);
    } else if (item.phase == 0 && (kind == "identifier" || kind == "member_expression") &&
               ConstantOf(forest, text, constants, names, package, item.node) >= 0) {
        // A package constant is its value.
        declared := constants[ConstantOf(forest, text, constants, names, package, item.node)];
        slot: Slot = {storage: declared.storage, kind: ValueKind};
        slots.append(slot);
        code.append(ConstantCode(ops, declared.storage, declared.bits, at.slot, node));
        produced = Typed(at.slot, declared.storage, 0, -1);
    } else if (kind == "identifier") {
        wanted := Text(forest, text, item.node);
        found := Lookup(names, wanted);
        if (found < 0 || names[found].place == AliasPlace) {
            return Fail(forest, item.node, document, format_text("Unknown name '{}'", wanted));
        }
        binding := names[found];
        if (binding.place == ResultsPlace) {
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                Typed(binding.index, binding.storage, 0, binding.record), NoValue(), marks);
        }
        if (binding.place == GlobalPlace) {
            return Fail(forest, item.node, document,
                        format_text("reading the global '{}' is not supported yet", wanted));
        }
        if (binding.place == ReferencePlace || binding.place == BoxPlace) {
            return PlaceReadStep(binding, ops, target, at, node);
        }
        if (binding.place == LocalPlace || binding.place == StatePlace || binding.place == SelfPlace) {
            op := ops.local;
            if (binding.place == StatePlace) {
                op = ops.variable;
            } else if (binding.place == SelfPlace) {
                op = ops.owner;
            }
            slot: Slot = {storage: binding.storage, kind: ValueKind};
            slots.append(slot);
            code.append(Instruction(op, binding.storage, at.slot, binding.index, 0, 0, node));
        } else {
            slots.append(address);
            if (binding.place == CellPlace) {
                code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, binding.index, 0, 0, node));
                slots.append(address);
                load := Instruction(ops.load, target.pointer_storage, at.slot + 1, at.slot, 0, 0, node);
                load.offset = target.payload_offset;
                code.append(load);
            } else {
                read := Instruction(ops.array, target.pointer_storage, at.slot, binding.index, 0, ops.argument, node);
                read.value_storage = binding.storage;
                read.value_container = binding.container;
                read.value_record = binding.record;
                code.append(read);
            }
            root: Root = {slot: at.slot + length(slots) - 1, storage: binding.storage, container: binding.container,
                          record: binding.record};
            roots.append(root);
        }
        produced = Typed(at.slot + length(slots) - 1, binding.storage, binding.container, binding.record);
    } else if (kind == "parenthesized_expression") {
        next.append(Expect(Field(forest, item.node, "expression"), item.storage, item.container, item.record));
    } else if (item.phase == 0 && kind == "member_expression" &&
               UnionOf(forest, text, types, names, package, item.node) >= 0) {
        // A variant without a payload: the constructor takes only its tag.
        sum_type := UnionOf(forest, text, types, names, package, item.node);
        member := Text(forest, text, Field(forest, item.node, "member"));
        variant := FindVariant(types, sum_type, member);
        if (variant < 0) {
            return Fail(forest, item.node, document, format_text("Unknown variant '{}'", member));
        }
        if (types[variant].count != 0) {
            return Fail(forest, item.node, document, format_text("variant '{}' needs its payload", member));
        }
        tag: Cell = {storage: WordStorage, container: 0, record: -1, constant: 0, variant: variant, kind: ValueKind};
        cells.append(tag);
        made: Cell = {storage: UnionStorage, container: 0, record: sum_type, constant: 0, variant: -1, kind: ValueKind};
        cells.append(made);
        host: Host = {intrinsic: UnionMakeIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 1,
                      result_count: 1, written: false};
        hosts.append(host);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, at.cell + 1, 0, 0, node));
        value: Slot = {storage: UnionStorage, kind: ValueKind};
        slots.append(value);
        load := Instruction(ops.load, UnionStorage, at.slot + 1, at.slot, 0, 0, node);
        load.offset = target.payload_offset;
        code.append(load);
        produced = Typed(at.slot + 1, UnionStorage, 0, sum_type);
    } else if (item.phase == 0 && kind == "member_expression" &&
               KeyedMember(forest, text, types, members, names, item.node) >= 0) {
        // A global's keyed field, such as a scene binding, a native reads by
        // its key.
        field := members[KeyedMember(forest, text, types, members, names, item.node)];
        key: Value = {slot: at.slot, storage: ports[natives[field.read].first].storage, container: 0, record: -1};
        constant := ConstantCode(ops, key.storage, 0, at.slot, node);
        constant.text = field.read_key;
        constant.has_text = true;
        shifted: Bases = {pc: at.pc + 1, slot: at.slot + 1, local: at.local, cell: at.cell, host: at.host,
                          call: at.call};
        switch NativeReadStep(key, field, ops, target, shifted, node) {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(read_code, read_slots, read_locals, read_cells, read_hosts, read_roots, read_calls,
                          read_bound, read_next, read_popped, read_value, read_retain, read_marks):
                read := Typed(read_value.slot, read_value.storage, 0, field.record);
                return Step.Emitted(extend([constant], read_code), extend([ValueLocal(key.storage)], read_slots),
                                    read_locals, read_cells, read_hosts, read_roots, read_calls, read_bound,
                                    read_next, 0, read, NoValue(), read_marks);
        }
    } else if (item.phase == 0 && kind == "member_expression" &&
               ConstantMember(forest, text, types, members, names, item.node) >= 0) {
        // A constant member of a global, such as an input action, is its name.
        field := members[ConstantMember(forest, text, types, members, names, item.node)];
        slots.append(ValueLocal(field.storage));
        constant := ConstantCode(ops, field.storage, 0, at.slot, node);
        constant.text = field.name;
        constant.has_text = true;
        code.append(constant);
        produced = Typed(at.slot, field.storage, 0, field.record);
    } else if (item.phase == 0 && kind == "member_expression" &&
               SelfComponent(forest, text, types, names, item.node) >= 0) {
        return ComponentReadStep([], types, SelfComponent(forest, text, types, names, item.node), false, -1, [],
                                 ops, target, at, node);
    } else if (item.phase == 0) {
        next.append(Visit(Field(forest, item.node, "object")));
        // An index's type is a map's key type or an array's int.
        if (kind == "index_expression") {
            next.append(Resume(item.node, KeyPhase, 0, 0));
        } else {
            next.append(Resume(item.node, 1, 0, 0));
        }
    } else if (item.phase == KeyPhase) {
        // The object is ready, so the index takes a map's key type or an
        // array's int.
        index := Field(forest, item.node, "index");
        if (IsMap(values[top - 1])) {
            next.append(Expect(index, types[values[top - 1].record].key, 0, -1));
        } else {
            next.append(Expect(index, IntStorage, 0, -1));
        }
        next.append(Resume(item.node, 1, 0, 0));
    } else if (kind == "member_expression") {
        popped = 1;
        object := values[top - 1];
        member := Text(forest, text, Field(forest, item.node, "member"));
        if (member == "") {
            return Fail(forest, Field(forest, item.node, "member"), document, "Invalid string or embedded NUL");
        }
        if (Single(object, ResultsStorage)) {
            // One of a native's results, read from its cell.
            called := natives[object.record];
            index := FindResult(ports, called, member);
            if (index == -2) {
                return Fail(forest, item.node, document, format_text("Ambiguous result '{}'", member));
            }
            if (index < 0) {
                return Fail(forest, item.node, document, format_text("Unknown result '{}'", member));
            }
            port := ports[called.first + called.parameters + index];
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, object.slot + index, 0, 0,
                                    node));
            loaded: Slot = {storage: SlotStorage(port.storage, port.container, target),
                            kind: SlotKind(port.storage, port.container)};
            slots.append(loaded);
            read := Instruction(ops.load, loaded.storage, at.slot + 1, at.slot, 0, 0, node);
            read.offset = target.payload_offset;
            code.append(read);
            if (Pointer(port.storage, port.container)) {
                root: Root = {slot: at.slot + 1, storage: port.storage, container: port.container, record: -1};
                roots.append(root);
            }
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1,
                                Typed(at.slot + 1, port.storage, port.container, -1), NoValue(), marks);
        }
        if (Single(object, FunctionResultsStorage)) {
            // One of a function's named results, read from its cell.
            called := callables[object.record];
            index := NamedResult(params, called, member);
            if (index < 0) {
                return Fail(forest, item.node, document, format_text("Unknown result '{}'", member));
            }
            result := params[called.first + called.count + index];
            slots = [address, ValueLocal(result.storage)];
            code = CellRead(result.storage, object.slot + index, ops, target, at.slot, node);
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1,
                                Typed(at.slot + 1, result.storage, 0, -1), NoValue(), marks);
        }
        if (Single(object, HandleStorage) && Component(types, member) >= 0) {
            // A component of another entity, read as the owner's is.
            return ComponentReadStep([], types, Component(types, member), false, object.slot, [], ops, target, at,
                                     node);
        }
        found: int = -1;
        if (Single(object, StructStorage) ||
            (object.container == 0 && object.record >= 0 && types[object.record].kind == NativeDecl)) {
            found = FindField(types, members, object.record, member);
        }
        if (found < 0) {
            return Fail(forest, item.node, document, format_text("Unknown field '{}'", member));
        }
        field := members[found];
        if (field.read >= 0) {
            // A native reads the field, such as an input action's `pressed`.
            return NativeReadStep(object, field, ops, target, at, node);
        }
        if (field.c_string) {
            return NativeTextReadStep(object, field, ops, target, at, node);
        }
        if (field.storage == StructStorage && field.record < 0) {
            return Fail(forest, item.node, document,
                        format_text("field '{}' has a type this compiler cannot read", member));
        }
        if (field.storage == StructStorage) {
            // A native record's record field lies inside it.
            word: Slot = {storage: target.pointer_storage, kind: ValueKind};
            slots.append(word);
            code.append(ConstantCode(ops, target.pointer_storage, uint64(field.offset), at.slot, node));
            slots.append(address);
            code.append(Instruction(ops.add, target.pointer_storage, at.slot + 1, object.slot, at.slot, -1,
                                    node));
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1,
                                Typed(at.slot + 1, StructStorage, 0, field.record), NoValue(), marks);
        }
        slot: Slot = {storage: field.storage, kind: ValueKind};
        slots.append(slot);
        read := Instruction(ops.load, field.storage, at.slot, object.slot, 0, 0, node);
        read.offset = field.offset;
        code.append(read);
        produced = Typed(at.slot, field.storage, 0, -1);
    } else {
        popped = 2;
        array := values[top - 2];
        position := values[top - 1];
        if (IsMap(array)) {
            return MapReadStep(forest, document, types, array, position, ops, target, at, item.node);
        }
        if (array.container != ArrayContainer) {
            return Fail(forest, Field(forest, item.node, "object"), document, "indexing needs an array");
        }
        if (!Single(position, IntStorage)) {
            return Fail(forest, Field(forest, item.node, "index"), document, "index needs an int");
        }
        packable := Packable(array.storage, array.record, types, members);
        slots = ElementSlots(array.storage, packable, target);
        locals = ElementLocals(array.storage, packable, target);
        code = ElementRead(array.slot, position.slot, array.storage, packable, at.slot, at.pc, at.local, ops, target,
                           node);
        element := at.slot + length(slots) - 1;
        if (array.storage == StructStorage) {
            root: Root = {slot: element, storage: StructStorage, container: 0, record: array.record};
            roots.append(root);
        }
        produced = Typed(element, array.storage, 0, array.record);
    }
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, NoValue(), marks);
}

// The phase of an array literal whose element type its first item gives.
InferPhase: int : 2;
// Struct and array literals, built by the construct intrinsic: the value's
// header, then each array item, or each field as an offset cell and a value
// cell; it returns the new value.
LiteralStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                members: TypeMember[], values: Value[], top: int, built: int[], item: Work, ops: Ops, target: Target,
                at: Bases) -> Step {
    node := forest[item.node];
    array := node.kind == "array_expression";
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    if (array && item.container != ArrayContainer) {
        // With no type expected, the first item's type is the element type,
        // as in stage zero, and the other items take it.
        if (item.storage != 0) {
            return Fail(forest, item.node, document, "Array literal needs an explicit array type");
        }
        first := FirstMember(forest, item.node);
        if (item.phase == 0) {
            if (first < 0) {
                return Fail(forest, item.node, document, "Empty arrays need an explicit element type");
            }
            next.append(Visit(first));
            next.append(Resume(item.node, InferPhase, 0, 0));
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(),
                                marks);
        }
        element := values[top - 1];
        if (element.storage == NumberStorage) {
            return Fail(forest, first, document, "an untyped number is a double; give the array an integer type");
        }
        if (element.storage <= 0) {
            return Fail(forest, first, document, "array item has no value type");
        }
        if (element.container != 0) {
            return Fail(forest, first, document, "arrays of arrays are not supported yet");
        }
        count: int = 1;
        member := NextMember(forest, first);
        while (member >= 0) {
            next.append(Expect(member, element.storage, 0, element.record));
            count += 1;
            member = NextMember(forest, member);
        }
        rest := Expect(item.node, element.storage, ArrayContainer, element.record);
        rest.phase = 1;
        rest.a = count;
        next.append(rest);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
    }
    if (!array && (item.storage != StructStorage || item.container != 0)) {
        return Fail(forest, item.node, document, "Struct literal needs an explicit record type");
    }
    record := item.record;
    if (item.phase == 0) {
        count: int = 0;
        member := FirstMember(forest, item.node);
        while (member >= 0) {
            if (array) {
                next.append(Expect(member, item.storage, 0, record));
            } else {
                name := Text(forest, text, Field(forest, member, "name"));
                if (name == "") {
                    return Fail(forest, Field(forest, member, "name"), document, "Invalid string or embedded NUL");
                }
                if (FindField(types, members, record, name) < 0) {
                    return Fail(forest, member, document, format_text("Unknown field '{}'", name));
                }
                earlier := FirstMember(forest, item.node);
                while (earlier != member) {
                    if (Text(forest, text, Field(forest, earlier, "name")) == name) {
                        return Fail(forest, member, document, format_text("Duplicate literal member '{}'", name));
                    }
                    earlier = NextMember(forest, earlier);
                }
                field := members[FindField(types, members, record, name)];
                if (field.c_string) {
                    message := CStringMessage(forest, text, Field(forest, member, "value"), field.name);
                    if (message != "") {
                        return Fail(forest, Field(forest, member, "value"), document, message);
                    }
                }
                next.append(Expect(Field(forest, member, "value"), field.storage, 0, -1));
            }
            count += 1;
            member = NextMember(forest, member);
        }
        if (!array && count != types[record].count) {
            return Fail(forest, item.node, document, "Struct literal needs every field");
        }
        rest := Expect(item.node, item.storage, item.container, record);
        rest.phase = 1;
        rest.a = count;
        next.append(rest);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
    }
    header: Cell = {storage: item.storage, container: item.container, record: record, constant: 0, variant: -1, kind: ValueKind};
    cells.append(header);
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    member := FirstMember(forest, item.node);
    index: int = 0;
    while (member >= 0) {
        value := values[top - item.a + index];
        if (array && !SameType(item.storage, 0, record, value)) {
            return Fail(forest, member, document, "array item differs from the array's type");
        }
        if (!array) {
            found := FindField(types, members, record, Text(forest, text, Field(forest, member, "name")));
            field := members[found];
            if (!SameType(field.storage, 0, -1, value)) {
                return Fail(forest, member, document, "field value differs from its type");
            }
            // Each field's value is watched as the literal's input, numbered
            // by the field's place in the record.
            code.append(WatchCode(ops, value.slot, value.storage, value.container, value.record,
                                  found - types[record].first, false, forest[item.node], target));
            offset: Cell = {storage: WordStorage, container: 0, record: -1, constant: uint64(field.offset), variant: -1,
                            kind: ValueKind};
            cells.append(offset);
        }
        content: Cell = {storage: value.storage, container: 0, record: value.record, constant: 0, variant: -1, kind: ValueKind};
        cells.append(content);
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1,
                                at.cell + length(cells) - 1, 0, 0, forest[member]));
        write := Instruction(ops.write, SlotStorage(value.storage, 0, target), 0, value.slot,
                             at.slot + length(slots) - 1, 0, forest[member]);
        write.offset = target.payload_offset;
        code.append(write);
        index += 1;
        member = NextMember(forest, member);
    }
    cells.append(header);
    // A literal the function returns, or one that starts a local it returns,
    // is built in the caller's storage.
    intrinsic := ConstructIntrinsic;
    if ((array && BuiltLiteral(forest, built, item.node)) || Returned(forest, item.node)) {
        intrinsic += InResult;
    }
    host: Host = {intrinsic: intrinsic, linked: -1, first: at.cell, result_first: at.cell + length(cells) - 1,
                  result_count: 1, written: false};
    hosts.append(host);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    slots.append(address);
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1,
                            at.cell + length(cells) - 1, 0, 0, node));
    slots.append(address);
    made := at.slot + length(slots) - 1;
    load := Instruction(ops.load, target.pointer_storage, made, made - 1, 0, 0, node);
    load.offset = target.payload_offset;
    code.append(load);
    root: Root = {slot: made, storage: item.storage, container: item.container, record: record};
    roots.append(root);
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, item.a,
                        Typed(made, item.storage, item.container, record), NoValue(), marks);
}

// `node` without the parentheses around it.
Unparenthesized :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    at := node;
    while (Is(forest, at, "parenthesized_expression")) {
        at = Field(forest, at, "expression");
    }
    return at;
}
// A provable literal at an explicit foreign C-string boundary.
CStringMessage :: (forest: snapshot.SnapshotNode[], text: string, node: int, boundary: string) -> string {
    at := Unparenthesized(forest, node);
    if (Is(forest, at, "named_argument")) {
        at = Unparenthesized(forest, Field(forest, at, "value"));
    }
    if (!Is(forest, at, "string")) {
        return "";
    }
    decoded := compiler_json_value_string(Text(forest, text, at));
    if (!decoded.valid) {
        return "";
    }
    index: int = 0;
    while (index < strings.ByteLength(decoded.value)) {
        if (strings.ByteAt(decoded.value, index) == 0) {
            return format_text("C-string boundary '{}' cannot accept NUL at byte {}", boundary, index);
        }
        index += 1;
    }
    return "";
}
// Calls of the package's functions and of natives. Arguments go to fresh data
// cells and the result comes back in one. A native's inferred ports all take
// the one type its arguments give them.
CallStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, callables: Callable[],
             params: Param[], types: TypeDecl[], members: TypeMember[], constants: ConstDecl[], natives: Native[], ports: Port[],
             makes: NativeMake[], make_fields: int[], names: Name[], package: int, values: Value[], top: int,
             built: int[], item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    if (item.phase == 0) {
        callee := Field(forest, item.node, "function");
        hidden := PrivateAccess(forest, text, callables, types, constants, names, package, callee);
        if (hidden >= 0) {
            return Fail(forest, hidden, document, PrivateMessage(Text(forest, text, hidden)));
        }
        sum_type: int = -1;
        if (Is(forest, callee, "member_expression")) {
            sum_type = UnionOf(forest, text, types, names, package, callee);
        }
        if (sum_type >= 0) {
            // A variant with a payload: each argument is a payload field, in order.
            member := Text(forest, text, Field(forest, callee, "member"));
            variant := FindVariant(types, sum_type, member);
            if (variant < 0) {
                return Fail(forest, callee, document, format_text("Unknown variant '{}'", member));
            }
            count: int = 0;
            argument := FirstMember(forest, Field(forest, item.node, "arguments"));
            while (argument >= 0) {
                if (Is(forest, argument, "named_argument")) {
                    return Fail(forest, argument, document, "named payload arguments are not supported yet");
                }
                if (count >= types[variant].count) {
                    break;
                }
                field := members[types[variant].first + count];
                next.append(Expect(argument, field.storage, field.container, field.record));
                count += 1;
                argument = NextMember(forest, argument);
            }
            if (argument >= 0 || count != types[variant].count) {
                return Fail(forest, item.node, document, "variant payload needs one value per field");
            }
            finish := Resume(item.node, 1, variant, count);
            finish.c = 2;
            next.append(finish);
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
        }
        // `xs.f(...)` calls the array function f with xs first. A method that
        // changes its array is a statement on the array's name.
        method: int = -1;
        if (Is(forest, callee, "member_expression") &&
            QualifierOf(forest, text, names, package, Field(forest, callee, "object")) < 0) {
            method = ArrayMethod(natives, ports, Text(forest, text, Field(forest, callee, "member")));
        }
        if (method >= 0) {
            if (ArrayChanger(natives, method) &&
                ChangedArray(forest, text, names, natives, ports, forest[item.node].parent) < 0) {
                return Fail(forest, callee, document,
                            format_text("{} changes the array; call it as a statement on a name",
                                        Text(forest, text, Field(forest, callee, "member"))));
            }
            if (!Supported(ports, natives[method])) {
                return Fail(forest, callee, document,
                            format_text("native '{}' is not supported yet", natives[method].name));
            }
            count: int = 0;
            argument := Field(forest, callee, "object");
            while (argument >= 0) {
                expected := Visit(argument);
                if (count < natives[method].parameters && ports[NativePort(natives[method], count)].storage > 0) {
                    port := ports[NativePort(natives[method], count)];
                    expected = Expect(argument, port.storage, port.container, -1);
                }
                next.append(expected);
                if (count == 0) {
                    argument = FirstMember(forest, Field(forest, item.node, "arguments"));
                } else {
                    argument = NextMember(forest, argument);
                }
                count += 1;
            }
            if (count != natives[method].parameters) {
                return Fail(forest, item.node, document, "call has the wrong number of arguments");
            }
            finish := Resume(item.node, 1, method, count);
            finish.c = 1;
            next.append(finish);
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
        }
        // `F(...)` calls this package's F or a native; `alias.F(...)` calls an
        // imported package's F.
        qualifier: int = -1;
        if (Is(forest, callee, "member_expression")) {
            qualifier = Field(forest, callee, "object");
            callee = Field(forest, callee, "member");
        }
        home := QualifierOf(forest, text, names, package, qualifier);
        if (home < 0 || !Is(forest, callee, "identifier")) {
            return Fail(forest, Field(forest, item.node, "function"), document, "call needs a function name");
        }
        callee_name := Text(forest, text, callee);
        found := FindCallable(callables, home, callee_name);
        conversion: int = 0;
        if (qualifier < 0 && found < 0) {
            conversion = ScalarStorage(callee_name);
        }
        if (Integer(conversion)) {
            // `T(value)` fails when the value does not fit; `T(wrap: value)`
            // keeps its low bits and `T(clamp: value)` saturates.
            argument := FirstMember(forest, Field(forest, item.node, "arguments"));
            if (argument < 0 || NextMember(forest, argument) >= 0) {
                return Fail(forest, item.node, document, "Conversion takes one value");
            }
            mode: int = 0;
            value := argument;
            if (Is(forest, argument, "named_argument")) {
                label := Text(forest, text, Field(forest, argument, "name"));
                mode = 1;
                if (label == "clamp") {
                    mode = 2;
                }
                if (label != "wrap" && label != "clamp") {
                    return Fail(forest, argument, document, "A conversion argument may only be named wrap or clamp");
                }
                value = Field(forest, argument, "value");
            }
            if (mode == 0) {
                next.append(Expect(value, conversion, 0, -1));
            } else {
                next.append(Visit(value));
            }
            finish := Resume(item.node, 1, conversion, mode);
            finish.c = 3;
            next.append(finish);
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
        }
        // `assert(condition, "message")` is a language intrinsic. It emits a
        // checked instruction, so a pure host needs no native capability for it.
        if (qualifier < 0 && found < 0 && NameMatches("assert", callee_name)) {
            condition: int = -1;
            message: int = -1;
            index: int = 0;
            argument := FirstMember(forest, Field(forest, item.node, "arguments"));
            while (argument >= 0) {
                value := argument;
                position := index;
                if (Is(forest, argument, "named_argument")) {
                    label := Text(forest, text, Field(forest, argument, "name"));
                    value = Field(forest, argument, "value");
                    position = -1;
                    if (NameMatches("Condition", label)) {
                        position = 0;
                    } else if (NameMatches("Message", label)) {
                        position = 1;
                    }
                }
                if (position < 0) {
                    return Fail(forest, argument, document,
                                format_text("Unknown argument '{}'", Text(forest, text, Field(forest, argument, "name"))));
                }
                if (position > 1) {
                    return Fail(forest, argument, document, "Too many arguments");
                }
                if ((position == 0 && condition >= 0) || (position == 1 && message >= 0)) {
                    return Fail(forest, argument, document, "Argument supplied more than once");
                }
                if (position == 0) {
                    condition = value;
                } else {
                    message = value;
                }
                index += 1;
                argument = NextMember(forest, argument);
            }
            // Stage zero gives a missing condition false; stage one asks
            // for one.
            if (condition < 0) {
                return Fail(forest, item.node, document, "assert needs a condition");
            }
            if (message >= 0 && !Is(forest, Unparenthesized(forest, message), "string")) {
                return Fail(forest, message, document, "assert's message is a string constant");
            }
            next.append(Expect(condition, BoolStorage, 0, -1));
            finish := Resume(item.node, 1, message, condition);
            finish.c = 6;
            next.append(finish);
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
        }
        native: int = -1;
        expected_count: int = 0;
        if (found >= 0) {
            expected_count = callables[found].count;
        } else if (qualifier >= 0) {
            return Fail(forest, callee, document, format_text("Unknown function '{}'", callee_name));
        } else {
            native = FindNative(natives, callee_name);
            if (native == -2) {
                return Fail(forest, callee, document, format_text("Ambiguous function '{}'", callee_name));
            }
            if (native < 0) {
                return Fail(forest, callee, document, format_text("Unknown function '{}'", callee_name));
            }
            if (Overloaded(natives, callee_name)) {
                // Each argument's own type picks the overload.
                argument := FirstMember(forest, Field(forest, item.node, "arguments"));
                count: int = 0;
                while (argument >= 0) {
                    next.append(Visit(argument));
                    count += 1;
                    argument = NextMember(forest, argument);
                }
                choose := Resume(item.node, 1, -1, count);
                choose.c = 4;
                next.append(choose);
                return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(),
                                    NoValue(), marks);
            }
            make := FindMake(makes, native);
            if (make < 0 && !Supported(ports, natives[native])) {
                return Fail(forest, callee, document, format_text("native '{}' is not supported yet", callee_name));
            }
            expected_count = natives[native].parameters;
        }
        count: int = 0;
        argument := FirstMember(forest, Field(forest, item.node, "arguments"));
        while (argument >= 0) {
            expected := Visit(argument);
            if (found >= 0 && count < expected_count) {
                param := params[callables[found].first + count];
                expected = Expect(argument, param.storage, param.container, param.record);
                if (param.reference) {
                    expected.phase = ReferencePhase;
                }
            } else if (native >= 0 && (count < expected_count || natives[native].variadic) &&
                       ports[NativePort(natives[native], count)].storage > 0) {
                port := ports[NativePort(natives[native], count)];
                expected = Expect(argument, port.storage, port.container, -1);
            }
            next.append(expected);
            count += 1;
            argument = NextMember(forest, argument);
        }
        // A variadic native's last parameter takes any number of arguments,
        // and an omitted argument of a function takes its default.
        arity := count == expected_count;
        if (native >= 0 && natives[native].variadic) {
            arity = count >= expected_count - 1;
        }
        if (found >= 0 && count < expected_count) {
            // Every omitted argument needs a default.
            arity = true;
            at_omitted := count;
            while (at_omitted < expected_count) {
                arity = arity && params[callables[found].first + at_omitted].has_default;
                at_omitted += 1;
            }
        }
        if (!arity) {
            return Fail(forest, item.node, document, "call has the wrong number of arguments");
        }
        finish := Resume(item.node, 1, found, count);
        if (native >= 0) {
            finish.a = native;
            finish.c = 1;
        }
        if (native >= 0 && FindMake(makes, native) >= 0) {
            finish.a = FindMake(makes, native);
            finish.c = 5;
        }
        next.append(finish);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
    }
    if (item.c == 6) {
        // An assert fails with its message, or with its condition's source
        // when it gives none.
        said := Text(forest, text, Unparenthesized(forest, item.b));
        if (item.a >= 0) {
            decoded := compiler_json_value_string(Text(forest, text, Unparenthesized(forest, item.a)));
            if (!decoded.valid) {
                return Fail(forest, item.a, document, "Invalid string literal");
            }
            if (decoded.value != "") {
                said = strings.ReplaceAll(decoded.value, "\u0000", "\\0");
            }
        }
        check := Instruction(ops.guard, 0, 0, values[top - 1].slot, 0, target.assert_failure, node);
        check.message = format_text("Assertion failed: {}", said);
        check.has_message = true;
        code.append(check);
        // Like a call of a function with no result, it leaves no value.
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, Typed(-1, -1, 0, -1),
                            NoValue(), marks);
    }
    if (item.c == 3) {
        // A conversion to types item.a in mode item.b. A wrapped or clamped
        // literal is int64; a bare number beyond int64 is uint64.
        value := values[top - 1];
        if (value.storage == NumberStorage) {
            storage := Int64Storage;
            written := Field(forest, FirstMember(forest, Field(forest, item.node, "arguments")), "value");
            if (Is(forest, written, "number")) {
                switch ParseNumber(forest, text, value.record) {
                    case .Invalid:
                        storage = Int64Storage;
                    case .Number(negative, magnitude):
                        if (!Fits(negative, magnitude, storage)) {
                            storage = WordStorage;
                        }
                }
            }
            typed := ConstantStep(forest, text, document, value, storage, ops, at, node);
            switch typed {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(typed_code, typed_slots, typed_locals, typed_cells, typed_hosts, typed_roots, typed_calls,
                              typed_bound, typed_next, typed_popped, typed_value, typed_retain, typed_marks):
                    code = typed_code;
                    slots = typed_slots;
                    value = typed_value;
            }
        }
        if (value.container != 0 || (!Integer(value.storage) && !Floating(value.storage))) {
            return Fail(forest, item.node, document, "conversion needs a number");
        }
        if (value.storage == item.a) {
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, value, NoValue(), marks);
        }
        converted: Slot = {storage: item.a, kind: ValueKind};
        slots.append(converted);
        code.append(CastCode(ops, item.a, at.slot + length(slots) - 1, value.slot, item.b, node));
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1,
                            Typed(at.slot + length(slots) - 1, item.a, 0, -1), NoValue(), marks);
    }
    count := item.b;
    first := top - count;
    at_argument := first;
    while (at_argument < top) {
        if (values[at_argument].storage == NumberStorage) {
            return Fail(forest, values[at_argument].record, document, "a number needs an integer type here");
        }
        at_argument += 1;
    }
    // Stage zero evaluates the default of each argument a call omits.
    if (item.c == 0 && item.a >= 0) {
        omitted := count;
        while (omitted < callables[item.a].count) {
            param := params[callables[item.a].first + omitted];
            if (callables[item.a].package == package) {
                code.append(OccurrenceCode(ops, ExpressionRecord, param.default_occurrence,
                                           forest[Field(forest, forest[param.node].parent, "value")]));
            } else {
                code.append(ExpressionCode(ops, forest[Field(forest, item.node, "arguments")]));
            }
            omitted += 1;
        }
    }
    if (item.c == 2) {
        // The constructor takes the variant's tag, then each payload field. A
        // returned variant is built in the caller's storage, so the return
        // need not copy it, with a mask of the payload values it keeps there:
        // the locals the function builds there. It copies the others.
        variant := types[item.a];
        returned := Returned(forest, item.node);
        keep: int64 = 0;
        argument_node := FirstMember(forest, Field(forest, item.node, "arguments"));
        position: int = 0;
        while (returned && count <= 64 && argument_node >= 0) {
            if (BuiltName(forest, text, names, built, argument_node)) {
                keep = keep | (int64(1) << int64(position));
            }
            position += 1;
            argument_node = NextMember(forest, argument_node);
        }
        tag: Cell = {storage: WordStorage, container: 0, record: -1, constant: 0, variant: item.a, kind: ValueKind};
        cells.append(tag);
        kept := returned && count <= 64;
        shift: int = 0;
        if (kept) {
            mask: Cell = {storage: WordStorage, container: 0, record: -1, constant: uint64(wrap: keep), variant: -1,
                          kind: ValueKind};
            cells.append(mask);
            shift = 1;
        }
        address: Slot = {storage: target.pointer_storage, kind: AddressKind};
        index: int = 0;
        while (index < count) {
            argument := values[first + index];
            field := members[variant.first + index];
            if (!SameType(field.storage, field.container, field.record, argument)) {
                return Fail(forest, item.node, document, "payload value differs from its field type");
            }
            cell: Cell = {storage: argument.storage, container: argument.container, record: argument.record,
                          constant: 0, variant: -1, kind: ValueKind};
            cells.append(cell);
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + index,
                                    at.cell + 1 + shift + index, 0, 0, node));
            write := Instruction(ops.write, SlotStorage(argument.storage, argument.container, target), 0, argument.slot,
                                 at.slot + index, 0, node);
            write.offset = target.payload_offset;
            code.append(write);
            index += 1;
        }
        made: Cell = {storage: UnionStorage, container: 0, record: variant.parent, constant: 0, variant: -1,
                      kind: ValueKind};
        cells.append(made);
        intrinsic := UnionMakeIntrinsic;
        if (kept) {
            intrinsic = UnionKeepIntrinsic + InResult;
        }
        host: Host = {intrinsic: intrinsic, linked: -1, first: at.cell, result_first: at.cell + 1 + shift + count,
                      result_count: 1, written: false};
        hosts.append(host);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + count, at.cell + 1 + shift + count,
                                0, 0, node));
        value: Slot = {storage: UnionStorage, kind: ValueKind};
        slots.append(value);
        load := Instruction(ops.load, UnionStorage, at.slot + count + 1, at.slot + count, 0, 0, node);
        load.offset = target.payload_offset;
        code.append(load);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, count,
                            Typed(at.slot + count + 1, UnionStorage, 0, variant.parent), NoValue(), marks);
    }
    chosen := item.a;
    if (item.c == 4) {
        // An overloaded native: the one whose parameters take the arguments.
        callee := Field(forest, item.node, "function");
        chosen = Overload(natives, ports, Text(forest, text, callee), values, first, count);
        if (chosen < 0) {
            return Fail(forest, callee, document, "no overload of this native takes these arguments, or several do");
        }
        if (!Supported(ports, natives[chosen])) {
            return Fail(forest, callee, document, "this overload is not supported yet");
        }
    }
    if (item.c == 5) {
        return MakeStep(forest, document, types, members, makes[item.a], make_fields, values, first, count, item.node,
                        ops, target, at, node);
    }
    linked := item.c == 1 || item.c == 4;
    inferred := NoValue();
    first_port: int = 0;
    if (linked) {
        first_port = natives[chosen].first;
    }
    // The given arguments, then the defaults of those the call omits.
    arguments: Value[] = slice(values, first, count);
    if (!linked) {
        called := callables[item.a];
        while (length(arguments) < called.count) {
            param := params[called.first + length(arguments)];
            slots.append(ValueLocal(param.storage));
            constant := ConstantCode(ops, param.storage, param.default_bits, at.slot + length(slots) - 1, node);
            constant.text = param.default_text;
            constant.has_text = param.storage == TextStorage;
            code.append(constant);
            if (called.package == package) {
                code.append(DefaultWatch(ops, at.slot + length(slots) - 1, param.storage,
                                         param.default_occurrence,
                                         forest[Field(forest, forest[param.node].parent, "value")]));
            } else {
                code.append(DefaultWatch(ops, at.slot + length(slots) - 1, param.storage, uint64(0),
                                         forest[Field(forest, item.node, "arguments")]));
            }
            arguments.append(Typed(at.slot + length(slots) - 1, param.storage, 0, -1));
        }
    }
    total := length(arguments);
    // Slots for the call follow the defaults'.
    b := at.slot + length(slots);
    index: int = 0;
    while (index < total) {
        argument := arguments[index];
        expected := NoValue();
        if (linked) {
            port := ports[NativePort(natives[chosen], index)];
            if (port.c_string) {
                argument_node := FirstMember(forest, Field(forest, item.node, "arguments"));
                ordinal: int = 0;
                while (ordinal < index && argument_node >= 0) {
                    argument_node = NextMember(forest, argument_node);
                    ordinal += 1;
                }
                message := CStringMessage(forest, text, argument_node, port.name);
                if (message != "") {
                    return Fail(forest, argument_node, document, message);
                }
            }
            expected = Typed(-1, port.storage, port.container, -1);
            if (port.storage == AnyPort && argument.storage > 0) {
                expected = argument;
            } else if (port.storage == 0) {
                element := Typed(-1, argument.storage, 0, argument.record);
                if (argument.storage <= 0 || argument.container != port.container ||
                    (inferred.storage != 0 && !SameType(inferred.storage, 0, inferred.record, element))) {
                    return Fail(forest, item.node, document, "argument differs from its parameter type");
                }
                inferred = element;
                expected = Typed(-1, element.storage, port.container, element.record);
            }
        } else {
            param := params[callables[item.a].first + index];
            expected = Typed(-1, param.storage, param.container, param.record);
            if (param.reference) {
                expected = Typed(-1, ReferenceStorage, 0, -1);
            }
        }
        if (!SameType(expected.storage, expected.container, expected.record, argument)) {
            return Fail(forest, item.node, document, "argument differs from its parameter type");
        }
        cell: Cell = {storage: argument.storage, container: argument.container, record: argument.record, constant: 0, variant: -1,
                      kind: ValueKind};
        if (argument.storage == ReferenceStorage) {
            cell = ReferenceCell(target);
        }
        cells.append(cell);
        index += 1;
    }
    result := Typed(-1, -1, 0, -1);
    result_count: int = 0;
    if (linked && natives[chosen].results > 1) {
        // Several results land in cells a local or `.name` reads.
        called := natives[chosen];
        at_result: int = 0;
        while (at_result < called.results) {
            port := ports[called.first + called.parameters + at_result];
            if (port.storage <= 0) {
                return Fail(forest, item.node, document, "native result type is not known");
            }
            cell: Cell = {storage: port.storage, container: port.container, record: -1, constant: 0, variant: -1,
                          kind: ValueKind};
            cells.append(cell);
            at_result += 1;
        }
        result_count = called.results;
        result = Typed(at.cell + total, ResultsStorage, 0, chosen);
    } else if (linked && natives[chosen].results == 1) {
        port := ports[first_port + natives[chosen].parameters];
        result = Typed(-1, port.storage, port.container, -1);
        if (port.storage == 0) {
            if (inferred.storage == 0) {
                return Fail(forest, item.node, document, "native result type is not known");
            }
            result = Typed(-1, inferred.storage, port.container, inferred.record);
        }
        result_count = 1;
    } else if (!linked && callables[item.a].results > 0) {
        // Named results land in cells a local or `.name` reads.
        called := callables[item.a];
        at_result: int = 0;
        while (at_result < called.results) {
            named := params[called.first + called.count + at_result];
            cell: Cell = {storage: named.storage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
            cells.append(cell);
            at_result += 1;
        }
        result_count = called.results;
        result = Typed(at.cell + total, FunctionResultsStorage, 0, item.a);
    } else if (!linked && callables[item.a].result != 0) {
        called := callables[item.a];
        result = Typed(-1, called.result, called.result_container, called.result_record);
        result_count = 1;
    }
    if (result.storage > 0) {
        cell: Cell = {storage: result.storage, container: result.container, record: result.record, constant: 0, variant: -1,
                      kind: ValueKind};
        cells.append(cell);
    }
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    index = 0;
    while (index < total) {
        argument := arguments[index];
        // Each argument is watched as the call's input; a ref argument as the
        // value it reaches.
        written := SlotStorage(argument.storage, argument.container, target);
        if (argument.storage == ReferenceStorage) {
            written = target.pointer_storage;
            code.append(ReferenceWatch(ops, params[callables[item.a].first + index], index, argument.slot,
                                       node, target));
        } else {
            code.append(WatchCode(ops, argument.slot, argument.storage, argument.container, argument.record,
                                  index, false, node, target));
        }
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, b + index, at.cell + index, 0, 0, node));
        write := Instruction(ops.write, written, 0, argument.slot, b + index, 0, node);
        write.offset = target.payload_offset;
        code.append(write);
        index += 1;
    }
    if (linked) {
        host: Host = {intrinsic: 0, linked: chosen, first: at.cell, result_first: at.cell + total,
                      result_count: result_count, written: false};
        hosts.append(host);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    } else {
        invocation: Invocation = {callee: item.a, first: at.cell, count: total, result_first: at.cell + total,
                                  result_count: result_count};
        calls.append(invocation);
        // Each invocation suspends the caller once; EmitBody numbers it.
        code.append(Instruction(ops.invoke, 0, 0, at.call, 0, 0, node));
    }
    if (result.storage > 0) {
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, b + total, at.cell + total, 0, 0, node));
        loaded: Slot = {storage: SlotStorage(result.storage, result.container, target),
                        kind: SlotKind(result.storage, result.container)};
        slots.append(loaded);
        read := Instruction(ops.load, loaded.storage, b + total + 1, b + total, 0, 0, node);
        read.offset = target.payload_offset;
        code.append(read);
        if (Pointer(result.storage, result.container)) {
            root: Root = {slot: b + total + 1, storage: result.storage, container: result.container,
                          record: result.record};
            roots.append(root);
        }
        result.slot = b + total + 1;
    }
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, count, result, NoValue(), marks);
}

// Unary operators and the binary operators other than logic.
OperatorStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, values: Value[], top: int,
                 item: Work, ops: Ops, at: Bases) -> Step {
    node := forest[item.node];
    unary := node.kind == "unary_expression";
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    if (item.phase == 0) {
        if (unary) {
            next.append(Visit(Field(forest, item.node, "operand")));
        } else {
            next.append(Visit(Field(forest, item.node, "left")));
            next.append(Visit(Field(forest, item.node, "right")));
        }
        // The expected type stays with the node, for untyped literals.
        finish := Expect(item.node, item.storage, item.container, item.record);
        finish.phase = 1;
        next.append(finish);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
    }
    operator := Text(forest, text, Field(forest, item.node, "operator"));
    if (node.kind == "assignment") {
        operator = CompoundOperator(operator);
    }
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    if (unary) {
        operand := values[top - 1];
        if (operand.storage == NumberStorage && (operator == "-" || operator == "+")) {
            // A signed literal is a literal too: typed here when its use is,
            // else by its use.
            literal := Typed(-1, NumberStorage, 0, item.node);
            if (operator == "+") {
                literal = operand;
            }
            if (Integer(item.storage) || Floating(item.storage)) {
                typed := ConstantStep(forest, text, document, literal, item.storage, ops, at, node);
                if (Floating(item.storage)) {
                    typed = FloatConstantStep(forest, text, document, literal, item.storage, ops, at, node);
                }
                switch typed {
                    case .Failed(diagnostic):
                        return Step.Failed(diagnostic);
                    case .Emitted(typed_code, typed_slots, typed_locals, typed_cells, typed_hosts, typed_roots,
                                  typed_calls, typed_bound, typed_next, typed_popped, typed_value, typed_retain,
                                  typed_marks):
                        literal = typed_value;
                        code = typed_code;
                        slots = typed_slots;
                }
            }
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, literal, NoValue(),
                                marks);
        }
        if (operand.storage == NumberStorage && Integer(item.storage)) {
            typed := ConstantStep(forest, text, document, operand, item.storage, ops, at, node);
            switch typed {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(typed_code, typed_slots, typed_locals, typed_cells, typed_hosts, typed_roots, typed_calls,
                              typed_bound, typed_next, typed_popped, typed_value, typed_retain, typed_marks):
                    code = typed_code;
                    slots = typed_slots;
                    operand = typed_value;
            }
        }
        integer := Integer(operand.storage) && operand.container == 0;
        op: int = -1;
        right_slot: int = 0;
        if (operator == "-" && integer && Computes(ops, ops.neg, operand.storage)) {
            op = ops.neg;
        } else if (operator == "~" && integer) {
            op = ops.bit_not;
        } else if ((operator == "!" || operator == "not") && Single(operand, BoolStorage)) {
            // Not is equality with false.
            slots.append(flag);
            code.append(ConstantCode(ops, BoolStorage, 0, at.slot + length(slots) - 1, node));
            right_slot = at.slot + length(slots) - 1;
            op = ops.eq;
        } else if (operator == "+" && integer) {
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, operand, NoValue(),
                                marks);
        } else if (operator == "-" && integer) {
            return Fail(forest, item.node, document, "unsupported arithmetic type");
        } else {
            return Fail(forest, item.node, document, "operator does not apply to this operand");
        }
        result: Slot = {storage: operand.storage, kind: ValueKind};
        slots.append(result);
        output := at.slot + length(slots) - 1;
        operation := Instruction(op, operand.storage, output, operand.slot, right_slot, -1, node);
        if (op != ops.eq) {
            operation.right = 0;
            operation.target = 0;
        }
        code.append(operation);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1,
                            Typed(output, operand.storage, 0, -1), NoValue(), marks);
    }
    op := BinaryOp(ops, operator);
    left := values[top - 2];
    right := values[top - 1];
    if (Single(left, StructStorage) || Single(right, StructStorage)) {
        // Records combine through a native, field by field.
        next.append(Resume(item.node, AggregatePhase, 0, 0));
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(),
                            marks);
    }
    // Untyped literals take the other operand's type, or the expected one
    // when both are untyped; differing integers widen to their common type.
    wanted := item.storage;
    if (left.storage != NumberStorage) {
        wanted = left.storage;
    }
    if (right.storage != NumberStorage && left.storage == NumberStorage) {
        wanted = right.storage;
    }
    operands: Value[] = [left, right];
    side: int = 0;
    while (side < 2) {
        if (operands[side].storage == NumberStorage) {
            if (!Integer(wanted) && !Floating(wanted)) {
                return Fail(forest, operands[side].record, document, "a number needs an integer type here");
            }
            shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots), local: at.local, cell: at.cell,
                              host: at.host, call: at.call};
            typed := ConstantStep(forest, text, document, operands[side], wanted, ops, shifted, node);
            if (Floating(wanted)) {
                typed = FloatConstantStep(forest, text, document, operands[side], wanted, ops, shifted, node);
            }
            switch typed {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(typed_code, typed_slots, typed_locals, typed_cells, typed_hosts, typed_roots, typed_calls,
                              typed_bound, typed_next, typed_popped, typed_value, typed_retain, typed_marks):
                    code.extend(typed_code);
                    slots.extend(typed_slots);
                    operands[side] = typed_value;
            }
        }
        side += 1;
    }
    left = operands[0];
    right = operands[1];
    if (Single(left, left.storage) && Single(right, right.storage) && Integer(left.storage) &&
        Integer(right.storage) && left.storage != right.storage) {
        common := CommonInteger(left.storage, right.storage);
        if (common < 0) {
            return Fail(forest, item.node, document, format_text("{} and {} operands need an explicit conversion, such as {}(value)",
                                                                 TypeName(left.storage), TypeName(right.storage), TypeName(left.storage)));
        }
        widened: Slot = {storage: common, kind: ValueKind};
        if (left.storage != common) {
            slots.append(widened);
            code.append(CastCode(ops, common, at.slot + length(slots) - 1, left.slot, 0, node));
            left = Typed(at.slot + length(slots) - 1, common, 0, -1);
        }
        if (right.storage != common) {
            slots.append(widened);
            code.append(CastCode(ops, common, at.slot + length(slots) - 1, right.slot, 0, node));
            right = Typed(at.slot + length(slots) - 1, common, 0, -1);
        }
    }
    // An integer with a floating value becomes one, as stage zero converts it.
    if (Single(left, left.storage) && Single(right, right.storage) && Integer(left.storage) &&
        Floating(right.storage)) {
        code.extend(NumberCode(ops, left.storage, right.storage, left.slot, at.slot + length(slots), node));
        slots.extend(NumberSlots(left.storage, right.storage));
        left = Typed(at.slot + length(slots) - 1, right.storage, 0, -1);
    }
    if (Single(left, left.storage) && Single(right, right.storage) && Floating(left.storage) &&
        Integer(right.storage)) {
        code.extend(NumberCode(ops, right.storage, left.storage, right.slot, at.slot + length(slots), node));
        slots.extend(NumberSlots(right.storage, left.storage));
        right = Typed(at.slot + length(slots) - 1, left.storage, 0, -1);
    }
    // A float with a double becomes a double.
    if (Single(left, FloatStorage) && Single(right, DoubleStorage)) {
        slots.append(ValueLocal(DoubleStorage));
        code.append(Instruction(ops.convert, DoubleStorage, at.slot + length(slots) - 1, left.slot, 0, 0, node));
        left = Typed(at.slot + length(slots) - 1, DoubleStorage, 0, -1);
    }
    if (Single(left, DoubleStorage) && Single(right, FloatStorage)) {
        slots.append(ValueLocal(DoubleStorage));
        code.append(Instruction(ops.convert, DoubleStorage, at.slot + length(slots) - 1, right.slot, 0, 0, node));
        right = Typed(at.slot + length(slots) - 1, DoubleStorage, 0, -1);
    }
    numeric := Single(left, left.storage) && Single(right, left.storage) && Numeric(left.storage);
    equality := op == ops.eq || op == ops.ne;
    same := Single(right, left.storage) && (Single(left, BoolStorage) || Single(left, TextStorage));
    if (op < 0 || (!numeric && !(equality && same))) {
        return Fail(forest, item.node, document, "operator does not apply to these operands");
    }
    if (numeric && !Computes(ops, op, left.storage)) {
        return Fail(forest, item.node, document, "unsupported arithmetic type");
    }
    storage := left.storage;
    operand_storage := left.storage;
    left_slot := left.slot;
    right_slot := right.slot;
    if (Comparison(ops, op)) {
        storage = BoolStorage;
    }
    if (equality && left.storage == TextStorage) {
        // Strings compare by content; inequality negates it.
        slots.append(flag);
        code.append(Instruction(ops.string_equal, BoolStorage, at.slot + length(slots) - 1, left_slot,
                                right_slot, 0, node));
        left_slot = at.slot + length(slots) - 1;
        operand_storage = BoolStorage;
        if (op == ops.eq) {
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 2,
                                Typed(left_slot, BoolStorage, 0, -1), NoValue(), marks);
        }
        slots.append(flag);
        code.append(ConstantCode(ops, BoolStorage, 0, at.slot + length(slots) - 1, node));
        right_slot = at.slot + length(slots) - 1;
        op = ops.eq;
    }
    slot: Slot = {storage: storage, kind: ValueKind};
    slots.append(slot);
    output := at.slot + length(slots) - 1;
    code.append(Instruction(op, operand_storage, output, left_slot, right_slot, -1, node));
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 2,
                        Typed(output, storage, 0, -1), NoValue(), marks);
}

// The untyped literal `literal` as a constant of the integer type `storage`.
ConstantStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, literal: Value, storage: int,
                 ops: Ops, at: Bases, node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    bits: uint64 = 0;
    switch ParseNumber(forest, text, literal.record) {
        case .Invalid:
            return Fail(forest, literal.record, document, "only integer literals of 64 bits are supported");
        case .Number(negative, magnitude):
            if (!Fits(negative, magnitude, storage)) {
                return Fail(forest, literal.record, document,
                            format_text("Numeric literal is outside the range of {}", TypeName(storage)));
            }
            bits = Bits(negative, magnitude);
    }
    slot: Slot = {storage: storage, kind: ValueKind};
    slots.append(slot);
    // The literal is watched once its use gives it a type.
    code = extend([ConstantCode(ops, storage, bits, at.slot, node)],
                  LiteralWatch(forest, ops, at.slot, storage, literal.record));
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, Typed(at.slot, storage, 0, -1),
                        NoValue(), marks);
}

// The head of a for loop over the copy in the last cell: an index local
// set to zero, or to the last index when `reverse`, then at `head` the bound
// check, the exit jump and the element load, which takes a second local for a
// packable record. Marks report the head, the exit jump and the index local.
ForStep :: (array: Value, packable: bool, reverse: bool, ops: Ops, target: Target, at: Bases,
            node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    number: Slot = {storage: IntStorage, kind: ValueKind};
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    if (reverse) {
        // The copy's count is fixed, so the last index is read once.
        slots.append(address);
        slots.append(address);
        slots.append(number);
        slots.append(number);
        slots.append(number);
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, at.cell - 1, 0, 0, node));
        start_load := Instruction(ops.load, target.pointer_storage, at.slot + 1, at.slot, 0, 0, node);
        start_load.offset = target.payload_offset;
        code.append(start_load);
        start_root: Root = {slot: at.slot + 1, storage: array.storage, container: ArrayContainer, record: array.record};
        roots.append(start_root);
        code.append(Instruction(ops.guard, 0, 0, at.slot + 1, 0, target.argument_failure, node));
        start_count := Instruction(ops.load, IntStorage, at.slot + 2, at.slot + 1, 0, 0, node);
        start_count.offset = target.count_offset;
        code.append(start_count);
        code.append(ConstantCode(ops, IntStorage, 1, at.slot + 3, node));
        code.append(Instruction(ops.sub, IntStorage, at.slot + 4, at.slot + 2, at.slot + 3, -1, node));
    } else {
        slots.append(number);
        constant := Instruction(ops.constant, IntStorage, at.slot, 0, 0, 0, node);
        constant.value_storage = IntStorage;
        code.append(constant);
    }
    locals.append(ValueLocal(IntStorage));
    code.append(Instruction(ops.save, IntStorage, 0, at.slot + length(slots) - 1, 0, at.local, node));
    // The head's slots follow the start's.
    b := at.slot + length(slots);
    head := at.pc + length(code);
    code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
    slots.append(address);
    code.append(Instruction(ops.host_slot, target.pointer_storage, b, at.cell - 1, 0, 0, node));
    slots.append(address);
    load := Instruction(ops.load, target.pointer_storage, b + 1, b, 0, 0, node);
    load.offset = target.payload_offset;
    code.append(load);
    root: Root = {slot: b + 1, storage: array.storage, container: ArrayContainer, record: array.record};
    roots.append(root);
    code.append(Instruction(ops.guard, 0, 0, b + 1, 0, target.argument_failure, node));
    slots.append(number);
    count := Instruction(ops.load, IntStorage, b + 2, b + 1, 0, 0, node);
    count.offset = target.count_offset;
    code.append(count);
    slots.append(number);
    code.append(Instruction(ops.local, IntStorage, b + 3, at.local, 0, 0, node));
    if (reverse) {
        slots.append(number);
        code.append(ConstantCode(ops, IntStorage, 0, b + 4, node));
        slots.append(flag);
        code.append(Instruction(ops.ge, IntStorage, b + 5, b + 3, b + 4, -1, node));
    } else {
        slots.append(flag);
        code.append(Instruction(ops.lt, IntStorage, b + 4, b + 3, b + 2, -1, node));
    }
    code.append(Instruction(ops.branch_if, 0, 0, at.slot + length(slots) - 1, 0, at.pc + length(code) + 2,
                            node));
    leave := at.pc + length(code);
    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
    // The index is between zero and the count, so the element needs no check.
    first_load := at.slot + length(slots);
    slots.extend(LoadSlots(array.storage, packable, target));
    code.extend(ElementLoad(b + 1, b + 3, array.storage, packable, first_load,
                            at.pc + length(code), at.local + 1, ops, target, node));
    locals.extend(ElementLocals(array.storage, packable, target));
    element := at.slot + length(slots) - 1;
    if (array.storage == StructStorage) {
        element_root: Root = {slot: element, storage: StructStorage, container: 0, record: array.record};
        roots.append(element_root);
    }
    marks: int[] = [head, leave, at.local];
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                        Typed(element, array.storage, 0, array.record), NoValue(), marks);
}

// `x.f = v` and `x.f op= v` on the local record `binding`, as stage zero
// writes a field: a narrower integer `v` converted first, a reference to the
// local's cell and then to the field, and a write through it, which copies
// the record with the new field, so no other value shares the old storage,
// and copies a string into it.
FieldStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, binding: Name, field: TypeMember,
              value: Value, item: Work, ops: Ops, target: Target, at: Bases,
              node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    stored := value;
    if (value.container == 0 && value.storage != field.storage && Converts(value.storage, field.storage)) {
        slots.extend(NumberSlots(value.storage, field.storage));
        code.extend(NumberCode(ops, value.storage, field.storage, value.slot, at.slot, node));
        stored = Typed(at.slot + length(slots) - 1, field.storage, 0, -1);
    }
    if (binding.place == ReferencePlace) {
        return ReferenceFieldStep(forest, text, document, binding, field, stored, code, slots, item, ops, target, at,
                                  node);
    }
    if (item.c == 1) {
        // The current field, read in place, combined with the value.
        op := BinaryOp(ops, CompoundOperator(Text(forest, text, Field(forest, item.node, "operator"))));
        if (op < 0 || Comparison(ops, op) || !(Integer(field.storage) || Floating(field.storage)) ||
            !Single(stored, field.storage)) {
            return Fail(forest, item.node, document, "compound assignment needs number operands of its type");
        }
        if (!Computes(ops, op, field.storage)) {
            return Fail(forest, item.node, document, "unsupported arithmetic type");
        }
        base := at.slot + length(slots);
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, base, binding.index, 0, 0, node));
        slots.append(address);
        record := Instruction(ops.load, target.pointer_storage, base + 1, base, 0, 0, node);
        record.offset = target.payload_offset;
        code.append(record);
        current: Slot = {storage: field.storage, kind: ValueKind};
        slots.append(current);
        read := Instruction(ops.load, field.storage, base + 2, base + 1, 0, 0, node);
        read.offset = field.offset;
        code.append(read);
        slots.append(current);
        code.append(Instruction(op, field.storage, base + 3, base + 2, stored.slot, -1, node));
        code.append(ScalarWatch(ops, base + 3, field.storage, 0, true,
                                forest[Field(forest, item.node, "target")]));
        stored = Typed(base + 3, field.storage, 0, -1);
    }
    if (!SameType(field.storage, 0, -1, stored)) {
        return Fail(forest, item.node, document, "field value differs from its type");
    }
    // Reference make: the context, the record's type, a value reference to
    // the local's cell, then unused component facts.
    first := at.cell;
    constants: uint64[] = [0, 0, 0, 0xFFFFFFFFFFFFFFFF, 0, 0, 0, 0, 0];
    cells.extend(ReferenceCells(target, binding.record, constants, field));
    // The context and the local's cell address go into the make's cells.
    slots.append(address);
    holder := at.slot + length(slots) - 1;
    context := Instruction(ops.context, target.pointer_storage, holder, 0, 0, 1, node);
    code.append(context);
    slots.append(address);
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1, binding.index,
                            0, 0, node));
    local := at.slot + length(slots) - 1;
    code.extend(CellWrite(target.pointer_storage, holder, first, ops, target, at.slot + length(slots), node));
    slots.append(address);
    code.extend(CellWrite(target.pointer_storage, local, first + 4, ops, target, at.slot + length(slots), node));
    slots.append(address);
    hosts.extend(FieldReferenceHosts(first));
    code.extend(ReferenceCode(ops, target, first, first + 14, at.host, at.slot + length(slots), node));
    slots.extend(FieldReferenceSlots(target));
    hosts.append(WriteHost(first));
    code.extend(ReferenceWriteCode(ops, target, first, at.slot + length(slots) - 1, stored.slot, field.storage,
                                   at.host + 2, at.slot + length(slots), node));
    slots.append(address);
    slots.append(address);
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, NoValue(), NoValue(), marks);
}
// A cell's payload into a new slot: its address at `slot`, its value at
// `slot + 1`.
CellRead :: (storage: int, cell: int, ops: Ops, target: Target, slot: int, node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    code.append(Instruction(ops.host_slot, target.pointer_storage, slot, cell, 0, 0, node));
    read := Instruction(ops.load, storage, slot + 1, slot, 0, 0, node);
    read.offset = target.payload_offset;
    return append(code, read);
}
// A slot's value into a cell's payload, through the cell's address at `slot`.
CellWrite :: (storage: int, value: int, cell: int, ops: Ops, target: Target, slot: int,
              node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    code.append(Instruction(ops.host_slot, target.pointer_storage, slot, cell, 0, 0, node));
    write := Instruction(ops.write, storage, 0, value, slot, 0, node);
    write.offset = target.payload_offset;
    return append(code, write);
}
// The component of the owner `self.C` names, as an index into `types`; -1
// for any other node.
SelfComponent :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], names: Name[],
                  node: int) -> int {
    if (!Is(forest, node, "member_expression")) {
        return -1;
    }
    owner := Field(forest, node, "object");
    if (!Is(forest, owner, "identifier")) {
        return -1;
    }
    found := Lookup(names, Text(forest, text, owner));
    if (found < 0 || names[found].place != SelfPlace) {
        return -1;
    }
    component := FindNativeType(types, Text(forest, text, Field(forest, node, "member")));
    if (component < 0 || types[component].component == 0) {
        return -1;
    }
    return component;
}
// The field `g.F` names on the global `g` that a native reads by its key, as
// an index into `members`; -1 for any other node.
KeyedMember :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
                names: Name[], node: int) -> int {
    global := Field(forest, node, "object");
    if (!Is(forest, global, "identifier")) {
        return -1;
    }
    found := Lookup(names, Text(forest, text, global));
    if (found < 0 || names[found].place != GlobalPlace || names[found].record < 0) {
        return -1;
    }
    field := FindField(types, members, names[found].record, Text(forest, text, Field(forest, node, "member")));
    if (field < 0 || members[field].read < 0 || members[field].read_key == "") {
        return -1;
    }
    return field;
}
// The component type `name` names, -1 for none.
Component :: (types: TypeDecl[], name: string) -> int {
    found := FindNativeType(types, name);
    if (found < 0 || types[found].component == 0) {
        return -1;
    }
    return found;
}
// The constant field `g.F` names on the global `g`, as an index into
// `members`; -1 for any other node.
ConstantMember :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
                   names: Name[], node: int) -> int {
    global := Field(forest, node, "object");
    if (!Is(forest, global, "identifier")) {
        return -1;
    }
    found := Lookup(names, Text(forest, text, global));
    if (found < 0 || names[found].place != GlobalPlace || names[found].record < 0) {
        return -1;
    }
    field := FindField(types, members, names[found].record, Text(forest, text, Field(forest, node, "member")));
    if (field < 0 || !members[field].constant) {
        return -1;
    }
    return field;
}
// The native type named `name`, matched as the catalog matches names: an
// exact name first, else the one that matches loosely; -1 for none or
// several.
FindNativeType :: (types: TypeDecl[], name: string) -> int {
    found: int = -1;
    index: int = 0;
    while (index < length(types)) {
        if (types[index].kind == NativeDecl && types[index].name == name) {
            return index;
        }
        if (types[index].kind == NativeDecl && NameMatches(types[index].name, name)) {
            if (found != -1) {
                found = -2;
            } else {
                found = index;
            }
        }
        index += 1;
    }
    if (found < 0) {
        return -1;
    }
    return found;
}
// The cells of a reference make: its nine arguments, the context, the type
// of types[record] and then `facts`: the reference's kind and element, an
// address, the owner, and a component's ID, layout and size; then its result.
MakeCells :: (target: Target, record: int, facts: uint64[]) -> Cell[] {
    kinds: int[] = [AddressKind, ValueKind, ValueKind, ValueKind, AddressKind, ValueKind, ValueKind, ValueKind,
                    ValueKind];
    storages: int[] = [target.pointer_storage, StructStorage, IntStorage, IntStorage, target.pointer_storage,
                       HandleStorage, WordStorage, WordStorage, WordStorage];
    cells: Cell[] = [];
    index: int = 0;
    while (index < 9) {
        record_index: int = -1;
        if (index == 1) {
            record_index = record;
        }
        cell: Cell = {storage: storages[index], container: 0, record: record_index, constant: facts[index],
                      variant: -1, kind: kinds[index]};
        cells.append(cell);
        index += 1;
    }
    return append(cells, ReferenceCell(target));
}
ReferenceCell :: (target: Target) -> Cell {
    return {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: ReferenceKind};
}
// The make facts of a reference to the owner's component `declared`.
ComponentFacts :: (declared: TypeDecl) -> uint64[] {
    return [0, 0, uint64(ComponentReference), 0xFFFFFFFFFFFFFFFF, 0, 0, declared.component, declared.layout,
            uint64(declared.size)];
}
// The cells of a field write through references: MakeCells, then the field
// reference's reference, type, offset and element flag and its result, and the
// write's reference, value and bool result.
ReferenceCells :: (target: Target, record: int, facts: uint64[], field: TypeMember) -> Cell[] {
    made := ReferenceCell(target);
    typed: Cell = {storage: field.storage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    offset: Cell = {storage: WordStorage, container: 0, record: -1, constant: uint64(field.offset), variant: -1,
                    kind: ValueKind};
    element: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    return extend(MakeCells(target, record, facts), [made, typed, offset, element, made, made, typed, element]);
}
// The reference make and the field reference, written through, over the
// cells from `first`.
FieldReferenceHosts :: (first: int) -> Host[] {
    make: Host = {intrinsic: ReferenceMakeIntrinsic, linked: -1, first: first, result_first: first + 9, result_count: 1,
                  written: true};
    field: Host = {intrinsic: ReferenceFieldIntrinsic, linked: -1, first: first + 10, result_first: first + 14,
                   result_count: 1, written: false};
    return [make, field];
}
WriteHost :: (first: int) -> Host {
    return {intrinsic: ReferenceWriteIntrinsic, linked: -1, first: first + 15, result_first: first + 17,
            result_count: 1, written: false};
}
// The make, its reference into the first cell of the host after it, a field
// reference or a read, then that host, whose result in cell `result` it
// leaves at slot + 4; the make's reference stays at slot + 1. `host` is the
// make's host.
ReferenceCode :: (ops: Ops, target: Target, first: int, result: int, host: int, slot: int,
                  node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [Instruction(ops.host_call, 0, 0, target.data_failure, 0, host, node)];
    code.extend(CellRead(target.pointer_storage, first + 9, ops, target, slot, node));
    code.extend(CellWrite(target.pointer_storage, slot + 1, first + 10, ops, target, slot + 2, node));
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, host + 1, node));
    return extend(code, CellRead(target.pointer_storage, result, ops, target, slot + 3, node));
}
// The slots ReferenceCode uses for a field reference.
FieldReferenceSlots :: (target: Target) -> Slot[] {
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    reference: Slot = {storage: target.pointer_storage, kind: ReferenceKind};
    return [address, reference, address, address, reference];
}
// The write of `value` through the field reference at slot `reference`,
// with two address slots from `slot`. `host` is the write's host.
ReferenceWriteCode :: (ops: Ops, target: Target, first: int, reference: int, value: int, storage: int, host: int,
                       slot: int, node: snapshot.SnapshotNode) -> Code[] {
    code := CellWrite(target.pointer_storage, reference, first + 15, ops, target, slot, node);
    code.extend(CellWrite(storage, value, first + 16, ops, target, slot + 1, node));
    return append(code, Instruction(ops.host_call, 0, 0, target.data_failure, 0, host, node));
}
// The context and the owner into the cells of a make from `first`, through
// the four OwnerSlots from `slot`. The owner is the entity in slot `entity`,
// or the behavior's own when that is -1.
OwnerCode :: (ops: Ops, target: Target, first: int, entity: int, slot: int, node: snapshot.SnapshotNode) -> Code[] {
    owner := entity;
    code: Code[] = [Instruction(ops.context, target.pointer_storage, slot, 0, 0, 1, node)];
    if (owner < 0) {
        owner = slot + 1;
        code.append(Instruction(ops.owner, HandleStorage, owner, 0, 0, 0, node));
    }
    code.extend(CellWrite(target.pointer_storage, slot, first, ops, target, slot + 2, node));
    return extend(code, CellWrite(HandleStorage, owner, first + 5, ops, target, slot + 3, node));
}
OwnerSlots :: (target: Target) -> Slot[] {
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    owner: Slot = {storage: HandleStorage, kind: ValueKind};
    return [address, owner, address, address];
}
// `self.C.f = v` as stage zero orders it: the references to the owner's
// component types[component] and to its field members[field] first, after
// `before`; then the value, and the write in ComponentPhase. A `compound`
// assignment reads the field through the reference first and combines it
// with the value. Pushing onto `before` would make this step and its callers
// copy their arguments.
ComponentReferenceStep :: (before: Code[], types: TypeDecl[], members: TypeMember[], component: int, field: int,
                           value: int, compound: bool, item: Work, ops: Ops, target: Target, at: Bases,
                           node: snapshot.SnapshotNode) -> Step {
    locals: Slot[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    marks: int[] = [];
    first := at.cell;
    declared := members[field];
    cells := ReferenceCells(target, component, ComponentFacts(types[component]), declared);
    code := OwnerCode(ops, target, first, -1, at.slot, node);
    code.extend(ReferenceCode(ops, target, first, first + 14, at.host, at.slot + 4, node));
    slots := extend(OwnerSlots(target), FieldReferenceSlots(target));
    reference := at.slot + length(slots) - 1;
    write := Resume(item.node, ComponentPhase, first, field);
    write.c = reference;
    hosts := FieldReferenceHosts(first);
    if (!compound) {
        next: Work[] = [Expect(value, declared.storage, 0, -1), write];
        return Step.Emitted(extend(before, code), slots, locals, cells, hosts, roots, calls, bound, next, 0,
                            NoValue(), NoValue(), marks);
    }
    // The read takes the field reference and returns the field's value, in
    // cells after the write's.
    typed: Cell = {storage: declared.storage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    cells.extend([ReferenceCell(target), typed]);
    copy: Host = {intrinsic: ReferenceReadIntrinsic, linked: -1, first: first + 18, result_first: first + 19,
                  result_count: 1, written: false};
    hosts.append(copy);
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    current: Slot = {storage: declared.storage, kind: ValueKind};
    code.extend(CellWrite(target.pointer_storage, reference, first + 18, ops, target, reference + 1, node));
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host + 2, node));
    code.extend(CellRead(declared.storage, first + 19, ops, target, reference + 2, node));
    slots.extend([address, address, current]);
    next: Work[] = [Visit(value), Resume(item.node, CombinePhase, 0, 0), write];
    return Step.Emitted(extend(before, code), slots, locals, cells, hosts, roots, calls, bound, next, 0,
                        Typed(reference + 3, declared.storage, 0, -1), NoValue(), marks);
}
// Where ComponentReadStep leaves the make's reference, from its first slot.
ComponentReferenceSlot: int : 5;
// `self.C`: the owner's component types[component], read through a reference
// into a record of its own, as stage zero reads it, after `before`; `e.C`
// reads the component of the entity in slot `entity`, which it pops. A
// compound assignment writes through the reference, so its make is `written`,
// and schedules `next`.
ComponentReadStep :: (before: Code[], types: TypeDecl[], component: int, written: bool, entity: int, next: Work[],
                      ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    locals: Slot[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    marks: int[] = [];
    first := at.cell;
    read: Cell = {storage: StructStorage, container: 0, record: component, constant: 0, variant: -1,
                  kind: ValueKind};
    cells := extend(MakeCells(target, component, ComponentFacts(types[component])), [ReferenceCell(target), read]);
    make: Host = {intrinsic: ReferenceMakeIntrinsic, linked: -1, first: first, result_first: first + 9, result_count: 1,
                  written: written};
    copy: Host = {intrinsic: ReferenceReadIntrinsic, linked: -1, first: first + 10, result_first: first + 11,
                  result_count: 1, written: false};
    code := OwnerCode(ops, target, first, entity, at.slot, node);
    code.extend(ReferenceCode(ops, target, first, first + 11, at.host, at.slot + 4, node));
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    reference: Slot = {storage: target.pointer_storage, kind: ReferenceKind};
    slots := extend(OwnerSlots(target), [address, reference, address, address, address]);
    value := at.slot + length(slots) - 1;
    roots: Root[] = [{slot: value, storage: StructStorage, container: 0, record: component}];
    popped: int = 0;
    if (entity >= 0) {
        popped = 1;
    }
    return Step.Emitted(extend(before, code), slots, locals, cells, [make, copy], roots, calls, bound, next, popped,
                        Typed(value, StructStorage, 0, component), NoValue(), marks);
}
// `self.C = v`: the reference to the owner's component types[component],
// made to be written through, after `before`; `next` writes the value.
ComponentMakeStep :: (before: Code[], types: TypeDecl[], component: int, next: Work[], ops: Ops, target: Target,
                      at: Bases, node: snapshot.SnapshotNode) -> Step {
    locals: Slot[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    marks: int[] = [];
    first := at.cell;
    make: Host = {intrinsic: ReferenceMakeIntrinsic, linked: -1, first: first, result_first: first + 9, result_count: 1,
                  written: true};
    code := OwnerCode(ops, target, first, -1, at.slot, node);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.extend(CellRead(target.pointer_storage, first + 9, ops, target, at.slot + 4, node));
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    reference: Slot = {storage: target.pointer_storage, kind: ReferenceKind};
    slots := extend(OwnerSlots(target), [address, reference]);
    cells := MakeCells(target, component, ComponentFacts(types[component]));
    return Step.Emitted(extend(before, code), slots, locals, cells, [make], roots, calls, bound, next, 0, NoValue(),
                        NoValue(), marks);
}
// The type a native type stands for, as stage zero's canonical type: its
// underlying type, followed to the end.
Canonical :: (types: TypeDecl[], record: int) -> int {
    at := record;
    steps: int = 0;
    while (types[at].kind == NativeDecl && types[at].parent >= 0 && steps < length(types)) {
        at = types[at].parent;
        steps += 1;
    }
    return at;
}
// The write of `self.C = v` and `self.C op= v`: the record, of a type that
// stands for the same one as the component's, types[item.b], through the
// reference at slot item.a.
ComponentAssignStep :: (forest: snapshot.SnapshotNode[], document: int, types: TypeDecl[], value: Value, item: Work,
                        ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    if (!Single(value, StructStorage) || Canonical(types, value.record) != Canonical(types, item.b)) {
        return Fail(forest, item.node, document, "assigned value differs from its component");
    }
    locals: Slot[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    record: Cell = {storage: StructStorage, container: 0, record: item.b, constant: 0, variant: -1, kind: ValueKind};
    done: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    code := CellWrite(target.pointer_storage, item.a, at.cell, ops, target, at.slot, node);
    code.extend(CellWrite(target.pointer_storage, value.slot, at.cell + 1, ops, target, at.slot + 1, node));
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    write: Host = {intrinsic: ReferenceWriteIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 2,
                   result_count: 1, written: false};
    return Step.Emitted(code, [address, address], locals, [ReferenceCell(target), record, done], [write], roots, calls,
                        bound, next, 1, NoValue(), NoValue(), marks);
}
// The write of `self.C.f = v`: the value, in the field's storage, through the
// field reference at slot item.c over the cells from item.a. An integer
// becomes a floating field's value as stage zero converts it: exactly to a
// double, then to a float; a literal is a constant of the field's type.
ComponentWriteStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, field: TypeMember, value: Value,
                       item: Work, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    floating := field.storage == FloatStorage || field.storage == DoubleStorage;
    stored := value;
    if (Single(value, NumberStorage) && floating) {
        switch FloatConstantStep(forest, text, document, value, field.storage, ops, at, node) {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(typed_code, typed_slots, typed_locals, typed_cells, typed_hosts, typed_roots, typed_calls,
                          typed_bound, typed_next, typed_popped, typed_value, typed_retain, typed_marks):
                code = typed_code;
                slots = typed_slots;
                stored = typed_value;
        }
    } else if (value.container == 0 && Converts(value.storage, field.storage)) {
        code = NumberCode(ops, value.storage, field.storage, value.slot, at.slot, node);
        slots = NumberSlots(value.storage, field.storage);
        stored = Typed(at.slot + length(slots) - 1, field.storage, 0, -1);
    }
    if (!SameType(field.storage, 0, -1, stored)) {
        return Fail(forest, item.node, document, "field value differs from its type");
    }
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    code.extend(ReferenceWriteCode(ops, target, item.a, item.c, stored.slot, field.storage, at.host,
                                   at.slot + length(slots), node));
    slots.append(address);
    slots.append(address);
    hosts: Host[] = [WriteHost(item.a)];
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, NoValue(), NoValue(), marks);
}
// The bit patterns of the untyped literal at `node`: a number, or `-` on one.
NumberBits :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> FloatBits {
    if (Is(forest, node, "unary_expression")) {
        return LiteralBits(Text(forest, text, Field(forest, node, "operand")), true);
    }
    return LiteralBits(Text(forest, text, node), false);
}
// The untyped literal `literal` as a constant of the floating type `storage`.
FloatConstantStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, literal: Value, storage: int,
                      ops: Ops, at: Bases, node: snapshot.SnapshotNode) -> Step {
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    bits: uint64 = 0;
    switch NumberBits(forest, text, literal.record) {
        case .OutOfRange:
            return Fail(forest, literal.record, document, "Numeric literal is outside the range of its type");
        case .Finite(double_bits, float_fits, float_bits):
            if (storage == FloatStorage && !float_fits) {
                return Fail(forest, literal.record, document, "Numeric literal is outside the range of float");
            }
            bits = double_bits;
            if (storage == FloatStorage) {
                bits = float_bits;
            }
    }
    code := extend([ConstantCode(ops, storage, bits, at.slot, node)],
                   LiteralWatch(forest, ops, at.slot, storage, literal.record));
    slots: Slot[] = [ValueLocal(storage)];
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, Typed(at.slot, storage, 0, -1),
                        NoValue(), marks);
}
// Whether a number of type `from` converts to `to` implicitly: an integer
// widens or becomes a floating value, and the floating types convert to one
// another.
Converts :: (from: int, to: int) -> bool {
    return Widens(from, to) || ((Integer(from) || Floating(from)) && Floating(to) && from != to);
}
// The conversion of the number in slot `input` from `from` to `to`, through
// the NumberSlots from `slot`, as stage zero converts: an integer becomes a
// floating value exactly as a double first, the floating types convert to
// one another, and anything else casts.
NumberCode :: (ops: Ops, from: int, to: int, input: int, slot: int, node: snapshot.SnapshotNode) -> Code[] {
    if (Floating(from) && Floating(to)) {
        return [Instruction(ops.convert, to, slot, input, 0, 0, node)];
    }
    if (!Integer(from) || !Floating(to)) {
        return [CastCode(ops, to, slot, input, 0, node)];
    }
    exact := Instruction(ops.cast, DoubleStorage, slot, input, 0, 0, node);
    if (to == DoubleStorage) {
        return [exact];
    }
    return [exact, Instruction(ops.convert, FloatStorage, slot + 1, slot, 0, 0, node)];
}
NumberSlots :: (from: int, to: int) -> Slot[] {
    if (Integer(from) && to == FloatStorage) {
        return [ValueLocal(DoubleStorage), ValueLocal(FloatStorage)];
    }
    return [ValueLocal(to)];
}
// The index of the named result `name` of `called`, -1 when none.
NamedResult :: (params: Param[], called: Callable, name: string) -> int {
    index: int = 0;
    while (index < called.results) {
        if (params[called.first + called.count + index].name == name) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// Returns each named result of `callable` from its local, which start at
// `named`, through the NamedResultsSlots from `slot`.
NamedResultsCode :: (ops: Ops, params: Param[], callable: Callable, named: int, slot: int,
                     node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    index: int = 0;
    while (index < callable.results) {
        storage := params[callable.first + callable.count + index].storage;
        code.append(Instruction(ops.local, storage, slot + index, named + index, 0, 0, node));
        code.append(Instruction(ops.result, storage, 0, slot + index, 0, index, node));
        index += 1;
    }
    return code;
}
NamedResultsSlots :: (params: Param[], callable: Callable) -> Slot[] {
    slots: Slot[] = [];
    index: int = 0;
    while (index < callable.results) {
        slots.append(ValueLocal(params[callable.first + callable.count + index].storage));
        index += 1;
    }
    return slots;
}
// `return` in a function with named results, after `before`: alone, it
// returns them; `return (a, b)` gives each its value, with ReturnsPhase.
NamedReturnStep :: (forest: snapshot.SnapshotNode[], document: int, before: Code[], params: Param[],
                    callable: Callable, named: int, value: int, item: Work, ops: Ops, at: Bases,
                    node: snapshot.SnapshotNode) -> Step {
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    marks: int[] = [];
    next: Work[] = [];
    if (value < 0) {
        code := extend(before, [CompletionCode(ops, node)]);
        code.extend(NamedResultsCode(ops, params, callable, named, at.slot, node));
        code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, node));
        return Step.Emitted(code, NamedResultsSlots(params, callable), locals, cells, hosts, roots, calls, bound, next,
                            0, NoValue(), NoValue(), marks);
    }
    if (!Is(forest, value, "argument_list")) {
        return Fail(forest, value, document, "a function with named results returns `(...)`, one value for each");
    }
    index: int = 0;
    argument := FirstMember(forest, value);
    while (argument >= 0) {
        if (index >= callable.results || Is(forest, argument, "named_argument")) {
            return Fail(forest, value, document, "a function with named results returns `(...)`, one value for each");
        }
        result := params[callable.first + callable.count + index];
        next.append(Expect(argument, result.storage, 0, result.record));
        index += 1;
        argument = NextMember(forest, argument);
    }
    if (index != callable.results) {
        return Fail(forest, value, document, "a function with named results returns `(...)`, one value for each");
    }
    next.append(Resume(item.node, ReturnsPhase, 0, 0));
    slots: Slot[] = [];
    return Step.Emitted(before, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(),
                        marks);
}
// `return (a, b)` once its values are on top: each converted as a store
// converts it, then returned as its named result.
ResultsStep :: (forest: snapshot.SnapshotNode[], document: int, params: Param[], callable: Callable, values: Value[],
                top: int, item: Work, ops: Ops, at: Bases, node: snapshot.SnapshotNode) -> Step {
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    // Each value stores its result, then the function completes.
    code: Code[] = [];
    returned_nodes := Members(forest, Field(forest, item.node, "value"));
    index: int = 0;
    while (index < callable.results) {
        code.append(SymbolCode(ops, params[callable.first + callable.count + index].node,
                               forest[returned_nodes[index]]));
        index += 1;
    }
    code.append(CompletionCode(ops, node));
    slots: Slot[] = [];
    index = 0;
    while (index < callable.results) {
        result := params[callable.first + callable.count + index];
        returned := values[top - callable.results + index];
        if (returned.container == 0 && Converts(returned.storage, result.storage)) {
            code.extend(NumberCode(ops, returned.storage, result.storage, returned.slot,
                                   at.slot + length(slots), node));
            slots.extend(NumberSlots(returned.storage, result.storage));
            returned = Typed(at.slot + length(slots) - 1, result.storage, 0, -1);
        }
        if (!SameType(result.storage, 0, result.record, returned)) {
            return Fail(forest, item.node, document, "returned value differs from the result type");
        }
        code.append(Instruction(ops.result, result.storage, 0, returned.slot, 0, index, node));
        index += 1;
    }
    code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, node));
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, callable.results, NoValue(),
                        NoValue(), marks);
}
// `step`, with `prefix` taking the slots before its own.
PrefixSlots :: (prefix: Slot[], step: Step) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, value, retained, marks):
            return Step.Emitted(code, extend(prefix, slots), locals, cells, hosts, roots, calls, bound, next, popped,
                                value, retained, marks);
    }
}
// The number types this compiler emits.
Numeric :: (storage: int) -> bool {
    return Integer(storage) || Floating(storage);
}
// Whether a value combines through a numeric aggregate native: a number, or a
// record of numbers. Stage zero also takes records of such records, whose
// field types this compiler does not see.
NumericAggregate :: (types: TypeDecl[], members: TypeMember[], value: Value) -> bool {
    if (value.container != 0) {
        return false;
    }
    if (value.storage == NumberStorage || Numeric(value.storage)) {
        return true;
    }
    if (value.storage != StructStorage || types[value.record].count == 0) {
        return false;
    }
    at := types[value.record].first;
    while (at < types[value.record].first + types[value.record].count) {
        if (!Numeric(members[at].storage)) {
            return false;
        }
        at += 1;
    }
    return true;
}
// Whether the records types[left] and types[right] have as many fields, each
// of one named as a field of the other.
SameFields :: (types: TypeDecl[], members: TypeMember[], left: int, right: int) -> bool {
    if (types[left].count != types[right].count) {
        return false;
    }
    at := types[left].first;
    while (at < types[left].first + types[left].count) {
        if (FindField(types, members, right, members[at].name) < 0) {
            return false;
        }
        at += 1;
    }
    return true;
}
// The native that combines records for the binary `operator`: -1 for none,
// -2 for several.
FindAggregate :: (operators: NumericOperator[], operator: string) -> int {
    found: int = -1;
    for (candidate in operators) {
        if (candidate.operator == operator && found >= 0) {
            return -2;
        }
        if (candidate.operator == operator) {
            found = candidate.native;
        }
    }
    return found;
}
// `a op b` and `self.C op= b` when an operand is a record, as stage zero
// resolves it: the operator's numeric aggregate native combines records of
// numbers, and a record with a number, field by field. The result has the
// type of the first record operand; an untyped literal is a double.
AggregateStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                  members: TypeMember[], operators: NumericOperator[], values: Value[], top: int, item: Work,
                  ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    locals: Slot[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    operator := Text(forest, text, Field(forest, item.node, "operator"));
    if (node.kind == "assignment") {
        operator = CompoundOperator(operator);
    }
    native := FindAggregate(operators, operator);
    if (native == -2) {
        return Fail(forest, item.node, document, "Ambiguous operator overload");
    }
    left := values[top - 2];
    right := values[top - 1];
    records := Single(left, StructStorage) && Single(right, StructStorage);
    if (native < 0 || !NumericAggregate(types, members, left) || !NumericAggregate(types, members, right) ||
        (records && !SameFields(types, members, left.record, right.record))) {
        return Fail(forest, item.node, document, "operator does not apply to these operands");
    }
    result := right;
    if (Single(left, StructStorage)) {
        result = left;
    }
    // An untyped operand is a double constant first.
    code: Code[] = [];
    slots: Slot[] = [];
    operands: Value[] = [];
    pair: Value[] = [left, right];
    for (operand in pair) {
        value := operand;
        if (value.storage == NumberStorage) {
            shifted: Bases = {pc: at.pc, slot: at.slot + length(slots), local: at.local, cell: at.cell,
                              host: at.host, call: at.call};
            switch FloatConstantStep(forest, text, document, value, DoubleStorage, ops, shifted, node) {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(typed_code, typed_slots, typed_locals, typed_cells, typed_hosts, typed_roots,
                              typed_calls, typed_bound, typed_next, typed_popped, typed_value, typed_retain,
                              typed_marks):
                    code.extend(typed_code);
                    slots.extend(typed_slots);
                    value = typed_value;
            }
        }
        operands.append(value);
    }
    combined: Cell = {storage: StructStorage, container: 0, record: result.record, constant: 0, variant: -1,
                      kind: ValueKind};
    host: Host = {intrinsic: 0, linked: native, first: at.cell, result_first: at.cell + 2, result_count: 1,
                  written: false};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    code.extend(CallCode(operands, at.cell, at.host, target.pointer_storage, at.slot + length(slots), ops,
                         target, node));
    slots.extend(CallSlots(2, address, target));
    made := at.slot + length(slots) - 1;
    root: Root = {slot: made, storage: StructStorage, container: 0, record: result.record};
    roots.append(root);
    return Step.Emitted(code, slots, locals, CallCells(operands, combined), [host], roots, calls, bound, next, 2,
                        Typed(made, StructStorage, 0, result.record), NoValue(), marks);
}
// A native char pointer is read through its reflected field adapter.
NativeTextReadStep :: (object: Value, field: TypeMember, ops: Ops, target: Target, at: Bases,
                       node: snapshot.SnapshotNode) -> Step {
    first := at.cell;
    facts: uint64[] = [0, 0, 0, 0xFFFFFFFFFFFFFFFF, 0, 0, 0, 0, 0];
    cells := ReferenceCells(target, object.record, facts, field);
    cells.extend([ReferenceCell(target), TypedCell(TextStorage, 0, -1),
                  TypedCell(StructStorage, 0, object.record)]);
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    slots: Slot[] = [address, address, address, address];
    code := CellWrite(target.pointer_storage, object.slot, first + 20, ops, target, at.slot, node);
    code.append(Instruction(ops.context, target.pointer_storage, at.slot, 0, 0, 1, node));
    code.extend(CellWrite(target.pointer_storage, at.slot, first, ops, target, at.slot + 1, node));
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + 2, first + 20, 0, 0, node));
    code.extend(CellWrite(target.pointer_storage, at.slot + 2, first + 4, ops, target, at.slot + 3, node));
    hosts := FieldReferenceHosts(first);
    code.extend(ReferenceCode(ops, target, first, first + 14, at.host, at.slot + 4, node));
    slots.extend(FieldReferenceSlots(target));
    hosts.append(ReadThroughHost(first + 18));
    code.extend(ReadThroughCode(ops, target, TextStorage, 0, at.slot + 8, first + 18, at.host + 2,
                                at.slot + 9, node));
    slots.extend(ReadThroughSlots(TextStorage, 0, target));
    return Step.Emitted(code, slots, [], cells, hosts, [], [], [], [], 1,
                        Typed(at.slot + 11, TextStorage, 0, -1), NoValue(), []);
}
// `v.f`, where natives[f.read] reads the field: a call of it on `v`.
NativeReadStep :: (object: Value, field: TypeMember, ops: Ops, target: Target, at: Bases,
                   node: snapshot.SnapshotNode) -> Step {
    locals: Slot[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    arguments: Value[] = [object];
    read: Cell = {storage: field.storage, container: 0, record: field.record, constant: 0, variant: -1,
                  kind: ValueKind};
    host: Host = {intrinsic: 0, linked: field.read, first: at.cell, result_first: at.cell + 1, result_count: 1,
                  written: false};
    value: Slot = {storage: SlotStorage(field.storage, 0, target), kind: SlotKind(field.storage, 0)};
    code := CallCode(arguments, at.cell, at.host, value.storage, at.slot, ops, target, node);
    return Step.Emitted(code, CallSlots(1, value, target), locals, CallCells(arguments, read), [host], roots, calls,
                        bound, next, 1, Typed(at.slot + 2, field.storage, 0, -1), NoValue(), marks);
}
// Whether the compiler passes each of a native's ports: a result takes a
// known or inferred type, never each value's own.
Supported :: (ports: Port[], called: Native) -> bool {
    port := called.first;
    while (port < called.first + called.parameters + called.results) {
        if (ports[port].storage == UnsupportedPort ||
            (port >= called.first + called.parameters && ports[port].storage == AnyPort)) {
            return false;
        }
        port += 1;
    }
    return true;
}
// Whether several natives have the exact name `name`.
Overloaded :: (natives: Native[], name: string) -> bool {
    count: int = 0;
    for (candidate in natives) {
        if (candidate.name == name) {
            count += 1;
        }
    }
    return count > 1;
}
// The one native named `name` whose parameters each take the argument of
// `values[first, first + count)` in its position; -1 for none or several.
Overload :: (natives: Native[], ports: Port[], name: string, values: Value[], first: int, count: int) -> int {
    found: int = -1;
    index: int = 0;
    while (index < length(natives)) {
        candidate := natives[index];
        takes := candidate.name == name && candidate.parameters == count;
        at: int = 0;
        while (takes && at < count) {
            port := ports[candidate.first + at];
            value := values[first + at];
            takes = port.storage != UnsupportedPort &&
                    (port.storage <= 0 || (port.storage == value.storage && port.container == value.container));
            at += 1;
        }
        if (takes && found >= 0) {
            return -1;
        }
        if (takes) {
            found = index;
        }
        index += 1;
    }
    return found;
}
// The record make of natives[native], -1 for none.
FindMake :: (makes: NativeMake[], native: int) -> int {
    index: int = 0;
    while (index < length(makes)) {
        if (makes[index].native == native) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// A native that makes a record of its arguments, such as `vec2(x, y)`, as
// stage zero lowers it: a struct literal of the fields they give, in order.
MakeStep :: (forest: snapshot.SnapshotNode[], document: int, types: TypeDecl[], members: TypeMember[], make: NativeMake,
             make_fields: int[], values: Value[], first: int, count: int, call: int, ops: Ops, target: Target,
             at: Bases, node: snapshot.SnapshotNode) -> Step {
    locals: Slot[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    code: Code[] = [];
    slots: Slot[] = [];
    record := make.record;
    if (record < 0) {
        return Fail(forest, call, document, "the native makes a record this compiler does not see");
    }
    header: Cell = {storage: StructStorage, container: 0, record: record, constant: 0, variant: -1, kind: ValueKind};
    cells: Cell[] = [header];
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    index: int = 0;
    while (index < count) {
        position := make_fields[make.first + index];
        if (position < 0) {
            return Fail(forest, call, document, "a native's argument gives no field of its record");
        }
        field := members[types[record].first + position];
        value := values[first + index];
        if (value.container == 0 && Converts(value.storage, field.storage)) {
            code.extend(NumberCode(ops, value.storage, field.storage, value.slot, at.slot + length(slots),
                                   node));
            slots.extend(NumberSlots(value.storage, field.storage));
            value = Typed(at.slot + length(slots) - 1, field.storage, 0, -1);
        }
        if (!SameType(field.storage, 0, -1, value)) {
            return Fail(forest, call, document, "argument differs from its parameter type");
        }
        offset: Cell = {storage: WordStorage, container: 0, record: -1, constant: uint64(field.offset), variant: -1,
                        kind: ValueKind};
        content: Cell = {storage: value.storage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
        cells.extend([offset, content]);
        slots.append(address);
        code.extend(CellWrite(SlotStorage(value.storage, 0, target), value.slot, at.cell + length(cells) - 1,
                              ops, target, at.slot + length(slots) - 1, node));
        index += 1;
    }
    cells.append(header);
    host: Host = {intrinsic: ConstructIntrinsic, linked: -1, first: at.cell, result_first: at.cell + length(cells) - 1,
                  result_count: 1, written: false};
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.extend(CellRead(target.pointer_storage, at.cell + length(cells) - 1, ops, target,
                         at.slot + length(slots), node));
    slots.extend([address, address]);
    made := at.slot + length(slots) - 1;
    roots: Root[] = [{slot: made, storage: StructStorage, container: 0, record: record}];
    return Step.Emitted(code, slots, locals, cells, [host], roots, calls, bound, next, count,
                        Typed(made, StructStorage, 0, record), NoValue(), marks);
}
// The cells of a native call: one for each argument, then its result.
CallCells :: (arguments: Value[], result: Cell) -> Cell[] {
    cells: Cell[] = [];
    for (argument in arguments) {
        record: int = -1;
        if (argument.storage == StructStorage) {
            record = argument.record;
        }
        cell: Cell = {storage: argument.storage, container: argument.container, record: record, constant: 0,
                      variant: -1, kind: ValueKind};
        cells.append(cell);
    }
    return append(cells, result);
}
// Each argument into its cell from `first`, the call as host `host`, and its
// result, of slot storage `storage`, from the cell after them, through the
// CallSlots from `slot`.
CallCode :: (arguments: Value[], first: int, host: int, storage: int, slot: int, ops: Ops, target: Target,
             node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    index: int = 0;
    for (argument in arguments) {
        code.extend(CellWrite(SlotStorage(argument.storage, argument.container, target), argument.slot,
                              first + index, ops, target, slot + index, node));
        index += 1;
    }
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, host, node));
    return extend(code, CellRead(storage, first + index, ops, target, slot + index, node));
}
// An address for each of `count` arguments and the result's, then the result.
CallSlots :: (count: int, result: Slot, target: Target) -> Slot[] {
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    slots: Slot[] = [];
    index: int = 0;
    while (index <= count) {
        slots.append(address);
        index += 1;
    }
    return append(slots, result);
}
// A record or array parameter the body writes, item.a: phase 0 reads it and
// copies it into a fresh cell; phase 1 binds its name to that cell.
ParameterStep :: (params: Param[], callable: Callable, item: Work, ops: Ops, target: Target, at: Bases,
                  node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    param := params[callable.first + item.a];
    if (item.b == 1) {
        return BoxParameterStep(param, item.a, ops, target, at, node);
    }
    if (item.phase == 1) {
        binding: Name = {name: param.name, place: CellPlace, index: at.cell - 1, storage: param.storage,
                         container: param.container, record: param.record, writable: true, node: param.node};
        bound.append(binding);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, NoValue(), NoValue(),
                            marks);
    }
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    slots.append(address);
    read := Instruction(ops.array, target.pointer_storage, at.slot, item.a, 0, ops.argument, node);
    read.value_storage = param.storage;
    read.value_container = param.container;
    read.value_record = param.record;
    code.append(read);
    root: Root = {slot: at.slot, storage: param.storage, container: param.container, record: param.record};
    roots.append(root);
    next.append(Resume(item.node, 1, item.a, 0));
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(),
                        Typed(at.slot, param.storage, param.container, param.record), marks);
}
// A match on the union in local `subject`, or, when `subject` is -1, in slot
// `from`, which it first saves to a new local. When the union holds variant
// types[variant], the names in `bindings` take its payload fields in order.
// A switch arm (`arm`) jumps past itself when the test fails, through the jump
// the mark reports, and watches the subject at `subject_node` it reads and
// the test of the pattern at `pattern_node`; an `is` expression produces the
// test, negated when `negated`. Bindings are not writable, so record and array payloads are read
// in place.
MatchStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
              members: TypeMember[], names: Name[], scope: int, subject: int, from: int, variant: int,
              bindings: int, arm: bool, negated: bool, subject_node: int, pattern_node: int, ops: Ops,
              target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    sum_type := types[variant].parent;
    value: Slot = {storage: UnionStorage, kind: ValueKind};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    source := subject;
    if (source < 0) {
        locals.append(ValueLocal(UnionStorage));
        source = at.local;
        code.append(Instruction(ops.save, UnionStorage, 0, from, 0, source, node));
    }
    slots.append(value);
    code.append(Instruction(ops.local, UnionStorage, at.slot, source, 0, 0, node));
    if (arm) {
        code.append(ScalarWatch(ops, at.slot, UnionStorage, 0, true, forest[subject_node]));
    }
    // The test takes the union and the tag and returns whether they match.
    held: Cell = {storage: UnionStorage, container: 0, record: sum_type, constant: 0, variant: -1, kind: ValueKind};
    tag: Cell = {storage: WordStorage, container: 0, record: -1, constant: 0, variant: variant, kind: ValueKind};
    answer: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    cells.append(held);
    cells.append(tag);
    cells.append(answer);
    slots.append(address);
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + 1, at.cell, 0, 0, node));
    write := Instruction(ops.write, UnionStorage, 0, at.slot, at.slot + 1, 0, node);
    write.offset = target.payload_offset;
    code.append(write);
    test: Host = {intrinsic: UnionTestIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 2, result_count: 1,
                  written: false};
    hosts.append(test);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    slots.append(address);
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + 2, at.cell + 2, 0, 0, node));
    slots.append(flag);
    read := Instruction(ops.load, BoolStorage, at.slot + 3, at.slot + 2, 0, 0, node);
    read.offset = target.payload_offset;
    code.append(read);
    if (arm) {
        code.append(ScalarWatch(ops, at.slot + 3, BoolStorage, 0, true, forest[pattern_node]));
    }
    marks: int[] = [];
    produced := Typed(at.slot + 3, BoolStorage, 0, -1);
    if (arm) {
        code.append(Instruction(ops.branch_if, 0, 0, at.slot + 3, 0, at.pc + length(code) + 2, node));
        marks.append(at.pc + length(code));
        code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
        produced = NoValue();
    } else if (negated) {
        // Not is equality with false.
        slots.append(flag);
        constant := Instruction(ops.constant, BoolStorage, at.slot + 4, 0, 0, 0, node);
        constant.value_storage = BoolStorage;
        code.append(constant);
        slots.append(flag);
        code.append(Instruction(ops.eq, BoolStorage, at.slot + 5, at.slot + 3, at.slot + 4, -1, node));
        produced = Typed(at.slot + 5, BoolStorage, 0, -1);
    }
    // Each binding takes the payload field at its position.
    position: int = 0;
    binding := FirstMember(forest, bindings);
    while (binding >= 0) {
        field := members[types[variant].first + position];
        first := at.cell + length(cells);
        index: Cell = {storage: IntStorage, container: 0, record: -1, constant: uint64(position), variant: -1,
                       kind: ValueKind};
        whole: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
        payload: Cell = {storage: field.storage, container: field.container, record: field.record, constant: 0,
                         variant: -1, kind: ValueKind};
        cells.append(held);
        cells.append(tag);
        cells.append(index);
        cells.append(whole);
        cells.append(payload);
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1, first, 0, 0,
                                node));
        put := Instruction(ops.write, UnionStorage, 0, at.slot, at.slot + length(slots) - 1, 0, node);
        put.offset = target.payload_offset;
        code.append(put);
        get: Host = {intrinsic: UnionGetIntrinsic, linked: -1, first: first, result_first: first + 4, result_count: 1,
                     written: false};
        hosts.append(get);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host + length(hosts) - 1,
                                node));
        name := Text(forest, text, binding);
        if (Declared(names, scope, name) || Lookup(bound, name) >= 0) {
            return Fail(forest, binding, document, format_text("Duplicate declaration '{}'", name));
        }
        code.append(SymbolCode(ops, binding, forest[binding]));
        if (Pointer(field.storage, field.container)) {
            view: Name = {name: name, place: CellPlace, index: first + 4, storage: field.storage,
                          container: field.container, record: field.record, writable: false, node: binding};
            bound.append(view);
        } else {
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1,
                                    first + 4, 0, 0, node));
            loaded: Slot = {storage: field.storage, kind: ValueKind};
            slots.append(loaded);
            take := Instruction(ops.load, field.storage, at.slot + length(slots) - 1, at.slot + length(slots) - 2, 0, 0, node);
            take.offset = target.payload_offset;
            code.append(take);
            locals.append(ValueLocal(field.storage));
            code.append(Instruction(ops.save, field.storage, 0, at.slot + length(slots) - 1, 0,
                                    at.local + length(locals) - 1, node));
            copy: Name = {name: name, place: LocalPlace, index: at.local + length(locals) - 1, storage: field.storage,
                          container: 0, record: field.record, writable: false, node: binding};
            bound.append(copy);
        }
        position += 1;
        binding = NextMember(forest, binding);
    }
    popped: int = 0;
    if (!arm) {
        popped = 1;
    }
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, NoValue(),
                        marks);
}

// `value is .V` and `value is not .V`. Bindings, `value is .V(a, b)`, are
// allowed only in an if or while condition, as stage zero allows them; they
// hold the payload where the test holds.
IsStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
           members: TypeMember[], names: Name[], scope: int, values: Value[], top: int, item: Work, ops: Ops,
           target: Target, at: Bases) -> Step {
    held := values[top - 1];
    if (!Single(held, UnionStorage)) {
        return Fail(forest, Field(forest, item.node, "value"), document, "is needs a union value");
    }
    pattern := Field(forest, item.node, "type");
    if (!Is(forest, pattern, "variant_pattern") || Field(forest, item.node, "binding") >= 0) {
        return Fail(forest, pattern, document, "is pattern is not supported yet");
    }
    member := Text(forest, text, Field(forest, pattern, "name"));
    variant := FindVariant(types, held.record, member);
    if (variant < 0) {
        return Fail(forest, pattern, document, format_text("Unknown union variant '{}'", member));
    }
    bindings := Field(forest, pattern, "bindings");
    count: int = 0;
    binding := FirstMember(forest, bindings);
    while (binding >= 0) {
        count += 1;
        binding = NextMember(forest, binding);
    }
    if (count != 0 && count != types[variant].count) {
        return Fail(forest, pattern, document, "A union payload pattern must bind every field");
    }
    negated := Field(forest, item.node, "negated") >= 0;
    if (count != 0 && (negated || !BindingCondition(forest, text, item.node))) {
        return Fail(forest, FirstMember(forest, bindings), document,
                    "Pattern bindings require a matching if, while or switch arm");
    }
    return MatchStep(forest, text, document, types, members, names, scope, -1, held.slot, variant, bindings, false,
                     negated, -1, -1, ops, target, at, forest[item.node]);
}
package package_compiler

import snapshot "project:source_snapshot"
import strings "core:strings"

// Maps `[K: V]`, lowered to stage zero's map intrinsics: a map is a pointer
// whose header names its collection type, types[record], a MapDecl. These
// steps live in a file of their own: slicing a document's text costs time in
// proportion to its length, so compiling a large file grows quadratically.

MapMakeIntrinsic: int : 30;
MapGetIntrinsic: int : 31;
MapHasIntrinsic: int : 32;
MapItemIntrinsic: int : 34;
MapStoreIntrinsic: int : 36;
MapDeleteIntrinsic: int : 37;

// A header-only cell of a map's, its key's or its value's type.
MapCell :: (map: int) -> Cell {
    return {storage: UnionStorage, container: MapContainer, record: map, constant: 0, variant: -1, kind: ValueKind};
}
KeyCell :: (types: TypeDecl[], map: int) -> Cell {
    return {storage: types[map].key, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
}
ItemCell :: (types: TypeDecl[], map: int) -> Cell {
    return {storage: types[map].value_storage, container: 0, record: types[map].value_record, constant: 0,
            variant: -1, kind: ValueKind};
}
// A cell of a value's type that a map call writes.
PartCell :: (value: Value) -> Cell {
    record: int = -1;
    if (value.storage == StructStorage) {
        record = value.record;
    }
    return {storage: value.storage, container: 0, record: record, constant: 0, variant: -1, kind: ValueKind};
}
// Whether a value is a map.
IsMap :: (value: Value) -> bool {
    return value.container == MapContainer;
}
// A map literal `[k: v, ...]` or `[:]` of the map type its context expects:
// phase 0 schedules each key and value; phase 1 makes the map from the map's,
// key's and value's headers and then each pair, as stage zero does.
MapLiteralStep :: (forest: snapshot.SnapshotNode[], document: int, types: TypeDecl[], values: Value[], top: int,
                   item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    code: Code[] = [];
    slots: Slot[] = [];
    cells: Cell[] = [];
    roots: Root[] = [];
    next: Work[] = [];
    if (item.container != MapContainer) {
        return Fail(forest, item.node, document, "map literal needs a [K: V] type");
    }
    map := item.record;
    if (item.phase == 0) {
        count: int = 0;
        for (pair in Members(forest, item.node)) {
            next.append(Expect(Field(forest, pair, "key"), types[map].key, 0, -1));
            next.append(Expect(Field(forest, pair, "value"), types[map].value_storage, 0,
                               types[map].value_record));
            count += 2;
        }
        rest := Expect(item.node, item.storage, item.container, map);
        rest.phase = 1;
        rest.a = count;
        next.append(rest);
        return Step.Emitted(code, slots, [], cells, [], roots, [], [], next, 0, NoValue(), NoValue(), []);
    }
    cells = [MapCell(map), KeyCell(types, map), ItemCell(types, map)];
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    index: int = 0;
    for (pair in Members(forest, item.node)) {
        key := values[top - item.a + index];
        value := values[top - item.a + index + 1];
        if (!SameType(types[map].key, 0, -1, key)) {
            return Fail(forest, Field(forest, pair, "key"), document, "Map key type does not match");
        }
        if (!SameType(types[map].value_storage, 0, types[map].value_record, value)) {
            return Fail(forest, Field(forest, pair, "value"), document, "map value differs from the map's type");
        }
        for (part in [key, value]) {
            cells.append(PartCell(part));
            slots.append(address);
            code.extend(CellWrite(SlotStorage(part.storage, 0, target), part.slot, at.cell + length(cells) - 1,
                                  ops, target, at.slot + length(slots) - 1, forest[pair]));
        }
        index += 2;
    }
    cells.append(MapCell(map));
    host: Host = {intrinsic: MapMakeIntrinsic, linked: -1, first: at.cell, result_first: at.cell + length(cells) - 1,
                  result_count: 1, written: false};
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    slots.extend([address, address]);
    made := at.slot + length(slots) - 1;
    code.extend(CellRead(target.pointer_storage, at.cell + length(cells) - 1, ops, target, made - 1, node));
    root: Root = {slot: made, storage: UnionStorage, container: MapContainer, record: map};
    roots.append(root);
    return Step.Emitted(code, slots, [], cells, [host], roots, [], [], next, item.a,
                        Typed(made, UnionStorage, MapContainer, map), NoValue(), []);
}
// The phase of an index whose object is ready, which picks its type.
KeyPhase: int : 2;
// Whether a map's value type has a zero that a missing key reads, as stage
// zero's has: a number, bool or string. A record without field defaults
// has none, so reading its missing key fails.
HasZero :: (storage: int) -> bool {
    return storage != StructStorage && storage != UnionStorage;
}
// `m[k]`: stage zero's map get, which reads the value type's zero for a
// missing key when it has one, an expression of its own at the index.
MapReadStep :: (forest: snapshot.SnapshotNode[], document: int, types: TypeDecl[], map: Value, key: Value,
                ops: Ops, target: Target, at: Bases, index: int) -> Step {
    node := forest[index];
    declared := types[map.record];
    if (!SameType(declared.key, 0, -1, key)) {
        return Fail(forest, Field(forest, index, "index"), document, "Map key type does not match");
    }
    item: ValueType = {storage: declared.value_storage, container: 0, record: declared.value_record};
    cells: Cell[] = [MapCell(map.record), KeyCell(types, map.record)];
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    slots: Slot[] = [address, address];
    code := extend(CellWrite(target.pointer_storage, map.slot, at.cell, ops, target, at.slot, node),
                   CellWrite(SlotStorage(key.storage, 0, target), key.slot, at.cell + 1, ops, target, at.slot + 1, node));
    if (HasZero(item.storage)) {
        code.append(ExpressionCode(ops, node));
        slots.append(ValueLocal(item.storage));
        code.append(ConstantCode(ops, item.storage, 0, at.slot + 2, node));
        code.append(WatchCode(ops, at.slot + 2, item.storage, 0, -1, 0, true, node, target));
        cells.append(ItemCell(types, map.record));
        slots.append(address);
        code.extend(CellWrite(item.storage, at.slot + 2, at.cell + 2, ops, target, at.slot + 3, node));
    }
    cells.append(ItemCell(types, map.record));
    host: Host = {intrinsic: MapGetIntrinsic, linked: -1, first: at.cell, result_first: at.cell + length(cells) - 1,
                  result_count: 1, written: false};
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    read := length(slots);
    slots.append(address);
    result: Slot = {storage: SlotStorage(item.storage, 0, target), kind: SlotKind(item.storage, 0)};
    slots.append(result);
    code.extend(CellRead(SlotStorage(item.storage, 0, target), at.cell + length(cells) - 1, ops, target,
                         at.slot + read, node));
    roots: Root[] = [];
    if (Pointer(item.storage, 0)) {
        root: Root = {slot: at.slot + read + 1, storage: item.storage, container: 0, record: item.record};
        roots.append(root);
    }
    return Step.Emitted(code, slots, [], cells, [host], roots, [], [], [], 2,
                        Typed(at.slot + read + 1, item.storage, 0, item.record), NoValue(), []);
}
// Statement phases of a local map's in-place store and removal.
MapStorePhase: int : 11;
MapDeletePhase: int : 12;
// The `c` of a map method's later work, which tells it from a call's.
MapHasMark: int : -1;
// Whether a binary operator is `not in`, the only one longer than three bytes.
NotIn :: (forest: snapshot.SnapshotNode[], node: int, operator: string) -> bool {
    return strings.ByteLength(operator) > 3 && Is(forest, Field(forest, node, "operator"), "not_in");
}
// Whether `node` calls the map method `name`, such as `m.has(k)`: a member
// of a value, not of a package, as stage zero tells them apart. Every call
// asks, so the member's length is checked before its text is read.
MapMethod :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], node: int, name: string) -> bool {
    if (!Is(forest, node, "call_expression")) {
        return false;
    }
    function := Field(forest, node, "function");
    member := Field(forest, function, "member");
    if (!Is(forest, function, "member_expression") ||
        forest[member].end - forest[member].start != strings.ByteLength(name) ||
        Text(forest, text, member) != name) {
        return false;
    }
    root := Field(forest, function, "object");
    while (Is(forest, root, "member_expression") || Is(forest, root, "index_expression")) {
        root = Field(forest, root, "object");
    }
    if (!Is(forest, root, "identifier")) {
        return true;
    }
    found := Lookup(names, Text(forest, text, root));
    return found >= 0 && names[found].place != AliasPlace;
}
// The local map `node` names, which a store or removal updates in place, as
// stage zero updates an owned local; -1 for any other.
LocalMap :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], node: int) -> int {
    if (!Is(forest, node, "identifier")) {
        return -1;
    }
    found := Lookup(names, Text(forest, text, node));
    if (found < 0 || names[found].place != CellPlace || names[found].container != MapContainer ||
        !names[found].writable || Parameter(forest, names[found])) {
        return -1;
    }
    return found;
}
// `m[k] = v` on a local map: the statement's check, the target's point, then
// the key and the value. A step of its own takes no code of the statement's,
// which would make the statement copy its code on every append.
MapStoreStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], names: Name[],
                 found: int, item: Work, ops: Ops, node: snapshot.SnapshotNode) -> Step {
    destination := Field(forest, item.node, "target");
    if (Text(forest, text, Field(forest, item.node, "operator")) != "=") {
        return Fail(forest, item.node, document, "compound map assignment is not supported yet");
    }
    if (LocalMap(forest, text, names, Field(forest, destination, "object")) < 0) {
        return Fail(forest, destination, document, "map assignment needs a local map");
    }
    map := types[names[found].record];
    next: Work[] = [Expect(Field(forest, destination, "index"), map.key, 0, -1),
                    Expect(Field(forest, item.node, "value"), map.value_storage, 0, map.value_record),
                    Resume(item.node, MapStorePhase, found, 0)];
    code: Code[] = [Instruction(ops.check, 0, 0, 0, 0, 0, node), ExpressionCode(ops, forest[destination])];
    return Step.Emitted(code, [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
}
// `delete m[k]` and `m.delete(k)` on a local map, which stage zero lowers as
// an assignment of the map without the key: the statement's check, the
// map's point, the removal's, then the key.
MapDeleteStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], names: Name[],
                  item: Work, ops: Ops, node: snapshot.SnapshotNode) -> Step {
    removal := item.node;
    object: int = -1;
    key: int = -1;
    if (node.kind == "delete_statement") {
        object = Field(forest, Field(forest, item.node, "target"), "object");
        key = Field(forest, Field(forest, item.node, "target"), "index");
    } else {
        removal = FirstMember(forest, item.node);
        arguments := Members(forest, Field(forest, removal, "arguments"));
        if (length(arguments) != 1) {
            return Fail(forest, removal, document, "Map method requires one key");
        }
        object = Field(forest, Field(forest, removal, "function"), "object");
        key = arguments[0];
    }
    found := LocalMap(forest, text, names, object);
    if (found < 0) {
        return Fail(forest, object, document, "deleting a key needs a local map");
    }
    code: Code[] = [Instruction(ops.check, 0, 0, 0, 0, 0, node), ExpressionCode(ops, forest[object]),
                    ExpressionCode(ops, forest[removal])];
    resume := Resume(item.node, MapDeletePhase, found, object);
    resume.c = removal;
    next: Work[] = [Expect(key, types[names[found].record].key, 0, -1), resume];
    return Step.Emitted(code, [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
}
// The in-place store or removal on the local map names[item.a]: the local's
// header address, the key and a store's value go to the intrinsic, which
// returns a bool. A removal then evaluates the map again, as stage zero does
// to watch it.
MapUpdateStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], names: Name[],
                  values: Value[], top: int, item: Work, ops: Ops, target: Target, at: Bases,
                  node: snapshot.SnapshotNode) -> Step {
    binding := names[item.a];
    map := types[binding.record];
    store := item.phase == MapStorePhase;
    arguments: Value[] = [values[top - 1]];
    if (store) {
        arguments = [values[top - 2], values[top - 1]];
        if (!SameType(map.value_storage, 0, map.value_record, values[top - 1])) {
            return Fail(forest, item.node, document, "map value differs from the map's type");
        }
    }
    if (!SameType(map.key, 0, -1, arguments[0])) {
        return Fail(forest, item.node, document, "Map key type does not match");
    }
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    address_cell: Cell = {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1,
                          kind: AddressKind};
    cells: Cell[] = [address_cell];
    slots: Slot[] = [address, address];
    code: Code[] = [Instruction(ops.host_slot, target.pointer_storage, at.slot, binding.index, 0, 0, node)];
    code.extend(CellWrite(target.pointer_storage, at.slot, at.cell, ops, target, at.slot + 1, node));
    for (argument in arguments) {
        cells.append(PartCell(argument));
        slots.append(address);
        code.extend(CellWrite(SlotStorage(argument.storage, 0, target), argument.slot,
                              at.cell + length(cells) - 1, ops, target, at.slot + length(slots) - 1, node));
    }
    done: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    cells.append(done);
    intrinsic := MapDeleteIntrinsic;
    if (store) {
        intrinsic = MapStoreIntrinsic;
    }
    host: Host = {intrinsic: intrinsic, linked: -1, first: at.cell, result_first: at.cell + length(cells) - 1,
                  result_count: 1, written: false};
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.append(SymbolCode(ops, binding.node, node));
    if (!store) {
        code.extend(NamePoints(forest, text, names, ops, item.b));
    }
    // The map a removal leaves is its watched output.
    if (!store && ops.debug) {
        slots.append(address);
        reread := Instruction(ops.load, target.pointer_storage, at.slot + length(slots) - 1, at.slot, 0, 0, node);
        reread.offset = target.payload_offset;
        code.append(reread);
        code.append(WatchCode(ops, at.slot + length(slots) - 1, UnionStorage, MapContainer, binding.record,
                              0, true, forest[item.c], target));
    }
    return Step.Emitted(code, slots, [], cells, [host], [], [], [], [], length(arguments), NoValue(), NoValue(), []);
}
// `k in m`, `k not in m` and `m.has(k)`: the map, then the key, to stage
// zero's map has. `not in` negates it, an expression of its own at the same
// range.
MapHasStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], values: Value[],
               top: int, item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    negated := Is(forest, Field(forest, item.node, "operator"), "not_in");
    map := Field(forest, item.node, "right");
    key := Field(forest, item.node, "left");
    if (node.kind == "call_expression") {
        map = Field(forest, Field(forest, item.node, "function"), "object");
        arguments := Members(forest, Field(forest, item.node, "arguments"));
        if (length(arguments) != 1) {
            return Fail(forest, item.node, document, "Map method requires one key");
        }
        key = arguments[0];
    }
    if (item.phase == 0) {
        code: Code[] = [];
        if (negated) {
            code.append(ExpressionCode(ops, node));
        }
        resume := Resume(item.node, KeyPhase, 0, 0);
        resume.c = MapHasMark;
        return Step.Emitted(code, [], [], [], [], [], [], [], [Visit(map), resume], 0, NoValue(), NoValue(), []);
    }
    if (item.phase == KeyPhase) {
        if (!IsMap(values[top - 1])) {
            return Fail(forest, map, document, "Map operation requires a map");
        }
        resume := Resume(item.node, 1, 0, 0);
        resume.c = MapHasMark;
        next: Work[] = [Expect(key, types[values[top - 1].record].key, 0, -1), resume];
        return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
    }
    held := values[top - 2];
    sought := values[top - 1];
    if (!SameType(types[held.record].key, 0, -1, sought)) {
        return Fail(forest, key, document, "Map key type does not match");
    }
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    result: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    cells: Cell[] = [MapCell(held.record), PartCell(sought), result];
    slots: Slot[] = [address, address, address, flag];
    code := extend(CellWrite(target.pointer_storage, held.slot, at.cell, ops, target, at.slot, node),
                   CellWrite(SlotStorage(sought.storage, 0, target), sought.slot, at.cell + 1, ops, target,
                             at.slot + 1, node));
    host: Host = {intrinsic: MapHasIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 2, result_count: 1,
                  written: false};
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.extend(CellRead(BoolStorage, at.cell + 2, ops, target, at.slot + 2, node));
    answer := at.slot + 3;
    if (negated) {
        // `not in` is a negation of the has, an expression of its own.
        code.append(ScalarWatch(ops, answer, BoolStorage, 0, true, node));
        // Not is equality with false.
        slots.append(flag);
        code.append(ConstantCode(ops, BoolStorage, 0, at.slot + 4, node));
        slots.append(flag);
        code.append(Instruction(ops.eq, BoolStorage, at.slot + 5, answer, at.slot + 4, -1, node));
        answer = at.slot + 5;
    }
    return Step.Emitted(code, slots, [], cells, [host], [], [], [], [], 2, Typed(answer, BoolStorage, 0, -1),
                        NoValue(), []);
}
// One entry of a map by its insertion ordinal: its value, or its key when
// `key`, from stage zero's map item intrinsic, whose cells start at `cell`.
MapItemCode :: (types: TypeDecl[], map: int, held: int, ordinal: int, key: bool, cell: int, host: int, slot: int,
                ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    code := extend(CellWrite(target.pointer_storage, held, cell, ops, target, slot, node),
                   CellWrite(IntStorage, ordinal, cell + 1, ops, target, slot + 1, node));
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, host, node));
    storage := types[map].key;
    if (!key) {
        storage = SlotStorage(types[map].value_storage, 0, target);
    }
    return extend(code, CellRead(storage, cell + 3, ops, target, slot + 2, node));
}
MapItemCells :: (types: TypeDecl[], map: int, key: bool) -> Cell[] {
    flag: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    result := ItemCell(types, map);
    if (key) {
        flag.constant = 1;
        result = KeyCell(types, map);
    }
    ordinal: Cell = {storage: IntStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    return [MapCell(map), ordinal, flag, result];
}
// A loop over the map, or its copy, in the last cell, as stage zero emits it:
// its ordinal from 0 up to the map's count, then the entry's value, saved in a
// local or copied into a cell of its own for a record, and, when the loop
// names it, its key, saved in a local. It binds the value's `name` and the
// key's `key`, then schedules the body; its marks are the head and the exit
// jump, and the ordinal is its first local.
MapForStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], held: Value,
               item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    if (Field(forest, item.node, "reverse") >= 0) {
        return Fail(forest, item.node, document, "for < reverses only ranges and arrays");
    }
    map := types[held.record];
    number: Slot = {storage: IntStorage, kind: ValueKind};
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    slots: Slot[] = [number];
    code: Code[] = [ConstantCode(ops, IntStorage, 0, at.slot, node)];
    locals: Slot[] = [ValueLocal(IntStorage)];
    code.append(Instruction(ops.save, IntStorage, 0, at.slot, 0, at.local, node));
    b := at.slot + 1;
    head := at.pc + length(code);
    code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
    slots.extend([address, address, number, number, flag]);
    code.append(Instruction(ops.host_slot, target.pointer_storage, b, at.cell - 1, 0, 0, node));
    load := Instruction(ops.load, target.pointer_storage, b + 1, b, 0, 0, node);
    load.offset = target.payload_offset;
    code.append(load);
    root: Root = {slot: b + 1, storage: UnionStorage, container: MapContainer, record: held.record};
    roots: Root[] = [root];
    count := Instruction(ops.load, IntStorage, b + 2, b + 1, 0, 0, node);
    count.offset = target.map_count_offset;
    code.append(count);
    code.append(Instruction(ops.local, IntStorage, b + 3, at.local, 0, 0, node));
    code.append(Instruction(ops.lt, IntStorage, b + 4, b + 3, b + 2, -1, node));
    code.append(Instruction(ops.branch_if, 0, 0, b + 4, 0, at.pc + length(code) + 2, node));
    leave := at.pc + length(code);
    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
    cells := MapItemCells(types, held.record, false);
    hosts: Host[] = [{intrinsic: MapItemIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 3,
                      result_count: 1, written: false}];
    value := at.slot + length(slots) + 3;
    slots.extend([address, address, address,
                  {storage: SlotStorage(map.value_storage, 0, target), kind: SlotKind(map.value_storage, 0)}]);
    code.extend(MapItemCode(types, held.record, b + 1, b + 3, false, at.cell, at.host, value - 3, ops, target,
                            node));
    value_node := Field(forest, item.node, "name");
    binding: Name = {name: Text(forest, text, value_node), place: LocalPlace, index: at.local + 1,
                     storage: map.value_storage, container: 0, record: map.value_record, writable: false,
                     node: value_node};
    if (map.value_storage == StructStorage) {
        // The record is copied into a cell of its own, as a record element is.
        copy: Cell = {storage: StructStorage, container: 0, record: map.value_record, constant: 0, variant: -1,
                      kind: ValueKind};
        cells.extend([copy, copy]);
        slots.append(address);
        code.extend(CellWrite(target.pointer_storage, value, at.cell + 4, ops, target, at.slot + length(slots) - 1,
                              node));
        snapshot: Host = {intrinsic: SnapshotIntrinsic, linked: -1, first: at.cell + 4, result_first: at.cell + 5,
                          result_count: 1, written: false};
        hosts.append(snapshot);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host + 1, node));
        binding.place = CellPlace;
        binding.index = at.cell + 5;
    } else {
        locals.append(ValueLocal(map.value_storage));
        code.append(Instruction(ops.save, map.value_storage, 0, value, 0, at.local + 1, node));
    }
    bound: Name[] = [binding];
    code.append(SymbolCode(ops, value_node, node));
    key_node := Field(forest, item.node, "key");
    if (key_node >= 0 && Text(forest, text, key_node) == binding.name) {
        return Fail(forest, value_node, document, format_text("Duplicate declaration '{}'", binding.name));
    }
    if (key_node >= 0) {
        first := at.cell + length(cells);
        cells.extend(MapItemCells(types, held.record, true));
        key_host: Host = {intrinsic: MapItemIntrinsic, linked: -1, first: first, result_first: first + 3,
                          result_count: 1, written: false};
        hosts.append(key_host);
        slots.extend([address, address, address, ValueLocal(map.key)]);
        code.extend(MapItemCode(types, held.record, b + 1, b + 3, true, first, at.host + length(hosts) - 1,
                                at.slot + length(slots) - 4, ops, target, node));
        key: Name = {name: Text(forest, text, key_node), place: LocalPlace, index: at.local + length(locals),
                     storage: map.key, container: 0, record: -1, writable: false, node: key_node};
        locals.append(ValueLocal(map.key));
        code.append(Instruction(ops.save, map.key, 0, at.slot + length(slots) - 1, 0, key.index, node));
        bound.append(key);
        code.append(SymbolCode(ops, key_node, node));
    }
    next: Work[] = [Visit(Field(forest, item.node, "body")), Resume(item.node, 4, 0, 0)];
    return Step.Emitted(code, slots, locals, cells, hosts, roots, [], bound, next, 0, NoValue(), NoValue(),
                        [head, leave]);
}
package package_compiler

import snapshot "project:source_snapshot"

// `ref` parameters, lowered to stage zero's reference intrinsics. A ref
// parameter's argument is a descriptor of the caller's value: a value
// reference to a local's data cell, a field reference into a local record,
// or the caller's own ref parameter, passed on. The callee reads and writes
// the value through it.

// A ref parameter; the name's index is the argument holding its descriptor.
ReferencePlace: int : 8;
// A number, bool or string local or parameter that a ref argument reaches,
// kept in a data cell, as stage zero keeps every local, so a reference can
// point at it; the name's index is the cell.
BoxPlace: int : 9;
// The value of a ref argument: a descriptor in a pointer slot.
ReferenceStorage: int : -6;
// The phase of a ref argument, which makes its descriptor; its work carries
// the parameter's type.
ReferencePhase: int : 14;

// Whether any function of `params` takes a ref parameter.
AnyReference :: (params: Param[]) -> bool {
    for (param in params) {
        if (param.reference) {
            return true;
        }
    }
    return false;
}
// The function a call names, of this package or an import, -1 for any other.
CalledFunction :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], aliases: Name[],
                   package: int, call: int) -> int {
    callee := Field(forest, call, "function");
    qualifier: int = -1;
    if (Is(forest, callee, "member_expression")) {
        qualifier = Field(forest, callee, "object");
        callee = Field(forest, callee, "member");
    }
    home := QualifierOf(forest, text, aliases, package, qualifier);
    if (home < 0 || !Is(forest, callee, "identifier")) {
        return -1;
    }
    return FindCallable(callables, home, Text(forest, text, callee));
}
// The name a ref argument reaches through its fields, or "" for a value no
// reference can reach.
ArgumentRoot :: (forest: snapshot.SnapshotNode[], text: string, argument: int) -> string {
    root := argument;
    while (Is(forest, root, "member_expression")) {
        root = Field(forest, root, "object");
    }
    if (!Is(forest, root, "identifier")) {
        return "";
    }
    return Text(forest, text, root);
}
// The names the body `node` passes to ref parameters, which then live in data
// cells. Shadowing is ignored: boxing a value nothing references costs only
// its speed.
ReferencedNames :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                    aliases: Name[], package: int, node: int) -> string[] {
    found: string[] = [];
    pending: int[] = [node];
    top: int = 1;
    while (top > 0) {
        top -= 1;
        at := pending[top];
        if (Is(forest, at, "call_expression")) {
            called := CalledFunction(forest, text, callables, aliases, package, at);
            index: int = 0;
            for (argument in Members(forest, Field(forest, at, "arguments"))) {
                if (called >= 0 && index < callables[called].count && params[callables[called].first + index].reference) {
                    found.append(ArgumentRoot(forest, text, argument));
                }
                index += 1;
            }
        }
        child := forest[at].first_child;
        while (child >= 0) {
            if (top < length(pending)) {
                pending[top] = child;
            } else {
                pending.append(child);
            }
            top += 1;
            child = forest[child].next_sibling;
        }
    }
    return found;
}
// Whether `names` holds `name`.
Holds :: (names: string[], name: string) -> bool {
    for (each in names) {
        if (each == name) {
            return true;
        }
    }
    return false;
}
// A ref parameter's descriptor, the argument `index`, into slot `slot`.
DescriptorCode :: (ops: Ops, target: Target, index: int, slot: int, node: snapshot.SnapshotNode) -> Code {
    read := Instruction(ops.argument, target.pointer_storage, slot, index, 0, 0, node);
    read.value_storage = target.pointer_storage;
    return read;
}
DescriptorSlot :: (target: Target) -> Slot {
    return {storage: target.pointer_storage, kind: ReferenceKind};
}
// A cell holding a value of the type storage, container and record give.
TypedCell :: (storage: int, container: int, record: int) -> Cell {
    return {storage: storage, container: container, record: record, constant: 0, variant: -1, kind: ValueKind};
}
// The read of the value of `type` that the descriptor in slot `descriptor`
// reaches, through cells from `cell` and slots from `slot`, by host `host`;
// the value lands in slot + 2.
ReadThroughCode :: (ops: Ops, target: Target, storage: int, container: int, descriptor: int, cell: int, host: int,
                    slot: int, node: snapshot.SnapshotNode) -> Code[] {
    code := CellWrite(target.pointer_storage, descriptor, cell, ops, target, slot, node);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, host, node));
    return extend(code, CellRead(SlotStorage(storage, container, target), cell + 1, ops, target, slot + 1, node));
}
ReadThroughSlots :: (storage: int, container: int, target: Target) -> Slot[] {
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    value: Slot = {storage: SlotStorage(storage, container, target), kind: SlotKind(storage, container)};
    return [address, address, value];
}
ReadThroughHost :: (cell: int) -> Host {
    return {intrinsic: ReferenceReadIntrinsic, linked: -1, first: cell, result_first: cell + 1, result_count: 1,
            written: false};
}
// The write of the value in slot `value` through the descriptor in slot
// `descriptor`, through cells from `cell` and two slots from `slot`.
WriteThroughCode :: (ops: Ops, target: Target, storage: int, container: int, descriptor: int, value: int, cell: int,
                     host: int, slot: int, node: snapshot.SnapshotNode) -> Code[] {
    code := CellWrite(target.pointer_storage, descriptor, cell, ops, target, slot, node);
    code.extend(CellWrite(SlotStorage(storage, container, target), value, cell + 1, ops, target, slot + 1,
                          node));
    return append(code, Instruction(ops.host_call, 0, 0, target.data_failure, 0, host, node));
}
WriteThroughCells :: (storage: int, container: int, record: int, target: Target) -> Cell[] {
    done: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    return [ReferenceCell(target), TypedCell(storage, container, record), done];
}
WriteThroughHost :: (cell: int) -> Host {
    return {intrinsic: ReferenceWriteIntrinsic, linked: -1, first: cell, result_first: cell + 2, result_count: 1,
            written: false};
}
// A read of `binding`, a ref parameter, through its descriptor, or a boxed
// value, from its cell.
PlaceReadStep :: (binding: Name, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    roots: Root[] = [];
    if (binding.place == BoxPlace) {
        address: Slot = {storage: target.pointer_storage, kind: AddressKind};
        slots: Slot[] = [address, ValueLocal(binding.storage)];
        return Step.Emitted(CellRead(binding.storage, binding.index, ops, target, at.slot, node), slots, [], [], [],
                            roots, [], [], [], 0, Typed(at.slot + 1, binding.storage, 0, -1), NoValue(), []);
    }
    slots: Slot[] = [DescriptorSlot(target)];
    code: Code[] = [DescriptorCode(ops, target, binding.index, at.slot, node)];
    slots.extend(ReadThroughSlots(binding.storage, binding.container, target));
    code.extend(ReadThroughCode(ops, target, binding.storage, binding.container, at.slot, at.cell, at.host,
                                at.slot + 1, node));
    cells: Cell[] = [ReferenceCell(target), TypedCell(binding.storage, binding.container, binding.record)];
    value := at.slot + 3;
    if (Pointer(binding.storage, binding.container)) {
        root: Root = {slot: value, storage: binding.storage, container: binding.container, record: binding.record};
        roots.append(root);
    }
    return Step.Emitted(code, slots, [], cells, [ReadThroughHost(at.cell)], roots, [], [], [], 0,
                        Typed(value, binding.storage, binding.container, binding.record), NoValue(), []);
}
// `x: T = v` for a number, bool or string local that a ref argument reaches:
// its cell holds the value.
BoxStep :: (forest: snapshot.SnapshotNode[], text: string, local: Value, value: Value, item: Work, ops: Ops,
            target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    name := Field(forest, item.node, "name");
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    code := CellWrite(local.storage, value.slot, at.cell, ops, target, at.slot, node);
    code.append(SymbolCode(ops, name, node));
    binding: Name = {name: Text(forest, text, name), place: BoxPlace, index: at.cell, storage: local.storage,
                     container: 0, record: local.record, writable: true, node: name};
    return Step.Emitted(code, [address], [], [TypedCell(local.storage, 0, -1)], [], [], [], [binding], [], 1,
                        NoValue(), NoValue(), []);
}
// A number, bool or string parameter that a ref argument reaches moves into
// a cell of its own before the body runs, as stage zero isolates it.
BoxParameterStep :: (param: Param, index: int, ops: Ops, target: Target, at: Bases,
                     node: snapshot.SnapshotNode) -> Step {
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    read := Instruction(ops.argument, param.storage, at.slot, index, 0, 0, node);
    read.value_storage = param.storage;
    code: Code[] = [read];
    code.extend(CellWrite(param.storage, at.slot, at.cell, ops, target, at.slot + 1, node));
    binding: Name = {name: param.name, place: BoxPlace, index: at.cell, storage: param.storage, container: 0,
                     record: param.record, writable: true, node: param.node};
    return Step.Emitted(code, [ValueLocal(param.storage), address], [], [TypedCell(param.storage, 0, -1)], [], [], [],
                        [binding], [], 0, NoValue(), NoValue(), []);
}
// `x = v` and `x op= v` on a ref parameter or a boxed local, as stage zero
// assigns them: a narrower integer widens first; a compound reads the target
// and watches it, then combines; the store writes through the reference or
// into the cell. A boxed local is stored as any local, with its symbol's
// point; a ref parameter's target is the caller's.
PlaceAssignStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, binding: Name, value: Value,
                    item: Work, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    destination := forest[Field(forest, item.node, "target")];
    slots: Slot[] = [];
    code: Code[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    stored := value;
    if (binding.container == 0 && value.container == 0 && Widens(value.storage, binding.storage)) {
        slots.append(ValueLocal(binding.storage));
        code.append(CastCode(ops, binding.storage, at.slot, value.slot, 0, node));
        stored = Typed(at.slot, binding.storage, 0, -1);
    }
    reference := binding.place == ReferencePlace;
    descriptor: int = -1;
    if (reference) {
        descriptor = at.slot + length(slots);
        slots.append(DescriptorSlot(target));
        code.append(DescriptorCode(ops, target, binding.index, descriptor, node));
    }
    operator := CompoundOperator(Text(forest, text, Field(forest, item.node, "operator")));
    if (operator != "") {
        op := BinaryOp(ops, operator);
        if (op < 0 || Comparison(ops, op) || !Numeric(binding.storage) || binding.container != 0 ||
            !Single(stored, binding.storage)) {
            return Fail(forest, item.node, document, "compound assignment needs number operands of its type");
        }
        if (!Computes(ops, op, binding.storage)) {
            return Fail(forest, item.node, document, "unsupported arithmetic type");
        }
        current := at.slot + length(slots) + 2;
        if (reference) {
            slots.extend(ReadThroughSlots(binding.storage, 0, target));
            code.extend(ReadThroughCode(ops, target, binding.storage, 0, descriptor, at.cell, at.host,
                                        current - 2, node));
            cells = [ReferenceCell(target), TypedCell(binding.storage, 0, -1)];
            hosts = [ReadThroughHost(at.cell)];
        } else {
            current = at.slot + length(slots) + 1;
            slots.extend(PlaceSlots(binding, target));
            code.extend(CellRead(binding.storage, binding.index, ops, target, current - 1, node));
        }
        code.append(ScalarWatch(ops, current, binding.storage, 0, true, destination));
        slots.append(ValueLocal(binding.storage));
        code.append(Instruction(op, binding.storage, current + 1, current, stored.slot, -1, node));
        // A local's target is watched again as the value it stores; stage zero
        // reads a ref parameter's target once.
        if (!reference) {
            code.append(ScalarWatch(ops, current + 1, binding.storage, 0, true, destination));
        }
        stored = Typed(current + 1, binding.storage, 0, -1);
    }
    if (!SameType(binding.storage, binding.container, binding.record, stored)) {
        return Fail(forest, item.node, document, "assigned value differs from its local");
    }
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    if (reference) {
        first := at.cell + length(cells);
        cells.extend(WriteThroughCells(binding.storage, binding.container, binding.record, target));
        hosts.append(WriteThroughHost(first));
        code.extend(WriteThroughCode(ops, target, binding.storage, binding.container, descriptor, stored.slot,
                                     first, at.host + length(hosts) - 1, at.slot + length(slots), node));
        slots.extend([address, address]);
    } else {
        code.extend(CellWrite(binding.storage, stored.slot, binding.index, ops, target, at.slot + length(slots),
                              node));
        slots.append(address);
    }
    if (!Parameter(forest, binding)) {
        code.append(SymbolCode(ops, binding.node, node));
    }
    return Step.Emitted(code, slots, [], cells, hosts, [], [], [], [], 1, NoValue(), NoValue(), []);
}
PlaceSlots :: (binding: Name, target: Target) -> Slot[] {
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    return [address, ValueLocal(binding.storage)];
}
// A value reference to the local whose cell is `cell`, of the type storage,
// container and record give: the make's context, type and kind, its unused
// state variable, the cell's address, then unused component facts.
MakeValueCells :: (target: Target, storage: int, container: int, record: int) -> Cell[] {
    facts: uint64[] = [0, 0, 0, 0xFFFFFFFFFFFFFFFF, 0, 0, 0, 0, 0];
    cells := MakeCells(target, -1, facts);
    cells[1] = TypedCell(storage, container, record);
    return cells;
}
// The make of a value reference to the cell `cell`, through cells from
// `first`, with the six slots from `slot`; the descriptor lands in slot + 5.
MakeValueCode :: (ops: Ops, target: Target, cell: int, first: int, host: int, slot: int,
                  node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [Instruction(ops.context, target.pointer_storage, slot, 0, 0, 1, node),
                    Instruction(ops.host_slot, target.pointer_storage, slot + 1, cell, 0, 0, node)];
    code.extend(CellWrite(target.pointer_storage, slot, first, ops, target, slot + 2, node));
    code.extend(CellWrite(target.pointer_storage, slot + 1, first + 4, ops, target, slot + 3, node));
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, host, node));
    return extend(code, CellRead(target.pointer_storage, first + 9, ops, target, slot + 4, node));
}
MakeValueSlots :: (target: Target) -> Slot[] {
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    return [address, address, address, address, address, DescriptorSlot(target)];
}
MakeValueHost :: (first: int) -> Host {
    return {intrinsic: ReferenceMakeIntrinsic, linked: -1, first: first, result_first: first + 9, result_count: 1,
            written: true};
}
// The argument of a ref parameter of the type item.storage, item.container
// and item.record, as stage zero passes it: a value reference to a local's
// cell, a field reference into a local record or through a ref parameter,
// or a ref parameter's own descriptor. The argument's points come first, its
// members outermost, then its name.
ReferenceArgumentStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                          members: TypeMember[], names: Name[], item: Work, ops: Ops, target: Target,
                          at: Bases) -> Step {
    node := forest[item.node];
    code := TargetPoints(forest, text, names, ops, item.node);
    root := item.node;
    field: int = -1;
    if (Is(forest, item.node, "member_expression")) {
        root = Field(forest, item.node, "object");
    }
    found: int = -1;
    if (Is(forest, root, "identifier")) {
        found = Lookup(names, Text(forest, text, root));
    }
    if (found < 0 || !names[found].writable || names[found].place == AliasPlace) {
        return Fail(forest, item.node, document, "Reference argument requires a writable value");
    }
    binding := names[found];
    storage := binding.storage;
    container := binding.container;
    record := binding.record;
    if (root != item.node) {
        if (binding.storage != StructStorage || binding.container != 0 ||
            (binding.place != CellPlace && binding.place != ReferencePlace)) {
            return Fail(forest, item.node, document, "a reference to this field is not supported yet");
        }
        field = FindField(types, members, binding.record, Text(forest, text, Field(forest, item.node, "member")));
        if (field < 0) {
            return Fail(forest, item.node, document, "Unknown field");
        }
        storage = members[field].storage;
        container = 0;
        record = -1;
    } else if (binding.place != CellPlace && binding.place != BoxPlace && binding.place != ReferencePlace) {
        return Fail(forest, item.node, document, "a reference to this value is not supported yet");
    }
    if (!SameType(item.storage, item.container, item.record, Typed(-1, storage, container, record))) {
        return Fail(forest, item.node, document, "reference argument differs from the parameter's type");
    }
    slots: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    descriptor: int = -1;
    if (binding.place == ReferencePlace) {
        descriptor = at.slot;
        slots = [DescriptorSlot(target)];
        code.append(DescriptorCode(ops, target, binding.index, descriptor, node));
    } else {
