pub GameEventField :: struct {
    name: string;
    storage: int;
    nominal: uint64;
    has_default: bool;
    default_owner: bool;
}
// A type the game links, a component when `component` is its component ID;
// its fields are type_fields[first, first + count). A module requires every
// type but a namespace, such as SceneGlobals; types[underlying], when that is
// not -1, is the type it stands for.
pub GameType :: struct {
    required: bool;
    underlying: int;
    name: string;
    id: uint64;
    layout: uint64;
    storage: int;
    size: int;
    component: uint64;
    first: int;
    count: int;
}
// A game type's field: of the type types[record] when that is not -1; a
// constant whose value is its name; read by natives[read] when that is not
// -1, with the key `read_key` instead of the value when that is not "".
pub GameField :: struct {
    name: string;
    storage: int;
    offset: int;
    writable: bool;
    c_string: bool;
    record: int;
    constant: bool;
    read: int;
    read_key: string;
}
// A native that makes a record of type types[record] of its arguments;
// argument i gives the record's field make_fields[first + i].
pub NativeMake :: struct {
    native: int;
    record: int;
    first: int;
}
// A name the game binds in every behavior, of the type types[record] when
// that is not -1.
pub GameGlobal :: struct {
    name: string;
    storage: int;
    record: int;
}
// A native that combines numbers, and records of them field by field, for a
// binary operator: natives[native].
pub NumericOperator :: struct {
    native: int;
    operator: string;
}
// A behavior's retained state, with the bits of its initial value.
StateDecl :: struct {
    name: string;
    id: uint64;
    storage: int;
    bits: uint64;
    node: int;
}
// What a module holds beyond its functions. A behavior's functions keep its
// states, and handled[i] is the event function i handles, -1 for none; its
// operators may combine records, and its globals are names.
Game :: union {
    Package
    | Behavior(kept: StateDecl[], handled: int[], declared: GameEvent[], payloads: GameEventField[],
               entity: uint64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
               make_fields: int[])
}
// Prepared function kinds.
HandlerFunction: int : 1;
// The reference kind of a component field, as the reference intrinsics take it.
ComponentReference: int : 2;
// Effects a handler declares.
ReadEffect: int : 1;
WriteEffect: int : 2;
InvocationReadEffect: int : 64;

// A behavior's names: the game's globals, its states, then `self`, its owner,
// whatever global the game names so.
BehaviorNames :: (kept_states: StateDecl[], globals: GameGlobal[]) -> Name[] {
    names: Name[] = [];
    index: int = 0;
    while (index < length(globals)) {
        bound: Name = {name: globals[index].name, place: GlobalPlace, index: index, storage: globals[index].storage,
                       container: 0, record: globals[index].record, writable: false, node: -1};
        names.append(bound);
        index += 1;
    }
    index = 0;
    while (index < length(kept_states)) {
        kept: Name = {name: kept_states[index].name, place: StatePlace, index: index,
                      storage: kept_states[index].storage, container: 0, record: -1, writable: true,
                      node: kept_states[index].node};
        names.append(kept);
        index += 1;
    }
    owner: Name = {name: "self", place: SelfPlace, index: 0, storage: HandleStorage, container: 0, record: -1,
                   writable: false, node: -1};
    return append(names, owner);
}
// The component of each component reference a body makes, or, when
// `written`, of each it writes through.
ComponentsOf :: (cells: Cell[], hosts: Host[], written: bool) -> uint64[] {
    found: uint64[] = [];
    for (host in hosts) {
        if (host.intrinsic == ReferenceMakeIntrinsic && cells[host.first + 2].constant == uint64(ComponentReference) &&
            (host.written || !written)) {
            found.append(cells[host.first + 6].constant);
        }
    }
    return found;
}
// Each of `items` once, in order.
Distinct :: (items: uint64[]) -> uint64[] {
    kept: uint64[] = [];
    for (item in items) {
        seen := false;
        for (known in kept) {
            if (known == item) {
                seen = true;
            }
        }
        if (!seen) {
            kept.append(item);
        }
    }
    return kept;
}
// A handler's effects, as stage zero's analysis gives them: reading a state
// reads what the invocation retains, storing one also reads it and writes,
// reading a component reads, and writing one reads and writes.
Effects :: (ops: Ops, code: Code[], reads_components: bool, writes_components: bool) -> int {
    effects: int = 0;
    if (reads_components) {
        effects = ReadEffect;
    }
    if (writes_components) {
        effects = ReadEffect | WriteEffect;
    }
    for (instruction in code) {
        if (instruction.op == ops.variable) {
            effects = effects | ReadEffect | InvocationReadEffect;
        } else if (instruction.op == ops.store) {
            effects = effects | ReadEffect | InvocationReadEffect | WriteEffect;
        }
    }
    return effects;
}
// The game's types as native declarations of package 0, in order, a
// namespace as one no module requires; their fields are members, and a
// native type's parent is its underlying type.
NativeTypes :: (types: GameType[]) -> TypeDecl[] {
    declared: TypeDecl[] = [];
    for (linked in types) {
        kind := NativeDecl;
        if (!linked.required) {
            kind = NamespaceDecl;
        }
        row: TypeDecl = {name: linked.name, type_name: linked.name, package: 0, node: -1, kind: kind,
                         first: linked.first, count: linked.count, size: linked.size, parent: linked.underlying,
                         storage: linked.storage, id: linked.id, layout: linked.layout, component: linked.component,
                         key: 0, value_storage: 0, value_container: 0, value_record: -1};
        declared.append(row);
    }
    return declared;
}
NativeFields :: (type_fields: GameField[]) -> TypeMember[] {
    fields: TypeMember[] = [];
    for (linked in type_fields) {
        row: TypeMember = {name: linked.name, storage: linked.storage, container: 0, record: linked.record,
                           offset: linked.offset, writable: linked.writable, c_string: linked.c_string, constant: linked.constant,
                           read: linked.read, read_key: linked.read_key};
        fields.append(row);
    }
    return fields;
}
// The event named `name`, matched as the catalog matches names: an exact
// name first, else the one that matches loosely; -1 for none or several.
FindEvent :: (game_events: GameEvent[], name: string) -> int {
    found: int = -1;
    index: int = 0;
    while (index < length(game_events)) {
        if (game_events[index].name == name) {
            return index;
        }
        if (NameMatches(game_events[index].name, name)) {
            if (found != -1) {
                found = -2;
            } else {
                found = index;
            }
        }
        index += 1;
    }
    if (found < 0) {
        return -1;
    }
    return found;
}
// Whether every field of an event's payload is a scalar a handler can take.
ScalarPayload :: (declared: GameEvent, event_fields: GameEventField[]) -> bool {
    at := declared.first;
    while (at < declared.first + declared.count) {
        storage := event_fields[at].storage;
        if (storage == StructStorage || storage == UnionStorage || storage <= 0) {
            return false;
        }
        at += 1;
    }
    return true;
}
// A handler's payload parameters, or why the handler cannot take them.
Payload :: union {
    Failed(diagnostic: syntax.Diagnostic) | Bound(params: Param[])
}
// The handler's parameters, one per payload field in payload order. The
// handler names fields in any order; each it leaves out gets an unnamed
// parameter, as stage zero gives it.
PayloadParams :: (forest: snapshot.SnapshotNode[], source: string, handler: int, event_name: string,
                  declared: GameEvent, event_fields: GameEventField[]) -> Payload {
    listed: int[] = [];
    at: int = 0;
    while (at < declared.count) {
        listed.append(int(-1));
        at += 1;
    }
    parameter := FirstMember(forest, Field(forest, handler, "parameters"));
    while (parameter >= 0) {
        name := Field(forest, parameter, "name");
        spelled := Text(forest, source, name);
        at = 0;
        while (at < declared.count && !NameMatches(event_fields[declared.first + at].name, spelled)) {
            at += 1;
        }
        if (at == declared.count) {
            return Payload.Failed(Diagnose(forest, name, 0,
                                           format_text("{} has no payload field '{}'", event_name, spelled)));
        }
        if (listed[at] >= 0) {
            return Payload.Failed(Diagnose(forest, name, 0, format_text("Payload field '{}' is listed twice",
                                                                        event_fields[declared.first + at].name)));
        }
        listed[at] = name;
        parameter = NextMember(forest, parameter);
    }
    params: Param[] = [];
    at = 0;
    while (at < declared.count) {
        param: Param = {name: "", storage: event_fields[declared.first + at].storage, container: 0, record: -1,
                        has_default: false, default_bits: 0, default_text: "", default_occurrence: 0,
                        reference: false, node: listed[at]};
        if (listed[at] >= 0) {
            param.name = Text(forest, source, listed[at]);
        }
        params.append(param);
        at += 1;
    }
    return Payload.Bound(params);
}
// `identity` names the source as the project does, such as
// "behaviors/Counter.chibi"; the module, states and handlers take their IDs
// from it. The target, natives, events, types, entity, operators, globals and
// record makes are the game's, as `chibi-compile --stage-one-input` exports
// them.
pub CompileBehavior :: (identity: string, source: string, target: Target, abi: uint64, names: string[],
                        natives: Native[], ports: Port[], native_ids: uint64[], game_events: GameEvent[],
                        event_fields: GameEventField[], types: GameType[], type_fields: GameField[],
                        entity: uint64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
                        make_fields: int[]) -> Result {
    ops := ResolveOps(names, true);
    if (abi == 0 || !Complete(ops) || length(native_ids) != 2 * length(natives)) {
        return InputFailure(-1, "unsupported compiler input or target");
    }
    forest: snapshot.SnapshotNode[] = [];
    root: int = -1;
    switch raw.Parse(source) {
        case .Parsed(nodes, fields, is_named, is_extra, top):
            errors := syntax.Diagnose(nodes, top);
            if (length(errors) > 0) {
                return Result.Rejected(snapshot.Stamp(errors[0], 0));
            }
            index: int = 0;
            while (index < length(nodes)) {
                forest.append(snapshot.Node(nodes[index], fields[index], is_named[index], is_extra[index],
                                            0));
                index += 1;
            }
            root = top;
    }
    declaration := FirstMember(forest, root);
    if (!Is(forest, declaration, "behavior") || NextMember(forest, declaration) >= 0) {
        return InputFailure(0, "a behavior asset needs one behavior declaration");
    }
    declared_types := NativeTypes(types);
    members := NativeFields(type_fields);
    no_names: Name[] = [];
    solid := SolidOffsets(source);
    kept_states: StateDecl[] = [];
    callables: Callable[] = [];
    params: Param[] = [];
    handled: int[] = [];
    member := FirstMember(forest, Field(forest, declaration, "body"));
    while (member >= 0) {
        if (Is(forest, member, "state_declaration")) {
            name := Text(forest, source, Field(forest, member, "name"));
            declared := ReadType(forest, source, declared_types, no_names, 0, Field(forest, member, "type"));
            if (!Numeric(declared.storage) || declared.container != 0) {
                return Result.Rejected(Diagnose(forest, member, 0, "state needs a number type"));
            }
            bits: uint64 = 0;
            value := Field(forest, member, "value");
            if (value >= 0 && Floating(declared.storage)) {
                literal := Typed(-1, NumberStorage, 0, value);
                if (!Is(forest, value, "number") && !Is(forest, value, "unary_expression")) {
                    return Result.Rejected(Diagnose(forest, value, 0, "state value must be a number literal"));
                }
                switch FloatConstantStep(forest, source, 0, literal, declared.storage, ops, NoBases(), forest[value]) {
                    case .Failed(diagnostic):
                        return Result.Rejected(diagnostic);
                    case .Emitted(typed_code, typed_slots, typed_locals, typed_cells, typed_hosts, typed_roots,
                                  typed_calls, typed_bound, typed_next, typed_popped, typed_value, typed_retain,
                                  typed_marks):
                        bits = typed_code[0].payload;
                }
            } else if (value >= 0) {
                switch ParseNumber(forest, source, value) {
                    case .Invalid:
                        return Result.Rejected(Diagnose(forest, value, 0, "state value must be an integer literal"));
                    case .Number(negative, magnitude):
                        if (!Fits(negative, magnitude, declared.storage)) {
                            return Result.Rejected(Diagnose(forest, value, 0,
                                                            format_text("Numeric literal is outside the range of {}",
                                                                        TypeName(declared.storage))));
                        }
                        bits = Bits(negative, magnitude);
                }
            }
            kept: StateDecl = {name: name, id: binding.ID("symbol", format_text("{}:1:{}", identity, name)),
                               storage: declared.storage, bits: bits, node: Field(forest, member, "name")};
            kept_states.append(kept);
        } else if (Is(forest, member, "handler")) {
            if (Text(forest, source, Field(forest, member, "kind")) != "on" || Field(forest, member, "alias") >= 0 ||
                !Is(forest, Field(forest, member, "name"), "identifier")) {
                return Result.Rejected(Diagnose(forest, member, 0, "only `on Event` handlers are supported yet"));
            }
            handled_name := Text(forest, source, Field(forest, member, "name"));
            found := FindEvent(game_events, handled_name);
            if (found < 0) {
                return Result.Rejected(Diagnose(forest, member, 0, format_text("Unknown event '{}'", handled_name)));
            }
            if (!ScalarPayload(game_events[found], event_fields)) {
                return Result.Rejected(Diagnose(forest, member, 0, "events with record payloads are not supported yet"));
            }
            first := length(params);
            switch PayloadParams(forest, source, member, handled_name, game_events[found], event_fields) {
                case .Failed(diagnostic):
                    return Result.Rejected(diagnostic);
                case .Bound(added):
                    params.extend(added);
            }
            callable: Callable = {name: handled_name, package: 0, document: 0, node: member, first: first,
                                  count: game_events[found].count, result: 0, result_container: 0, result_record: -1,
                                  results: 0};
            callables.append(callable);
            handled.append(found);
        } else if (Is(forest, member, "function_declaration")) {
            // A member procedure, which the behavior's handlers call.
            name := Text(forest, source, Field(forest, member, "name"));
            switch FunctionSignature(forest, source, identity, solid, declared_types, no_names, 0, 0, member, name,
                                     length(params)) {
                case .Failed(diagnostic):
                    return Result.Rejected(diagnostic);
                case .Read(procedure, added):
                    params.extend(added);
                    callables.append(procedure);
                    handled.append(int(-1));
            }
        } else {
            return Result.Rejected(Diagnose(forest, member, 0, "unsupported behavior member"));
        }
        member = NextMember(forest, member);
    }
    document: snapshot.Document = {original_path: identity, path: identity, directory: "", key: identity,
                                   identity: identity, text: source, root: 0, syntax_root: root, header_start: 0,
                                   header_end: 0, header_line: 0, header_column: 0, header_document: 0, node_start: 0,
                                   node_count: length(forest), first_import: 0, import_count: 0, has_key: true,
                                   has_syntax: true, has_header: false};
    links: graph.Binding[] = [];
    constants: ConstDecl[] = [];
    return Assemble(forest, [document], 0, 0, [identity], [binding.ID("module", identity)], [uint64(0)], [true], links,
                    callables, params, declared_types, members, constants, natives, ports, native_ids, ops, target, abi,
                    Game.Behavior(kept_states, handled, game_events, event_fields, entity, operators, globals, makes,
                                  make_fields));
}
// The modules of a project's behavior assets, `identities[i]` holding
// `sources[i]`, as a CHIBICLO closure rooted at the first, for a host that
// takes one byte[] result; empty when stage one rejects any of them, which
// BehaviorRejection then says why.
pub CompileBehaviors :: (identities: string[], sources: string[], target: Target, abi: uint64, names: string[],
                         natives: Native[], ports: Port[], native_ids: uint64[], game_events: GameEvent[],
                         event_fields: GameEventField[], types: GameType[], type_fields: GameField[],
                         entity: uint64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
                         make_fields: int[]) -> byte[] {
    if (length(identities) == 0 || length(identities) != length(sources)) {
        return [];
    }
    ids: uint64[] = [];
    data: byte[] = [];
    starts: int[] = [];
    lengths: int[] = [];
    index: int = 0;
    while (index < length(identities)) {
        switch CompileBehavior(identities[index], sources[index], target, abi, names, natives, ports, native_ids,
                               game_events, event_fields, types, type_fields, entity, operators,
                               globals, makes, make_fields) {
            case .Rejected(diagnostic):
                return [];
            case .Compiled(module, bytes):
                ids.append(module);
                starts.append(length(data));
                lengths.append(length(bytes));
                data.extend(bytes);
        }
        index += 1;
    }
    return writer.Closure(ids[0], ids, identities, data, starts, lengths);
}
// The first of CompileBehaviors' behaviors stage one rejects, as
// "identity:line:column: message"; "" when it compiles them all.
pub BehaviorRejection :: (identities: string[], sources: string[], target: Target, abi: uint64, names: string[],
                          natives: Native[], ports: Port[], native_ids: uint64[], game_events: GameEvent[],
                          event_fields: GameEventField[], types: GameType[], type_fields: GameField[],
                          entity: uint64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
                          make_fields: int[]) -> string {
    if (length(identities) == 0 || length(identities) != length(sources)) {
        return "the behaviors' identities and sources differ in number, or there are none";
    }
    index: int = 0;
    while (index < length(identities)) {
        switch CompileBehavior(identities[index], sources[index], target, abi, names, natives, ports, native_ids,
                               game_events, event_fields, types, type_fields, entity, operators,
                               globals, makes, make_fields) {
            case .Rejected(diagnostic):
                return format_text("{}:{}:{}: {}", identities[index], diagnostic.line, diagnostic.column,
                                   diagnostic.message);
            case .Compiled(module, bytes):
                index += 1;
        }
    }
    return "";
}
package syntax_diagnostics

import strings "core:strings"

// Raw Tree-sitter facts form one complete rooted tree, including unnamed
// children. Links use -1 for absence; offsets and positions count source bytes.
pub Node :: struct {
    kind: string;
    start: int;
    end: int;
    row: int;
    column: int;
    parent: int;
    first_child: int;
    next_sibling: int;
    error: bool;
    missing: bool;
    has_error: bool;
}

pub Diagnostic :: struct {
    start: int;
    end: int;
    line: int;
    column: int;
    document: int;
    message: string;
}

pub Diagnose :: (nodes: Node[], root: int) -> Diagnostic[] {
    diagnostics: Diagnostic[] = [];
    current := root;
    while (true) {
        node := nodes[current];
        hidden := !node.error && !node.missing && node.has_error;
        child := node.first_child;
        while (hidden && child >= 0) {
            if (nodes[child].has_error) {
                hidden = false;
            }
            child = nodes[child].next_sibling;
        }

        if (node.error || node.missing || hidden) {
            message := "Unexpected syntax";
            if (node.missing) {
                message = format_text("Expected {}", node.kind);
            } else if (!node.error) {
                // Recovery can hide a missing terminator beneath this node.
                message = format_text("Missing syntax inside {}", node.kind);
            }
            diagnostic: Diagnostic = {
                start: node.start,
                end: node.end,
                line: node.row + 1,
                column: node.column + 1,
                document: 0,
                message: strings.Slice(message, 0, 191)
            };
            diagnostics.append(diagnostic);
        }

        // An ERROR already describes its descendants. Otherwise walk children
        // before siblings, climbing through parent links when a branch ends.
        if (!node.error && node.first_child >= 0) {
            current = node.first_child;
            continue;
        }
        while (nodes[current].next_sibling < 0) {
            current = nodes[current].parent;
            if (current < 0) {
                return diagnostics;
            }
        }
        current = nodes[current].next_sibling;
    }
}
package strings

// String operations compare, count and offset bytes.
// Spaces and case use ASCII. Offsets are byte offsets, and -1 means not found.

// Compiler text operations use bytes, including bytes inside UTF-8 sequences.
pub ByteLength :: (value: string) -> int {
    return text_byte_length(value);
}

// Returns -1 outside the string; valid bytes are unsigned values from 0 to 255.
// Each call measures the string, so a loop over a long one should read Bytes.
pub ByteAt :: (value: string, index: int) -> int {
    return text_byte_at(value, index);
}

// Every byte of the string, from 0 to 255, read in one pass.
pub Bytes :: (value: string) -> int[] {
    return text_bytes(value);
}

// Start clamps to the string and count clamps to its remaining bytes.
pub Slice :: (value: string, start: int, count: int) -> string {
    return text_slice(value, start, count);
}

pub Compare :: (left: string, right: string) -> int {
    leftLength := ByteLength(left);
    rightLength := ByteLength(right);
    index: int = 0;
    while (index < leftLength && index < rightLength) {
        a := ByteAt(left, index);
        b := ByteAt(right, index);
        if (a < b) {
            return -1;
        }
        if (a > b) {
            return 1;
        }
        index += 1;
    }
    if (leftLength < rightLength) {
        return -1;
    }
    if (leftLength > rightLength) {
        return 1;
    }
    return 0;
}

pub IsIdentifier :: (value: string) -> bool {
    size := ByteLength(value);
    if (size == 0) {
        return false;
    }
    index: int = 0;
    while (index < size) {
        byte := ByteAt(value, index);
        letter := byte == 95 || (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122);
        if (!letter && !(index > 0 && byte >= 48 && byte <= 57)) {
            return false;
        }
        index += 1;
    }
    return true;
}

pub BaseName :: (path: string) -> string {
    size := ByteLength(path);
    start: int = 0;
    index: int = 0;
    while (index < size) {
        if (ByteAt(path, index) == 47) {
            start = index + 1;
        }
        index += 1;
    }
    return Slice(path, start, size - start);
}

pub Contains :: (s: string, substr: string) -> bool {
    return Index(s, substr) >= 0;
}

pub ContainsAny :: (s: string, chars: string) -> bool {
    return IndexAny(s, chars) >= 0;
}

pub HasPrefix :: (s: string, prefix: string) -> bool {
    size := ByteLength(prefix);
    return ByteLength(s) >= size && Slice(s, 0, size) == prefix;
}

pub HasSuffix :: (s: string, suffix: string) -> bool {
    size := ByteLength(s);
    count := ByteLength(suffix);
    return size >= count && Slice(s, size - count, count) == suffix;
}

pub IndexByte :: (s: string, c: int) -> int {
    size := ByteLength(s);
    i: int = 0;
    while (i < size) {
        if (ByteAt(s, i) == c) {
            return i;
        }
        i += 1;
    }
    return -1;
}

pub LastIndexByte :: (s: string, c: int) -> int {
    i: int = ByteLength(s) - 1;
    while (i >= 0) {
        if (ByteAt(s, i) == c) {
            return i;
        }
        i -= 1;
    }
    return -1;
}

// Uses a 32-bit Rabin-Karp rolling hash. An empty substring is found at 0.
pub Index :: (s: string, substr: string) -> int {
    n := ByteLength(substr);
    size := ByteLength(s);
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return IndexByte(s, ByteAt(substr, 0));
    }
    if (n == size) {
        if (s == substr) {
            return 0;
        }
        return -1;
    }
    if (n > size) {
        return -1;
    }
    hash: int64 = 0;
    pow: int64 = 1;
    h: int64 = 0;
    i: int = 0;
    while (i < n) {
        hash = (hash * 16777619 + ByteAt(substr, i)) & 0xFFFFFFFF;
        pow = (pow * 16777619) & 0xFFFFFFFF;
        h = (h * 16777619 + ByteAt(s, i)) & 0xFFFFFFFF;
        i += 1;
    }
    if (h == hash && Slice(s, 0, n) == substr) {
        return 0;
    }
    while (i < size) {
        h = (h * 16777619 + ByteAt(s, i) - pow * ByteAt(s, i - n)) & 0xFFFFFFFF;
        i += 1;
        if (h == hash && Slice(s, i - n, n) == substr) {
            return i - n;
        }
    }
    return -1;
}

// Index's search from the end. An empty substring is found at the length of s.
pub LastIndex :: (s: string, substr: string) -> int {
    n := ByteLength(substr);
    size := ByteLength(s);
    if (n == 0) {
        return size;
    }
    if (n == 1) {
        return LastIndexByte(s, ByteAt(substr, 0));
    }
    if (n == size) {
        if (s == substr) {
            return 0;
        }
        return -1;
    }
    if (n > size) {
        return -1;
    }
    hash: int64 = 0;
    pow: int64 = 1;
    h: int64 = 0;
    i: int = 0;
    while (i < n) {
        hash = (hash * 16777619 + ByteAt(substr, n - 1 - i)) & 0xFFFFFFFF;
        pow = (pow * 16777619) & 0xFFFFFFFF;
        h = (h * 16777619 + ByteAt(s, size - 1 - i)) & 0xFFFFFFFF;
        i += 1;
    }
    i = size - n;
    if (h == hash && Slice(s, i, n) == substr) {
        return i;
    }
    i -= 1;
    while (i >= 0) {
        h = (h * 16777619 + ByteAt(s, i) - pow * ByteAt(s, i + n)) & 0xFFFFFFFF;
        if (h == hash && Slice(s, i, n) == substr) {
            return i;
        }
        i -= 1;
    }
    return -1;
}

// The offset of the first byte of s that is any byte of chars.
pub IndexAny :: (s: string, chars: string) -> int {
    size := ByteLength(s);
    i: int = 0;
    while (i < size) {
        if (IndexByte(chars, ByteAt(s, i)) >= 0) {
            return i;
        }
        i += 1;
    }
    return -1;
}

pub LastIndexAny :: (s: string, chars: string) -> int {
    i: int = ByteLength(s) - 1;
    while (i >= 0) {
        if (IndexByte(chars, ByteAt(s, i)) >= 0) {
            return i;
        }
        i -= 1;
    }
    return -1;
}

// Non-overlapping occurrences. An empty substring occurs at every byte
// boundary, one more than the byte length.
pub Count :: (s: string, substr: string) -> int {
    n := ByteLength(substr);
    if (n == 0) {
        return ByteLength(s) + 1;
    }
    total: int = 0;
    if (n == 1) {
        c := ByteAt(substr, 0);
        size := ByteLength(s);
        i: int = 0;
        while (i < size) {
            if (ByteAt(s, i) == c) {
                total += 1;
            }
            i += 1;
        }
        return total;
    }
    rest: string = s;
    i := Index(rest, substr);
    while (i >= 0) {
        total += 1;
        rest = Slice(rest, i + n, ByteLength(rest));
        i = Index(rest, substr);
    }
    return total;
}

// Everything before the first c, or all of s when c is absent.
pub TruncateToByte :: (s: string, c: int) -> string {
    n := IndexByte(s, c);
    if (n < 0) {
        return s;
    }
    return Slice(s, 0, n);
}

// ASCII letters match in either case; every other byte must be equal.
pub EqualFold :: (u: string, v: string) -> bool {
    size := ByteLength(u);
    if (size != ByteLength(v)) {
        return false;
    }
    i: int = 0;
    while (i < size) {
        sr := ByteAt(u, i);
        tr := ByteAt(v, i);
        if (tr < sr) {
            swap := sr;
            sr = tr;
            tr = swap;
        }
        if (tr != sr && !(sr >= 65 && sr <= 90 && tr == sr + 32)) {
            return false;
        }
        i += 1;
    }
    return true;
}

// ASCII letters only; other bytes, including those of UTF-8 sequences, stay.
pub ToLower :: (s: string) -> string {
    size := ByteLength(s);
    result: string = "";
    start: int = 0;
    i: int = 0;
    while (i < size) {
        c := ByteAt(s, i);
        if (c >= 65 && c <= 90) {
            letter := Slice("abcdefghijklmnopqrstuvwxyz", c - 65, 1);
            result = format_text("{}{}{}", result, Slice(s, start, i - start), letter);
            start = i + 1;
        }
        i += 1;
    }
    if (start == 0) {
        return s;
    }
    return format_text("{}{}", result, Slice(s, start, size - start));
}

pub ToUpper :: (s: string) -> string {
    size := ByteLength(s);
    result: string = "";
    start: int = 0;
    i: int = 0;
    while (i < size) {
        c := ByteAt(s, i);
        if (c >= 97 && c <= 122) {
            letter := Slice("ABCDEFGHIJKLMNOPQRSTUVWXYZ", c - 97, 1);
            result = format_text("{}{}{}", result, Slice(s, start, i - start), letter);
            start = i + 1;
        }
        i += 1;
    }
    if (start == 0) {
        return s;
    }
    return format_text("{}{}", result, Slice(s, start, size - start));
}

// Tab, line feed, vertical tab, form feed, carriage return and space.
pub IsAsciiSpace :: (c: int) -> bool {
    return c == 32 || (c >= 9 && c <= 13);
}

// Removes the leading bytes that are bytes of cutset.
pub TrimLeft :: (s: string, cutset: string) -> string {
    size := ByteLength(s);
    i: int = 0;
    while (i < size && IndexByte(cutset, ByteAt(s, i)) >= 0) {
        i += 1;
    }
    return Slice(s, i, size - i);
}

pub TrimRight :: (s: string, cutset: string) -> string {
    i := ByteLength(s);
    while (i > 0 && IndexByte(cutset, ByteAt(s, i - 1)) >= 0) {
        i -= 1;
    }
    return Slice(s, 0, i);
}

pub Trim :: (s: string, cutset: string) -> string {
    return TrimRight(TrimLeft(s, cutset), cutset);
}

pub TrimLeftSpace :: (s: string) -> string {
    size := ByteLength(s);
    i: int = 0;
    while (i < size && IsAsciiSpace(ByteAt(s, i))) {
        i += 1;
    }
    return Slice(s, i, size - i);
}

pub TrimRightSpace :: (s: string) -> string {
    i := ByteLength(s);
    while (i > 0 && IsAsciiSpace(ByteAt(s, i - 1))) {
        i -= 1;
    }
    return Slice(s, 0, i);
}

pub TrimSpace :: (s: string) -> string {
    return TrimRightSpace(TrimLeftSpace(s));
}

pub TrimPrefix :: (s: string, prefix: string) -> string {
    if (HasPrefix(s, prefix)) {
        return Slice(s, ByteLength(prefix), ByteLength(s));
    }
    return s;
}

pub TrimSuffix :: (s: string, suffix: string) -> string {
    if (HasSuffix(s, suffix)) {
        return Slice(s, 0, ByteLength(s) - ByteLength(suffix));
    }
    return s;
}

// The count bytes from offset, or all bytes from offset when count is below 1.
// An offset outside s keeps all of s. A count past the end keeps the rest.
pub Cut :: (s: string, offset: int, count: int) -> string {
    rest: string = s;
    size := ByteLength(s);
    if (offset >= 0 && offset < size) {
        rest = Slice(s, offset, size - offset);
    }
    if (count < 1 || count >= ByteLength(rest)) {
        return rest;
    }
    return Slice(rest, 0, count);
}

// Produces at most n parts, or every part when n is negative.
// The last part holds the rest of s. Each other part keeps the first keep
// bytes of the separator after it. An empty separator splits s into bytes.
SplitKeeping :: (s: string, sep: string, keep: int, n: int) -> string[] {
    parts: string[] = [];
    size := ByteLength(sep);
    limit := n;
    if (size == 0) {
        count := ByteLength(s);
        if (limit < 0 || limit > count) {
            limit = count;
        }
        while (length(parts) < limit - 1) {
            parts.append(Slice(s, length(parts), 1));
        }
        if (limit > 0) {
            parts.append(Slice(s, limit - 1, count));
        }
        return parts;
    }
    if (limit == 0) {
        return parts;
    }
    if (limit < 0) {
        limit = Count(s, sep) + 1;
    }
    rest: string = s;
    while (length(parts) < limit - 1) {
        m := Index(rest, sep);
        if (m < 0) {
            break;
        }
        parts.append(Slice(rest, 0, m + keep));
        rest = Slice(rest, m + size, ByteLength(rest));
    }
    parts.append(rest);
    return parts;
}

pub Split :: (s: string, sep: string) -> string[] {
    return SplitKeeping(s, sep, 0, -1);
}

pub SplitN :: (s: string, sep: string, n: int) -> string[] {
    return SplitKeeping(s, sep, 0, n);
}

pub SplitAfter :: (s: string, sep: string) -> string[] {
    return SplitKeeping(s, sep, ByteLength(sep), -1);
}

pub SplitAfterN :: (s: string, sep: string, n: int) -> string[] {
    return SplitKeeping(s, sep, ByteLength(sep), n);
}

// Splits at line feeds; a line that ends in a carriage return loses it.
SplitLinesKeeping :: (s: string, keep: int, n: int) -> string[] {
    lines: string[] = [];
    for (line in SplitKeeping(s, "\n", keep, n)) {
        lines.append(TrimSuffix(line, "\r"));
    }
    return lines;
}

pub SplitLines :: (s: string) -> string[] {
    return SplitLinesKeeping(s, 0, -1);
}

pub SplitLinesN :: (s: string, n: int) -> string[] {
    return SplitLinesKeeping(s, 0, n);
}

pub SplitLinesAfter :: (s: string) -> string[] {
    return SplitLinesKeeping(s, 1, -1);
}

pub SplitLinesAfterN :: (s: string, n: int) -> string[] {
    return SplitLinesKeeping(s, 1, n);
}

// The runs of bytes between ASCII spaces.
pub Fields :: (s: string) -> string[] {
    fields: string[] = [];
    size := ByteLength(s);
    start: int = -1;
    i: int = 0;
    while (i < size) {
        if (IsAsciiSpace(ByteAt(s, i))) {
            if (start >= 0) {
                fields.append(Slice(s, start, i - start));
                start = -1;
            }
        } else if (start < 0) {
            start = i;
        }
        i += 1;
    }
    if (start >= 0) {
        fields.append(Slice(s, start, size - start));
    }
    return fields;
}

pub Join :: (a: string[], sep: string) -> string {
    if (length(a) == 0) {
        return "";
    }
    result: string = a[0];
    i: int = 1;
    while (i < length(a)) {
        result = format_text("{}{}{}", result, sep, a[i]);
        i += 1;
    }
    return result;
}

pub Concatenate :: (a: string[]) -> string {
    return Join(a, "");
}

// Doubles the result until it reaches the requested length.
// A count below 1 gives an empty string.
pub Repeat :: (s: string, count: int) -> string {
    if (count < 1) {
        return "";
    }
    total: int64 = int64(ByteLength(s)) * count;
    result: string = s;
    while (ByteLength(result) < total) {
        rest: int64 = total - ByteLength(result);
        result = format_text("{}{}", result, Slice(result, 0, int(clamp: rest)));
    }
    return result;
}

// Replaces the first n non-overlapping matches of old, or all of them when n is
// negative. An empty old matches at every byte boundary.
pub Replace :: (s: string, old: string, new: string, n: int) -> string {
    if (old == new || n == 0) {
        return s;
    }
    matches := Count(s, old);
    if (matches == 0) {
        return s;
    }
    if (n > 0 && n < matches) {
        matches = n;
    }
    size := ByteLength(s);
    width := ByteLength(old);
    result: string = "";
    start: int = 0;
    i: int = 0;
    while (i < matches) {
        j := start;
        if (width == 0) {
            if (i > 0) {
                j += 1;
            }
        } else {
            j += Index(Slice(s, start, size - start), old);
        }
        result = format_text("{}{}{}", result, Slice(s, start, j - start), new);
        start = j + width;
        i += 1;
    }
    return format_text("{}{}", result, Slice(s, start, size - start));
}

pub ReplaceAll :: (s: string, old: string, new: string) -> string {
    return Replace(s, old, new, -1);
}

pub Remove :: (s: string, key: string, n: int) -> string {
    return Replace(s, key, "", n);
}

pub RemoveAll :: (s: string, key: string) -> string {
    return Remove(s, key, -1);
}

pub Parts :: struct {
    head: string;
    match: string;
    tail: string;
}

// The text before the first sep, sep and the text after it; when sep is
// absent, head is all of str and the others are empty.
pub Partition :: (str: string, sep: string) -> Parts {
    i := Index(str, sep);
    if (i < 0) {
        return {head: str, match: "", tail: ""};
    }
    size := ByteLength(sep);
    return {head: Slice(str, 0, i), match: sep, tail: Slice(str, i + size, ByteLength(str))};
}
package source_snapshot

