        file += 1;
    }

    graphImports: graph.Import[] = [];
    file = 0;
    while (file < length(documents)) {
        document := documents[file];
        document.first_import = length(imports);
        documents[file] = document;
        index: int = 0;
        while (index < pendingCounts[file]) {
            if (length(imports) >= 4096) {
                return Reject(Diagnostic(FileRange(file), "Package import limit exceeded"), documents, nodes, imports);
            }
            imported := pending[pendingStarts[file] + index];
            request: routes.ImportInput = {
                directory: document.directory, root: document.root,
                literal: strings.Slice(document.text, imported.path_start, imported.path_end - imported.path_start),
                start: imported.path_start, end: imported.path_end,
                line: imported.path_line, column: imported.path_column, document: file
            };
            routed := routes.ImportRoute(roots, request);
            switch routed {
                case .Rejected(diagnostic):
                    return Reject(diagnostic, documents, nodes, imports);
                case .Accepted(directory):
                    imports.append(Resolved(imported, directory));
                    graphImport: graph.Import = {file: imported.file, directory: directory,
                                                 alias: imported.alias, explicit_alias: imported.explicit_alias};
                    graphImports.append(graphImport);
            }
            document.import_count += 1;
            documents[file] = document;
            index += 1;
        }
        file += 1;
    }
    built := graph.Build(files, graphImports);
    switch built {
        case .Rejected(error, cycle):
            return GraphFailure(error, cycle, documents, nodes, imports);
        case .Accepted(packages, members, filePackages, order, edges, bindings):
            return Result.Accepted(roots, documents, nodes, imports, built);
    }
}
package compiler_syntax

import syntax "project:syntax_diagnostics"

Tree :: union {
    Parsed(nodes: syntax.Node[], fields: string[], is_named: bool[], is_extra: bool[], root: int)
}

// The private parser returns aligned columns of public tree facts. An explicit
// read-only count keeps the ordinary record-array builder's loop-bound proof.
Assemble :: (count: int, kinds: string[], starts: int[], ends: int[],
             rows: int[], columns: int[], parents: int[],
             first_children: int[], next_siblings: int[],
             errors: bool[], missing: bool[], has_errors: bool[]) -> syntax.Node[] {
    nodes: syntax.Node[] = [];
    index: int = 0;
    while (index < count) {
        node: syntax.Node = {
            kind: kinds[index], start: starts[index], end: ends[index],
            row: rows[index], column: columns[index], parent: parents[index],
            first_child: first_children[index], next_sibling: next_siblings[index],
            error: errors[index], missing: missing[index], has_error: has_errors[index]
        };
        nodes.append(node);
        index += 1;
    }
    return nodes;
}

pub Parse :: (text: string) -> Tree {
    raw := compiler_syntax_parse(text);
    nodes := Assemble(length(raw.kinds), raw.kinds, raw.starts, raw.ends,
                      raw.rows, raw.columns, raw.parents, raw.first_children,
                      raw.next_siblings, raw.errors, raw.missing, raw.has_errors);
    return Tree.Parsed(nodes, raw.fields, raw.is_named, raw.is_extra, raw.root);
}
package package_routes

import paths "project:package_paths"
import strings "core:strings"
import syntax "project:syntax_diagnostics"

pub Collection :: struct {
    name: string;
    path: string;
    has_name: bool;
    has_path: bool;
}
pub Root :: struct {
    name: string;
    path: string;
}
File :: struct {
    path: string;
    directory: string;
    key: string;
    identity: string;
    root: int;
}
pub ImportInput :: struct {
    directory: string;
    literal: string;
    root: int;
    start: int;
    end: int;
    line: int;
    column: int;
    document: int;
}
pub RootResult :: union {
    Accepted(roots: Root[]) | Rejected(diagnostic: syntax.Diagnostic)
}
pub FileResult :: union {
    Accepted(file: File) | Rejected(diagnostic: syntax.Diagnostic)
}
pub ImportResult :: union {
    Accepted(directory: string) | Rejected(diagnostic: syntax.Diagnostic)
}

FileError :: (message: string, document: int) -> syntax.Diagnostic {
    return {start: 0, end: 0, line: 1, column: 1, document: document, message: message};
}

ImportError :: (message: string, request: ImportInput) -> ImportResult {
    return ImportResult.Rejected({start: request.start, end: request.end,
                                  line: request.line, column: request.column,
                                  document: request.document, message: message});
}

AddRoot :: (roots: Root[], item: Collection) -> RootResult {
    if (!item.has_name || !paths.Bounded(item.name) || !strings.IsIdentifier(item.name)) {
        return RootResult.Rejected(FileError("Invalid collection name", -1));
    }
    normalized := paths.Normalize({base: "", path: item.path, floor: "",
                                   has_base: false, has_path: item.has_path, has_floor: false});
    switch normalized {
        case .Invalid:
            return RootResult.Rejected(FileError("Invalid absolute collection root", -1));
        case .Normalized(path):
            // Name and path checks interleave for each earlier root. The first
            // conflicting earlier root determines the diagnostic.
            for (root in roots) {
                if (root.name == item.name) {
                    return RootResult.Rejected(FileError("Duplicate collection name", -1));
                }
                if (root.path == path) {
                    return RootResult.Rejected(FileError("Duplicate collection root", -1));
                }
            }
            root: Root = {name: item.name, path: path};
            return RootResult.Accepted(append(roots, root));
    }
}

pub RootSet :: (project: string, has_project: bool, collections: Collection[]) -> RootResult {
    // Snapshot option validation already bounds explicit collections to 255.
    roots: Root[] = [];
    first := AddRoot(roots, {name: "project", path: project, has_name: true, has_path: has_project});
    switch first {
        case .Rejected(diagnostic):
            return RootResult.Rejected(diagnostic);
        case .Accepted(items):
            roots = items;
    }
    for (item in collections) {
        added := AddRoot(roots, item);
        switch added {
            case .Rejected(diagnostic):
                return RootResult.Rejected(diagnostic);
            case .Accepted(items):
                roots = items;
        }
    }
    return RootResult.Accepted(roots);
}

// Roots are the nonempty canonical result of RootSet. Inputs use lexical paths;
// neither routing function inspects the filesystem or proves containment there.
OwningRoot :: (roots: Root[], directory: string) -> int {
    selected: int = -1;
    index: int = 0;
    while (index < length(roots)) {
        if (paths.Within(roots[index].path, directory)) {
            if (selected < 0 || strings.ByteLength(roots[index].path) > strings.ByteLength(roots[selected].path)) {
                selected = index;
            }
        }
        index += 1;
    }
    return selected;
}

Relative :: (root: string, path: string) -> string {
    offset := strings.ByteLength(root);
    if (root != "/" && strings.ByteAt(path, offset) == 47) {
        offset += 1;
    }
    return strings.Slice(path, offset, strings.ByteLength(path) - offset);
}

Key :: (root: Root, path: string) -> string {
    return format_text("{}:{}", root.name, Relative(root.path, path));
}

pub FileRoute :: (roots: Root[], path: string, has_path: bool, document: int) -> FileResult {
    if (!has_path || !paths.Bounded(path) || strings.ByteLength(path) == 0) {
        return FileResult.Rejected(FileError("Invalid package file path", document));
    }
    normalized := paths.Normalize({base: roots[0].path, path: path, floor: roots[0].path,
                                   has_base: true, has_path: true,
                                   has_floor: strings.ByteAt(path, 0) != 47});
    switch normalized {
        case .Invalid:
            return FileResult.Rejected(FileError("Invalid package file path or root escape", document));
        case .Normalized(canonical):
            if (canonical == "/") {
                return FileResult.Rejected(FileError("Invalid package file path or root escape", document));
            }
            slash := strings.LastIndexByte(canonical, 47);
            directory := "/";
            if (slash > 0) {
                directory = strings.Slice(canonical, 0, slash);
            }
            root := OwningRoot(roots, directory);
            if (root < 0) {
                return FileResult.Rejected(FileError("Package file is outside the configured roots", document));
            }
            tail := Relative(roots[root].path, directory);
            if (strings.Count(tail, "/") >= 16) {
                return FileResult.Rejected(FileError("Package path nesting exceeds the supported depth", document));
            }
            return FileResult.Accepted({path: canonical, directory: directory,
                                        key: Key(roots[root], canonical),
                                        identity: Key(roots[root], directory), root: root});
    }
}

// The foreign primitive supplies JSON decoding facts only. Collection lookup,
// path validity, root ownership and diagnostics remain authored policy.
pub ImportRoute :: (roots: Root[], request: ImportInput) -> ImportResult {
    decoded := compiler_json_string(request.literal);
    if (!decoded.valid || strings.IndexByte(decoded.value, 0) >= 0) {
        return ImportError("Invalid import string or embedded NUL", request);
    }
    path := decoded.value;
    base := request.directory;
    root := request.root;
    colon := strings.IndexByte(path, 58);
    if (colon >= 0) {
        root = -1;
        name := strings.Slice(path, 0, colon);
        index: int = 0;
        while (index < length(roots)) {
            if (roots[index].name == name) {
                root = index;
                break;
            }
            index += 1;
        }
        if (root < 0) {
            return ImportError("Unknown import collection", request);
        }
        path = strings.Slice(path, colon + 1, strings.ByteLength(path) - colon - 1);
        base = roots[root].path;
    }
    if ((colon < 0 && strings.ByteLength(path) == 0) || strings.ByteAt(path, 0) == 47 || !paths.Bounded(path)) {
        return ImportError("Invalid import path", request);
    }
    normalized := paths.Normalize({base: base, path: path, floor: roots[root].path,
                                   has_base: true, has_path: true, has_floor: true});
    switch normalized {
        case .Invalid:
            return ImportError("Import path escapes its collection root or exceeds the path limit", request);
        case .Normalized(directory):
            return ImportResult.Accepted(directory);
    }
}
