pub FindName :: (environment: Environment, scope: int, name: string) -> int {
    switch environment {
        case .Tables(scopes, symbols, functions, ids, keys):
            current := scope;
            while (current >= 0) {
                index := length(symbols) - 1;
                while (index >= 0) {
                    symbol := symbols[index];
                    if (symbol.scope == current && symbol.kind != FunctionKind &&
                        symbol.kind != MacroKind && symbol.name == name) {
                        return index;
                    }
                    index -= 1;
                }
                current = scopes[current].parent;
            }
            return -1;
    }
