        wide := int64(value);
        rest := uint64(wrap: wide << 1) ^ uint64(wrap: wide >> 63);
        while ((rest >> 7) != 0) {
            bytes.append(byte(wrap: rest | 128));
            rest = rest >> 7;
        }
        bytes.append(byte(wrap: rest));
    }
    return bytes;
}
